\section{Gradient Analysis}
\label{sec:grad_info}

Our proposed initialization method requires initialization of $\BA^{i}$, the down matrices and  $\BB^{i}$, the up matrices separately. The gradients of $\BA^{i}$ and $\BB^{i}$ with respect to the task loss $L$ is given as $\frac{\partial L}{\partial \BA^{i}} = \BB^{iT} \left( \frac{\partial L}{\partial \BY} \right) \BX^{iT}_{tar}$, where $\BY$ is the output of the LoRA layer. Similarly, the gradient of the task loss $L$ with respect to $\BB^{i}$ is given as $\frac{\partial L}{\partial \BB^{i}} =\left( \frac{\partial L}{\partial \BY} \right) \BX^{iT}_{tar}  \BA^{iT}$. From the expression, it is clear that the initial gradients would depend on the initial values of $\BA^{i}$ and $\BB^{i}$. For random initialization, $\frac{\partial L}{\partial \BA^{i}}$ would be zero as $\BB^{i}$ is initialized to $\mathbf{0}$. This can slow down the convergence. For data-driven initialization like EVA, $\BA^{i}$ is initialized from data and it is likely to assist $\frac{\partial L}{\partial \BB^{i}}$ in the convergence. However, still $\BB^{i}$ is initialized to 0 and hence the initial gradients of $\frac{\partial L}{\partial \BA^{i}}$ would be zero and hence affecting convergence. For our proposed method, the initial values of $\BB^{i}$ and $\BA^{i}$ are non-zero and both depend on the principal components of the input activations $\BX^{i}_{tar}$. Consequently, both of the gradients have a dependency on $\BX^{i}_{tar}$ beyond first order and hence we expect faster convergence compared to EVA.  


\section{Competitive Low Rank Adaptors as Constraints}

The first example of \textbf{Native LoRA} is as follows:
\begin{align}\label{eq:type1}
&\BF_1(\BX^{i}_{src}, \BX^{i}_{tar}, \BW^{i}_{src}, \BW^{i}_{tar}) = \mathbf{0}  \\
&\BW^{i}_{tar}  - \BW^{i}_{src} = \mathbf{0} \implies \Delta \BW^{i} = \mathbf{0} \\
&\implies \BB^{i} = \mathbf{0}, \BA^{i} \sim \mathcal{N}(\mathbf{0}, \BI) 
\end{align}
\textbf{PISSA} can be expressed as: 
\begin{align}\label{eq:type2}
&\BF_1(\BX^{i}_{src}, \BX^{i}_{tar}, \BW^{i}_{src}, \BW^{i}_{tar}) = \mathbf{0}\\
&\BW^{i}_{tar}  - 2\BW^{i}_{src} = \mathbf{0} 
\implies \Delta \BW^{i} = \BW^{i}_{src} \\
&\Delta\BW^{i} = \BU^{i} \BS^{i} \BV^{i} \implies \BB^{i} = \BU^{i}[::r] \BS^{i}[:r]^{0.5} , \\
&\BA^{i} = \BS^{i}[:r]^{0.5} \BV^{i}[:r:]  
\end{align}
\textbf{OLORA} can be expressed as: 
% \begin{align}\label{eq:type3}
% \BF_1(\BX^{i}_{src}, \BX^{i}_{tar}, \BW^{i}_{src}, \BW^{i}_{tar}) = \mathbf{0}\\
% \BW^{i}_{tar}  - 2\BW^{i}_{src} = \mathbf{0} 
% \implies \Delta \BW^{i} = \BW^{i}_{src} \\
% \Delta\BW^{i} = \BQ^{i}[::r] \BR^{i}[:r:] \implies \BB^{i} = \BQ^{i}[::r]  , \BA^{i} = \BR^{i}[:r:] 
% \end{align}
\begin{align}\label{eq:type3}
&\BF_1(\BX^{i}_{src}, \BX^{i}_{tar}, \BW^{i}_{src}, \BW^{i}_{tar}) = \mathbf{0} \\
&\BW^{i}_{tar}  - 2\BW^{i}_{src} = \mathbf{0} 
\implies \Delta \BW^{i} = \BW^{i}_{src} \\
&\Delta\BW^{i} = \BQ^{i}[::r] \BR^{i}[:r:] \implies \BB^{i} = \BQ^{i}[::r]  , \\
&\BA^{i} = \BR^{i}[:r:] 
\end{align}
\textbf{CORDA} can be expressed as: 
\begin{align}\label{eq:type4}
&\BF_1(\BX^{i}_{src}, \BX^{i}_{tar}, \BW^{i}_{src}, \BW^{i}_{tar}) = \mathbf{0}\\
&(\BW^{i}_{tar}  - \BW^{i}_{src})\BX^{i}_{tar}\BX^{iT}_{tar} - \text{SVD}((\BW^{i}_{tar})\BX^{i}_{tar}\BX^{iT}_{tar}) = \mathbf{0} \\
&\implies \Delta \BW^{i}\BC^{i}_{tar} = \text{SVD}(\BW^{i}_{tar}\BC^{i}_{tar}) \\
&\implies  \Delta \BW^{i} = \text{SVD}(\BW^{i}_{tar}\BC^{i}_{tar})\BC{^{i}_{tar}}^{-1}  \\
&\implies \BA^{i} = (\BS^{i})^{0.5}[:r](\BV^{i}\BC^{i}_{tar})^{-1}[:r:] \\
&\implies \BB^{i} = \BU^{i}[::r] (\BS^{i})^{0.5}[:r]
\end{align}
\textbf{EVA} can be expressed as: 
\begin{align}\label{eq:type5}
&\BF_1(\BX^{i}_{src}, \BX^{i}_{tar}, \BW^{i}_{src}, \BW^{i}_{tar}) = \mathbf{0}\\
&\BA^{i} = \BV^{i}[:r:] \quad \text{where} \\
&\BU^{i}[::r],\BS^{i}[:r],\BV^{i}[:r:] = \text{SVD}(\BX^{i}_{tar})  
\end{align}

