\section{PRELIMINARIES}
\subsection{Notation}
In this paper, random variables are denoted using capital letters (say $X$), their sample values with respective lowercase letters ($x$), and their alphabet with respective calligraphic letters ($\mathcal{X}$). The set of real numbers is denoted by $\mathbb{R}$. The alphabet, $\mathcal{X}$, can be finite, infinite, or a continuum, like an interval $[a,b]\subset \mathbb R$. The  2-dimensional jointly Gaussian distribution with mean $\begin{bmatrix}
    t_1 & t_2
\end{bmatrix}'$ and respective variances $\sigma_1^2,\sigma_2^2$ with a correlation $\rho$ is denoted by  $\mathcal{N}\bigg (\begin{bmatrix}t_1\\ t_2    \end{bmatrix},\sigma_1^2\begin{bmatrix}
        1 &  \rho r \\  \rho r & r^2 
    \end{bmatrix}\bigg ), 0\leq \rho <1, r = \sigma_{2}/\sigma_1$, $t_1,t_2\in \mathbb{R}$, respectively.  The expectation operator is written as $\mathbb{E}\{\cdot\}$. The operator $|\cdot |$ denotes  the cardinality of the set. 




\subsection{Problem Formulation}
Consider the following communication problem: an encoder observes realizations of the two sources $X\in \mathcal{X}\subseteq  [a_X,b_X],\theta \in \mathcal{T}\subseteq [a_{\theta},b_{\theta}]$, $a_X,b_X,a_{\theta},b_{\theta} \in \mathbb{R}$ with joint probability distribution $(X,\theta)\sim f(x,\theta)$, and maps $(X,\theta)$ to a message $Z\in \mathcal{Z}$, where $\mathcal{Z}$ is a set of  messages using a  mapping $Q:(\mathcal{X} \times \mathcal{T}) \rightarrow Z$. After receiving the message $Z$, the decoder applies a mapping $\phi:\mathcal{Z}\rightarrow \mathcal{Y}$ on the message $Z$ and takes an action $Y=\phi(Z) $. An eavesdropper observes the message $Y$ and estimates $\theta$ as $\hat{\theta} = \gamma(\theta)$.

The encoder, decoder, and eavesdropper minimize their respective objectives $$D_E=\mathbb{E}\{(X+\theta-Y)^2\} $$ such that $$\mathbb{E}\{(\theta - \hat{\theta})^2\}\geq C,$$ $C\in \mathbb{R}$,   $$D_D=\mathbb{E}\{(X-Y)^2\},$$ and $$D_{\theta} =\mathbb{E}\{(\theta - \hat{\theta})^2\}.$$ The encoder designs $Q$ \textit{ex-ante}, i.e., without the knowledge of the realization of $(X,\theta)$, using only the objectives $D_E$, $D_D$, $D_{\theta}$, and the statistics of the source $f(\cdot,\cdot)$. The objectives ($D_E$,  $D_D$, $D_{\theta}$), the shared prior ($f$), and the mapping ($Q$) are known to the encoder, decoder, and the eavesdropper. The problem is to design $Q$ for the equilibrium, i.e., the encoder minimizes its distortion if used with a corresponding decoder that minimizes its own distortion. This communication setting is given in Fig. \ref{fig:comm_diag}. Since the encoder chooses the mapping $Q$ first, followed by the decoder choosing the quantization representative levels ($\mathbf{y}$), we look for a Stackelberg equilibrium. 


\section{MAIN RESULTS}
We assume a jointly Gaussian source $$(X,\theta)\sim \mathcal{N}\bigg(\begin{bmatrix}
    0 \\ 0
\end{bmatrix},\sigma_X^2 \begin{bmatrix}
    1 & \rho r \\ \rho r & r^2
\end{bmatrix}\bigg).$$ We consider two problem settings: one without quantization, and one with quantization. In the first case, we obtain closed form expressions for the mappings under some assumptions. In the second case, we provide an algorithm to compute the optimal quantizers.
\subsection{No quantization}



We make the following assumption on the mappings:
\begin{assumption}
    $Q(x,\theta) = x+\alpha \theta$, $\phi = \kappa y, \gamma= \nu y$, $\alpha,\kappa, \nu\in \mathbb{R}$.
\end{assumption}
We present the optimal mapping under these linearity assumptions below. The proof is
in Appendix \ref{appdx:mapping}.
\begin{theorem}
    The optimal mapping is given by 
    \begin{align}
    \alpha^* = \frac{ - (1+\lambda r^2)+ \sqrt{ (1+\lambda r^2)^2 - 4r(\rho + r)(\lambda \rho r -1) }  }{ 2r(\rho +r) }  \nonumber .
\end{align}
\label{thm:alpha}
\end{theorem}



\begin{remark}
    Although we obtain the solution for the general case of correlation $\rho$, in our numerical results we focus on $\rho = 0$ setting.
\end{remark}
As $\lambda \rightarrow \infty$, $\alpha = -\rho/r$, i.e., the encoder optimally estimates $\theta$ and removes this to make the term $(X+\alpha \theta)$ independent of $\theta$. For $\rho = 0$, as $\lambda \rightarrow \infty$, the encoder sends $X$  (fully-revealing).

The following theorem shows that the decoder may prefer the existence of an adversary. The proof is shown in Appendix \ref{appdx:decdistdecreasewithlambda}.
\begin{theorem}
    For a zero mean jointly Gaussian source with correlation $\rho = 0$, the decoder distortion decreases with respect to $\lambda$. 
    \label{thm:Ddec}
\end{theorem}


\begin{remark}
    While in the classical communication setup the existence of an adversary is against the objective of the decoder, in the strategic problem setting, the decoder benefits from the adversary. 
\end{remark}

For $\rho =0$, $\alpha\geq 0,$ $$ \frac{\partial \kappa}{\partial \alpha}\leq 0,$$ i.e., as $\alpha $ increases, $\kappa $ decreases. 
Since $$ \frac{\partial \alpha}{\partial \lambda}<0,$$ $\alpha $ decreases with $\lambda$, i.e., $\kappa$ increases with $\lambda$.  

For $\lambda \rightarrow \infty$, $\alpha = 0$, $\kappa =1$ (the decoder accepts the message as it is because the encoder is fully revealing). 

\subsection{With quantization}
Consider the problem setting where the cardinality of the message space is constrained, $|\mathcal{Z}|\leq M$. The encoder's mapping $Q$ is a non-injective mapping. The set $\mathcal{X}$ is divided into mutually exclusive and exhaustive sets parameterized by the realization of $\theta$ as $\mathcal{V}_{\theta,1},\mathcal{V}_{\theta,2},\ldots,\mathcal{V}_{\theta,M}$. The $m-$th quantization region is denoted by $\mathcal{V}_{:,m}=\{\mathcal{V}_{\theta,m},\forall \theta \in \mathcal{T}\}$. 
The encoder chooses the set of quantizers $Q=\{q_{\theta},\theta \in \mathcal{T}\}$  to minimize its distortion,
\begin{align}
    D_E& = \mathbb{E}\{(X+\theta - Y)^2\} - \lambda \mathbb{E}\{ (\theta - \hat{\theta})^2 \} \nonumber
    \\& =  \underset{m=1}{\overset{M}{\sum}} \underset{\theta\in \mathcal{T}}{\int} \underset{ x\in \mathcal{V}_{\theta,m} }{\int} (x+\theta - y_m)^2 \mathrm d  F(x,\theta) \nonumber
    \\& \quad -  \underset{m=1}{\overset{M}{\sum}} \underset{\theta\in \mathcal{T}}{\int} \underset{ x\in \mathcal{V}_{\theta,m} }{\int}\lambda (\theta - \hat{\theta}_m)^2\mathrm d  F(x,\theta), \label{eqn:DE}
\end{align}
where $\lambda$ is the Lagrangian parameter, and the optimal reconstruction points $y_m^*$ are determined by the decoder as a best response to $Q$ to minimize its distortion, 
\begin{align}
    y_m^*& = \underset{y \in \mathcal{Y}}{\argmin}\underset{m=1}{\overset{M}{\sum}} \mathbb{E}\{(X-y)^2|x\in \mathcal{V}_{:,m}\}\nonumber
    \\& = \frac{\underset{\theta\in \mathcal{T}}{\int} \underset{x \in \mathcal{V}_{\theta,m}}{\int} x \mathrm d  F(x,\theta) }{\underset{\theta\in \mathcal{T}}{\int} \underset{x \in \mathcal{V}_{\theta,m}}{\int} \mathrm d  F(x,\theta)  },\label{eqn:yval}
\end{align}
and the optimal estimates $\hat{\theta}_m$ are determined by the eavesdropper to minimize its distortion,
\begin{align}
    \hat{\theta}_m = \frac{  \underset{\theta\in \mathcal{T}}{\int} \underset{q_{\theta,m-1}}{\overset{q_{\theta,m}}{\int}} \theta \mathrm d  F(x,\theta) }{  \underset{\theta\in \mathcal{T}}{\int} \underset{q_{\theta,m-1}}{\overset{q_{\theta,m}}{\int}} \mathrm d  F(x,\theta) }. \label{eqn:thval}
\end{align}


Note that implementing a quantizer $Q:(\mathcal{X},\mathcal {T})\rightarrow \mathcal{Z}$ can be simplified to computing a set of quantizers corresponding to each $\theta \in \mathcal{T}$ as in Fig. \ref{fig:quantM5} without loss of generality. If the quantizer does not include a region $m$ for some realization of $\theta$, the encoder never sends the message $m$ i.e., the encoder chooses a lower rate and is less revealing for that value of $\theta$. In Fig. \ref{fig:quantM5}, we see that the quantizer $q_{\theta_1}$ only includes $m=1,2,4$ regions, while the quantizer $q_{\theta_2}$ contains all five regions.

