\section{Proof of Theorem \ref{thm:alpha}}
\label{appdx:mapping}
We have two scalar random variables $X$ and $\theta$, jointly Gaussian with zero means and covariance
\begin{align}
    (X,\theta)\sim \mathcal{N}\bigg(\begin{bmatrix}
    0 \\ 0
\end{bmatrix},\begin{bmatrix}
    \sigma_X^2  & \rho \sigma_X\sigma_{\theta} \\ \rho \sigma_X\sigma_{\theta} & \sigma_{\theta}^2 
\end{bmatrix}\bigg)\nonumber ,
\end{align}
where $\rho\in[-1,1]$. We form the scalar
$$y = x + \alpha \theta,$$
and use the linear (MMSE) estimates
$$\hat{X}(Y)
=
\frac{\mathbb{E}\{XY\}}{\mathbb{E}\{Y^2\}}Y,
\quad
\hat{\theta}(Y)
=
\frac{\mathbb{E}\{\theta Y\}}{\mathbb{E}\{Y^2\}}Y.$$
We want to choose $\alpha$ to minimize
$$J(\alpha)
=
\mathbb{E}\{(X +\theta-\hat{X}(Y))^{2}\}
-
\lambda \mathbb{E}\{(\theta -\hat{\theta}(Y))^{2}\}
\quad
(\lambda>0).$$

We define:
$$v(\alpha)
=
\mathbb{E}\{Y^2\}
=\mathbb{E}\{(X+\alpha \theta)^2\}
=
\sigma_X^2
+
2\alpha \rho \sigma_X \sigma_{\theta}
+
\alpha^2 \sigma_{\theta}^2.$$
$$c_x(\alpha)
=\mathbb{E}\{XY\}
=\mathbb{E}\{X(X+\alpha \theta)\}=
\sigma_X^2
+
\alpha \rho \sigma_X \sigma_{\theta},$$
$$c_s(\alpha)
=\mathbb{E}\{\theta Y\}
=\mathbb{E}\{\theta(X+\alpha \theta)\}
=
\rho\sigma_X \sigma_{\theta}
+
\alpha \sigma_{\theta}^2,$$
\begin{align}
    c_{x+\theta}(\alpha)
&=\mathbb{E}\{(X+\theta)Y\}
=\mathbb{E}\{(X+\theta)(X+\alpha \theta)\}\nonumber
\\&=
\sigma_X^2 + \rho \sigma_X\sigma_{\theta}
+
\alpha (\rho \sigma_X \sigma_{\theta} + \sigma_{\theta}^2).\nonumber
\end{align}

We write
$$
J(\alpha)
 = 
\mathbb{E} \{(X - \hat{X}(Y) +\theta)^{2} \}
 - 
\lambda 
\mathbb{E} \{(\theta - \hat{\theta}(Y))^{2} \}.
$$
After some straightforward algebra steps, we obtain:

$$
J(\alpha)
=
\underbrace{\sigma_X^2  + (1-\lambda) \sigma_{\theta}^2  + 2 \rho \sigma_X \sigma_{\theta}}_{\text{constant}}
 + 
\frac{P(\alpha)}{v(\alpha)}.
$$
where
$$
P(\alpha)
 = 
(c_x(\alpha))^{2}
 - 
2 c_x(\alpha) c_{x+\theta}(\alpha)
 + 
\lambda (c_s(\alpha))^{2}.
$$
Minimizing $J(\alpha)$ is therefore equivalent to minimizing
$\displaystyle \frac{P(\alpha)}{v(\alpha)}.$

We then expand the terms in $P(\alpha)$ and after some straightforward algebra (omitted here, presented in \cite{anand2025arxivprivacy}), we have a quadratic equation in terms of $\alpha$: 













$$
r(\rho + r) \alpha^{2}
 + 
(1 + \lambda r^{2}) \alpha
 + 
(\lambda \rho r  - 1)
 = 
0, 
$$
where
$$
r  = \frac{\sigma_{\theta}}{\sigma_X}.
$$

Solving for  $\alpha$:
$$
\alpha^{\ast}
 = 
\frac{
-(1 + \lambda r^{2})
 \pm 
\sqrt{(1 + \lambda r^{2})^{2}
       - 
      4 r(\rho + r) (\lambda \rho r -1)}
}{
2 r (\rho + r)}.
$$



The second derivative,
\begin{align}
    \frac{\partial^2 }{\partial \alpha^2}\bigg[ \frac{P(\alpha)}{v(\alpha)}\bigg] & = 2r(\rho+r )\alpha + (1+\lambda r^2) \nonumber
    \end{align}

For $r>0,\, \rho\in[-1,1],\,\lambda >0$,
this expression evaluates to a negative value for 
$$\alpha  <-\frac{(1+\lambda r^2)}{2r(\rho+r )}.$$

That is,
$$
\alpha^{\ast}
 = 
\frac{
-(1 + \lambda r^{2})
+ 
\sqrt{(1 + \lambda r^{2})^{2}
       - 
      4 r(\rho + r) (\lambda \rho r -1)}
}{
2 r (\rho + r)}.
$$
















\section{Proof of Theorem \ref{thm:Ddec}}
\label{appdx:decdistdecreasewithlambda}
We assume zero mean, $\rho = 0$.
\begin{align}
    D_D&= \mathbb{E}\{(X-\kappa(X+\alpha\theta))^2\}\nonumber
    \\& = (1-\kappa)^2 \mathbb{E}\{X^2\} + \kappa^2 \alpha^2 \mathbb{E}\{\theta^2\}\nonumber .
\end{align}
The term $\partial D_D/\partial \lambda $,
\begin{align}
    \frac{\partial D_D}{\partial \lambda } = \frac{\partial D_D}{\partial \alpha} \frac{\partial \alpha}{\partial \lambda}\nonumber .
\end{align}
We  define the term $f(\alpha)$ as follows for convenience:
\begin{align}
    f(\alpha) = \frac{ \sigma_X^2 }{ \sigma_X^2 + \alpha^2 \sigma_S^2 }.\nonumber
\end{align}
Then, the decoder distortion,
\begin{align}
    D_D & = (1-f(\alpha))^2 \mathbb{E}\{X^2\} + f(\alpha)^2 \alpha^2 \mathbb{E}\{\theta^2\}.\nonumber
\end{align}
The term $f'(\alpha)$ is given by,
\begin{align}
    \frac{\partial f(\alpha)}{\partial \alpha} & = -\sigma_X^2 (\sigma_X^2+\alpha^2 \sigma_S^2)^{-2} 2 \alpha \sigma_S^2 . \nonumber
\end{align}
The term $\partial D_D/\partial \alpha$,
\begin{align}
    \frac{\partial D_D}{\partial \alpha} & = -2(1-f(\alpha)) f'(\alpha) \mathbb{E}\{X^2\} \nonumber
    \\& \quad + 2 f(\alpha) f'(\alpha) \alpha^2 \mathbb{E}\{\theta^2\} +2f(\alpha)^2 \alpha \mathbb{E}\{\theta^2\}  \nonumber
\end{align}


We define $A,B$ as follows for convenience of notation:
\begin{align}
    A = 1+\lambda r^2\nonumber
\end{align}
\begin{align}
    B = (1+\lambda r^2)^2 - 4 r(\rho+r)(\lambda \rho r -1).\nonumber
\end{align}
Then $\alpha^*$ can be written as,
\begin{align}
    \alpha^* = \frac{-A+ \sqrt{B}  }{ 2 r (\rho+r)}.\nonumber
\end{align}
The term $\partial \alpha /\partial \lambda$,
\begin{align}
    \frac{\partial \alpha }{\partial \lambda} = \frac{ -\frac{\partial A}{\partial \lambda} + \frac{1}{2} B^{-1/2} \frac{\partial B}{\partial \lambda } }{ 2 r (\rho +r ) },\nonumber
\end{align}
\begin{align}
    \frac{\partial A}{\partial \lambda} = r^2\nonumber
\end{align}
\begin{align}
     \frac{\partial B}{\partial \lambda} =2(1+\lambda r^2) r^2 -4r(\rho +r)\rho r \nonumber
\end{align}
\begin{align}
      \frac{\partial \alpha }{\partial \lambda} = \frac{ -r^2 + \frac{1}{2} B^{-1/2} (2(1+\lambda r^2) r^2 -4r(\rho +r)\rho r ) }{ 2 r (\rho +r ) }\nonumber .
\end{align}

For $\rho = 0$:
\begin{align}
    \frac{ \partial \alpha }{ \partial \lambda } & = \frac{ -r^2 + \frac{(1+\lambda r^2)r^2}{  \sqrt{(1+\lambda r^2 )^2 + 4r^2}  } }{ 2 r^2} \nonumber
    \\& = -\frac{1}{2} + \frac{1}{2} \frac{ (1+\lambda r^2) }{ \sqrt{(1+\lambda r^2)^2 + 4 r^2} }\nonumber
    \\& = -\frac{1}{2} + \frac{1}{2} k\nonumber
\end{align}
where $k<1$, i.e., $$ \frac{ \partial \alpha }{ \partial \lambda }<0.$$




Let $T$ be the sum of the first two terms of $\partial D_D /\partial \alpha$,
\begin{align}
   T& =  -2(1-f(\alpha)) f'(\alpha) \mathbb{E}\{X^2\} + 2 f(\alpha) f'(\alpha) \alpha^2 \mathbb{E}\{\theta^2\} \nonumber\\ & = 2f'(\alpha) \bigg( -(1-f(\alpha)) \mathbb{E}\{X^2\} + f(\alpha) \alpha^2 \mathbb{E}\{\theta^2\} \bigg)\nonumber
    \\& = \frac{2f'(\alpha) }{ \sigma_X^2 + \alpha^2 \sigma_{\theta}^2 } \bigg( - \alpha^2 \sigma_{\theta}^2 \mathbb{E}\{X^2\} + \sigma_X^2 \alpha^2 \mathbb{E}\{\theta^2\} \bigg)\nonumber
\end{align}
Since we assumed zero mean,
\begin{align}
    T = 0.\nonumber
\end{align}
Then $\partial D_D/\partial \alpha$ evaluates to
\begin{align}
    \frac{\partial D_D}{\partial \alpha} & = 2f(\alpha)^2 \alpha \mathbb{E}\{\theta^2\}  .\nonumber
\end{align}
For $\rho = 0$, 
\begin{align}
    \alpha & = \frac{ -(1+\lambda r^2) + \sqrt{(1+\lambda r^2)^2 - 4 r(\rho+r)(\lambda \rho r -1)} }{ 2 r(\rho +r)}\nonumber
    \\& =  \frac{ -(1+\lambda r^2) + \sqrt{(1+\lambda r^2)^2 + 4 r^2} }{ 2 r^2}\nonumber
    \\& \geq 0\nonumber .
\end{align}
Then $\frac{\partial D_D}{\partial \alpha}\geq 0$, that is $\frac{\partial D_D }{\partial \lambda } \leq 0$, $D_D$ decreases as $\lambda$ increases.





