\section{Proof of Lemma 1}
The proof of \cref{lemma:concentration} relies on the following two technical lemmas. Here, we assume that subgaussian random variables have zero mean.
\begin{lemma}
\label{lemma 4} Let $X$ be a $\sigma$-subgaussian random variable. Then for any $\varepsilon \geq 0$, the following concentration bound holds 
\[\mathbb{P}(X \geq \varepsilon) \leq e^{-\frac{\varepsilon^2}{2\sigma^2}}.\]
\end{lemma}
\begin{proof} Let $\lambda > 0$. By Markov's inequality and the definition of subgaussianity, we have 
\[\mathbb{P}(X\geq \varepsilon) = \mathbb{P}(e^{\lambda X} \geq e^{\lambda \varepsilon})\leq \mathbb{E}[e^{\lambda X}]e^{-\lambda\varepsilon}\leq e^{\frac{\lambda^2\sigma^2}{2}-\lambda\varepsilon}. \]
To optimize the upper bound, we set $\lambda = \frac{\varepsilon}{\sigma^2}$. Substituting this value of $\lambda$, we obtain the desired inequality. 
\end{proof}
\begin{lemma}
\label{lemma 5} Let $X$ be a $\sigma$-subgaussian random variable, and let $X_1$ and $X_2$ be independent $\sigma_1$-subgaussian and $\sigma_2$-subgaussian random variables, respectively. Then, the following properties hold
\begin{enumerate}[label=(\alph*)]
\item For any $c \in \mathbb{R}$, $cX$ is $|c|\sigma\text{-subgaussian}$

\item $X_1 + X_2$ is $\sqrt{\sigma_{1}^2+\sigma_{2}^2}\text{-subgaussian.}$
\end{enumerate}
\end{lemma} 
\begin{proof} By the definition of subgaussianity, for any $\lambda \in \mathbb{R}$, we have $\mathbb{E}[e^{\lambda X}] \leq e^{\frac{\lambda^2 \sigma^2}{2}}$. Substituting $\lambda$ with $c\lambda$ proves (a) as follows
\[\mathbb{E}[e^{\lambda (cX)}] = \mathbb{E}[e^{(c\lambda) X}]\leq e^{\frac{(c\lambda)^2 \sigma^2}{2}} = e^{\frac{\lambda^2 (|c|\sigma)^2}{2}} .\]

By the definition of subgaussianity, for any $\lambda \in \mathbb{R}$, we have $\mathbb{E}[e^{\lambda X_1}] \leq e^{\frac{\lambda^2 \sigma_1^2}{2}}$ and $\mathbb{E}[e^{\lambda X_2}] \leq e^{\frac{\lambda^2 \sigma_2^2}{2}}$. Using the independence of $X_1$ and $X_2$, we can write
\[\mathbb{E}[e^{\lambda (X_1+X_2)}] = \mathbb{E}[e^{\lambda X_1}]\mathbb{E}[e^{\lambda X_2}] \leq e^{\frac{\lambda^2 \sigma_1^2}{2}}e^{\frac{\lambda^2 \sigma_2^2}{2}} = e^{\frac{\lambda^2(\sigma_1^2+\sigma_2^2)}{2}} .\]
Thus, (b) is also proved.
\end{proof}

\begin{proof}[Proof of Lemma 1] \label{proof:concentration} For any $x \in \mathbb{R}^d$, substituting $\hat{\theta}_\ell$ with the batched regularized least squares
estimator and expanding \(r_s\), we obtain
\begin{align*}
\langle x, \hat{\theta}_{\ell} - \theta^{*} \rangle &= \langle x,H_{\ell}^{-1}\sum_{s=t_{\ell-1}+1}^{t_\ell} x_sr_s - \theta^{*} \rangle \\
&= \langle x,H_{\ell}^{-1} \sum_{s=t_{\ell-1}+1}^{t_\ell} x_s(x_{s}^{T}\theta^{*}+\eta_{s}) - \theta^{*} \rangle \\
&= \langle x,H_{\ell}^{-1} (\sum_{s=t_{\ell-1}+1}^{t_\ell} x_s\eta_{s} + (H_{\ell} - \lambda I)\theta^*) - \theta^{*} \rangle \\
&= \langle x,H_{\ell}^{-1} \sum_{s=t_{\ell-1}+1}^{t_\ell} x_s\eta_{s} - \lambda H_{\ell}^{-1}\theta^* \rangle \\
&= \sum_{s=t_{\ell-1}+1}^{t_\ell} \langle x,H_{\ell}^{-1}x_s \rangle \eta_{s} - \lambda \langle x,H_{\ell}^{-1}\theta^* \rangle \; . \tag{1}
\end{align*}
\\
The matrix $H_{\ell}$ is independent of the noise terms $\{\eta_{s}\}_{s=t_{\ell-1}+1}^{t_\ell}$. Furthermore, these $1$-subgaussian random variables $\{\eta_{s}\}_{s=t_{\ell-1}+1}^{t_\ell}$ are mutually independent. According to \cref{lemma 5}, the term
$$\sum_{s=t_{\ell-1}+1}^{t_\ell} \langle x, H_{\ell}^{-1}x_s \rangle \eta_{s} \quad \text{is} \quad\sqrt{\sum_{s=t_{\ell-1}+1}^{t_\ell} \langle x, H_{\ell}^{-1}x_s \rangle^2} -\text{subgaussian}.$$
\\
Applying the concentration inequality from \cref{lemma 4} to this subgaussian random variable yields
\begin{equation}
\mathbb{P}\left(\sum_{s=t_{\ell-1}+1}^{t_\ell} \langle x,H_{\ell}^{-1}x_s \rangle \eta_{s} \leq \sqrt{2\log\left(\frac{1}{\delta}\right)\sum_{s=t_{\ell-1}+1}^{t_\ell} \langle x,H_{\ell}^{-1}x_s \rangle^{2}}\,\right) \geq 1-\delta \; . \tag{2}
\end{equation}
\\
For the second term in (1), we apply the Cauchy-Schwarz inequality, yielding
\begin{equation}
|\langle x,H_{\ell}^{-1}\theta^* \rangle| \leq \|x\|_{H_{\ell}^{-2}} \|\theta^*\| \leq \|x\|_{H_{\ell}^{-2}} \leq \frac{\|x\|_{H_{\ell}^{-1}}}{\sqrt{\lambda}} \; . \tag{3} 
\end{equation}
Combining inequalities (2) and (3) with equation (1), we obtain
$$\mathbb{P}\left(\langle x, \hat{\theta}_{\ell}- \theta^{*} \rangle \leq \sqrt{2\log\left(\frac{1}{\delta}\right)\sum_{s=t_{\ell-1}+1}^{t_\ell} \langle x,H_{\ell}^{-1}x_s \rangle^{2}} + \sqrt{\lambda} \|x\|_{H_{\ell}^{-1}}\right) \geq 1-\delta \; .$$
To obtain a more concise bound, we observe that
$$\sum_{s=t_{\ell-1}+1}^{t_\ell} \langle x,H_{\ell}^{-1}x_s \rangle^{2} \leq x^{T}H_{\ell}^{-1}(\sum_{s=t_{\ell-1}+1}^{t_\ell} x_{s}x_{s}^{T} + \lambda I)H_{\ell}^{-1}x = x^{T}H_{\ell}^{-1}H_{\ell}H_{\ell}^{-1}x=\|x\|_{H_{\ell}^{-1}}^2 \; .$$
This completes the proof of \cref{lemma:concentration}:
$$\mathbb{P}\left(\langle x, \hat{\theta}_{\ell} - \theta^{*} \rangle \leq \bigg(\sqrt{2\log\left(\frac{1}{\delta}\right)} +\sqrt{\lambda}\bigg)\|x\|_{H_{\ell}^{-1}}  \right) \geq 1-\delta \; . \;$$
\end{proof}
\section{Proof of Lemma 2}
The proof of \cref{lemma:good-event} relies on the following five technical lemmas.
\begin{lemma}
\label{lemma 6}\cite{li2010concise} Let $A_d$ denote the surface area of an \(d\)-dimensional hypersphere of radius 1, and let $A_d^{\text{cap}}$ denote the surface area of a hyperspherical cap on an \(d\)-dimensional sphere of radius 1. Then, the following result holds for \( \phi \in (0, \frac{\pi}{2}] \), where \( I_x(a, b) \) is the regularized incomplete beta function
\[
A_d^{\text{cap}} = \frac{A_d}{2} I_{\sin^2\phi}\left(\frac{d-1}{2}, \frac{1}{2}\right) \; .
\]
\end{lemma}
\begin{lemma}
\label{lemma 7}\cite{abeille2017linear} For any integer \(d \geq 2\),
\[
\frac{\Gamma (\frac{d+1}{2})}{\Gamma (\frac{d}{2}+1)} \leq \sqrt{\frac{2}{d}} \; .
\]
\end{lemma}
\begin{lemma}
\label{lemma 8} Let $\zeta \in (0,1).$ There exists a set $C_{\zeta} \subset S^{d-1}$ with cardinality $|C_\zeta| \leq \sqrt{2\pi d} \,(\zeta^2-\frac{\zeta^4}{4})^{-\frac{d-1}{2}}$ such that for any $x \in S^{d-1}$, there exists a $y \in C_\zeta$ satisfying $\|x-y\| \leq \zeta$, where $S^{d-1} \coloneqq \{x \in \mathbb{R}^d : \|x\| = 1\}$ and $d \geq 2$.
\end{lemma}
\begin{proof} Let $\mathcal{X} \subset \mathbb{R}^d.$ A subset $C \subset \mathcal{X}$ is called an $\zeta$-cover of $\mathcal{X}$ if $\mathcal{X} \subset \bigcup_{x \in C}B_{\zeta}(x).$ Similarly, an $\zeta$-packing of $\mathcal{X}$ is a subset $P \subset \mathcal{X}$ such that for any distinct $x,y \in P,$ $\|x-y\|>\zeta.$
We define $N(\zeta)$ as the minimum cardinality of an $\zeta$-cover of $S^{d-1}$, and $M(\zeta)$ as the maximum cardinality of an $\zeta$-packing of $S^{d-1}$. Specifically,
\[
N(\zeta) \coloneqq \min\{|C| : C \text{ is an \(\zeta\)-cover of } S^{d-1} \}, \quad M(\zeta) \coloneqq \max\{|P| : P \text{ is an \(\zeta\)-packing of } S^{d-1} \} \; .
\]
Now, let $P$ be an arbitrary $\zeta$-packing of $S^{d-1}.$ For any distinct $x,y \in P$, we have $B_{\frac{\zeta}{2}}(x) \cap B_{\frac{\zeta}{2}}(y) = \emptyset$. \\
Therefore, we can write
\[\underset{x \in P}{\bigsqcup}B_{\frac{\zeta}{2}}(x) \cap S^{d-1} \subset S^{d-1} \; . \tag{4}\]
\\
From (4) and \cref{lemma 6}, and the arbitrariness of $\zeta$-packing $P$, we obtain
$$M(\zeta) \leq \frac{A_d}{A_d^{\text{cap}}} = \frac{2}{I_{\sin^2(2\sin^{-1}\frac{\zeta}{2})}\left(\frac{d-1}{2}, \frac{1}{2}\right)} = \frac{2}{I_{\zeta^2(1-\frac{\zeta^2}{4})}\left(\frac{d-1}{2}, \frac{1}{2}\right)} \; .$$
\\
Using the monotonicity of \(t \rightarrow (1-t)^{-\frac{1}{2}}\) on \((0,\frac{3}{4})\), along with \(0 < \zeta^2(1-\frac{\zeta^2}{4}) < \frac{3}{4}\) for \(\zeta \in (0,1)\), and applying \cref{lemma 7}, we derive
\begin{align*}
\frac{2}{I_{\zeta^2(1-\frac{\zeta^2}{4})}\left(\frac{d-1}{2}, \frac{1}{2}\right)} &= \frac{2B(\frac{d-1}{2},\frac{1}{2})}{B_{\zeta^2(1-\frac{\zeta^2}{4})}(\frac{d-1}{2},\frac{1}{2})} \\
&= \frac{2B(\frac{d-1}{2},\frac{1}{2})}{\int_0^{\zeta^2(1-\frac{\zeta^2}{4})} t^{\frac{d-3}{2}}(1-t)^{-\frac{1}{2}}dt} \\
&\leq \frac{2B(\frac{d-1}{2},\frac{1}{2})}{\int_0^{\zeta^2(1-\frac{\zeta^2}{4})} t^{\frac{d-3}{2}}dt} \\
&= \frac{(d-1)B(\frac{d-1}{2},\frac{1}{2})}{(\zeta^2-\frac{\zeta^4}{4})^{\frac{d-1}{2}}} \\
&= \frac{(d-1)\sqrt{\pi}}{(\zeta^2-\frac{\zeta^4}{4})^{\frac{d-1}{2}}} \cdot \frac{\Gamma(\frac{d-1}{2})}{\Gamma(\frac{d}{2})} \\
&= \frac{d\sqrt{\pi}}{(\zeta^2-\frac{\zeta^4}{4})^{\frac{d-1}{2}}} \cdot \frac{\Gamma(\frac{d+1}{2})}{\Gamma(\frac{d}{2}+1)} \\
&\leq \frac{\sqrt{2\pi d}}{(\zeta^2-\frac{\zeta^4}{4})^{\frac{d-1}{2}}} \; .
\end{align*}
\\
Here, \(B_x(a,b)\) is the incomplete beta function and \(B(a,b)\) is the beta function.
\\
Since $M(\zeta) \leq \sqrt{2\pi d} \,(\zeta^2-\frac{\zeta^4}{4})^{-\frac{d-1}{2}} < \infty,$ there exists a maximal $\zeta$-packing $P_\zeta$ of $S^{d-1}.$ In this case, $P_\zeta$ is also an $\zeta$-cover of $S^{d-1}$, implying $N(\zeta)\leq M(\zeta).$
\\
Thus, combining these results completes the proof:
\[
N(\zeta) \leq M(\zeta) \leq  \frac{\sqrt{2\pi d}}{(\zeta^2-\frac{\zeta^4}{4})^{\frac{d-1}{2}}}\; .
\]
\end{proof}
\begin{lemma}
\label{lemma 9} After the $\ell$-th batch $(\ell\geq 1)$, the following bound holds for any $0 < \zeta < 1$ and $d \geq 2$ with probability at least $1-\delta$
\[
\|\hat{\theta}_{{\ell}}-\theta^{*} \|_{H_{{\ell}}} \leq \frac{\sqrt{(d-1)\log(\frac{4}{4\zeta^2-\zeta^4})+2\log(\frac{\sqrt{2\pi d}}{\delta})} +\sqrt{\lambda}}{1-\zeta}\; .
\]
\end{lemma}
\begin{proof} If $\hat{\theta}_\ell = \theta_*$, the lemma is trivial. Thus, we only consider the case where $\hat{\theta}_\ell \neq \theta_*$. 
\\
Let $X = \frac{H_{\ell}^{\frac{1}{2}}(\hat{\theta}_{{\ell}} - \theta_{*})}{\|\hat{\theta}_{{\ell}} - \theta_{*}\|_{H_{\ell}}}.$ Since $\|X\|=1$, it follows that $X \in S^{d-1}$, where $S^{d-1}$ is the unit sphere in $\mathbb{R}^d$.
\\
Let $C_{\zeta} \subset S^{d-1}$ be the \(\zeta\)-covering set given in \cref{lemma 8}, and define the event
$$E \coloneqq \left\{ \exists \, x \in C_\zeta \; s.t. \; \langle H_{\ell}^{\frac{1}{2}}x, \hat{\theta}_{\ell} - \theta_{*} \rangle > \sqrt{2\log\left(\frac{|C_\zeta|}{\delta}\right)} + \sqrt{\lambda} \right\} \; .$$
Using the property $\|H_{\ell}^{\frac{1}{2}}x\|_{H_{\ell}^{-1}} = \|x\| = 1$ for all $x \in S^{d-1}$, and by applying \cref{lemma:concentration}, we have $\mathbb{P}(E) \leq \delta$.
\\
When the event $E$ does not occur, the following inequality holds
\begin{align*}
\|\hat{\theta}_{\ell} - \theta_{*}\|_{H_{\ell}} &= \max_{x \in S^{d-1}} \langle H_{\ell}^{\frac{1}{2}}x, \hat{\theta}_{\ell} - \theta_{*} \rangle \\
&= \max_{x \in S^{d-1}}\min_{y \in C_\zeta} \langle H_{\ell}^{\frac{1}{2}}(x-y), \hat{\theta}_{\ell} - \theta_{*} \rangle + \langle H_{\ell}^{\frac{1}{2}}y, \hat{\theta}_{\ell} - \theta_{*} \rangle \\
&\leq \max_{x \in S^{d-1}}\min_{y \in C_\zeta} \|\hat{\theta}_{\ell} - \theta_{*}\|_{H_{\ell}} \|x-y\| + \langle H_{\ell}^{\frac{1}{2}}y, \hat{\theta}_{\ell} - \theta_{*} \rangle \\
&\leq \zeta \|\hat{\theta}_{\ell} - \theta_{*}\|_{H_{\ell}} + \sqrt{2\log\left(\frac{|C_\zeta|}{\delta}\right)} +\sqrt{\lambda} \\
&\leq \zeta \|\hat{\theta}_{\ell} - \theta_{*}\|_{H_{\ell}} + \sqrt{(d-1)\log\left(\frac{4}{4\zeta^2-\zeta^4}\right)+2\log\left(\frac{\sqrt{2\pi d}}{\delta}\right)} +\sqrt{\lambda} \; .
\end{align*}
Therefore, we prove \cref{lemma 9}:
\[
\mathbb{P}\left(\|\hat{\theta}_{{\ell}}-\theta^{*} \|_{H_{{\ell}}} \leq \frac{\sqrt{(d-1)\log(\frac{4}{4\zeta^2-\zeta^4})+2\log(\frac{\sqrt{2\pi d}}{\delta})} +\sqrt{\lambda}}{1-\zeta}\, \right) \geq 1-\delta \; .
\]
\end{proof}
From this point onward, for convenience, we define $M_\ell$ as follows
\[
M_\ell \coloneqq \, \underset{x,y \in \mathcal{A}_{\ell-1}}{\max}\|x-y\|_{H_\ell^{-1}}^2.
\]
Here, $\zeta \in (0,1)$ is a tunable parameter. While it is possible to optimize over $\zeta$, we fix $\zeta = 0.5$ for simplicity, as this choice influences the results only up to a constant factor. Nevertheless, we retain $\zeta$ as a symbolic variable in the following analysis to maintain generality. Readers may safely substitute $\zeta = 0.5$ throughout.
\\
\begin{lemma}
\label{lemma 10} After the $\ell$-th batch $(\ell\geq 1)$, the following result holds for all $x,y \in \mathcal{A}_{\ell-1}$ with probability at least $1-\delta$
$$|\langle x-y, \hat{\theta}_{\ell}-\theta^{*} \rangle| \leq \sqrt{M_\ell} \cdot \beta_\ell(\delta+\delta\lceil \log_2\log_2T \rceil) \; .$$
\end{lemma}
\begin{proof} Using the Cauchy-Schwarz inequality and \cref{lemma 9}, the following result holds for all $x,y \in \mathcal{A}_{\ell-1}$ with probability at least $1-\frac{\delta}{2}$
\[
|\langle x-y, \hat{\theta}_{\ell} - \theta^* \rangle| \leq \|x-y\|_{H_{{\ell}}^{-1}}\|\hat{\theta}_{\ell} - \theta^*\|_{H_{{\ell}}} \leq \frac{\sqrt{\|x-y\|_{H_{{\ell}}^{-1}}^2 }\left(\sqrt{(d-1)\log(\frac{4}{4\zeta^2-\zeta^4})+2\log(\frac{2\sqrt{2\pi d}}{\delta})} +\sqrt{\lambda}\right)}{1-\zeta} \; . 
\]
Since $\|x-y\|_{H_{\ell}^{-1}}^2 \leq M_{\ell}$, we obtain
\[\mathbb{P}\left(
|\langle x-y, \hat{\theta}_{\ell} - \theta^* \rangle| \leq \frac{\sqrt{M_{\ell}}\left(\sqrt{(d-1)\log(\frac{4}{4\zeta^2-\zeta^4})+2\log(\frac{2\sqrt{2\pi d}}{\delta})} +\sqrt{\lambda}\right)}{1-\zeta}, \; \forall x,y \in \mathcal{A}_{\ell-1} \right) \geq 1-\frac{\delta}{2} \; . \tag{5}
\]
Next, by applying \cref{lemma:concentration} to the \(\binom{|\mathcal{A}_{\ell-1}|}{2}\) pairs of $x,y \in \mathcal{A}_{\ell-1}$ such that $\langle x-y, \hat{\theta}_{\ell} - \theta^* \rangle \geq 0$, we know that for all \(x,y \in \mathcal{A}_{\ell-1}\), the following holds with probability at least \(1-\frac{\delta}{2}\)
$$|\langle x-y, \hat{\theta}_{\ell}-\theta^{*} \rangle| \leq  \left(\sqrt{2\log\left(\frac{|\mathcal{A}_{\ell-1}|^2-|\mathcal{A}_{\ell-1}|}{\delta}\right)}+ \sqrt{\lambda}\right) \|x-y\|_{H_{\ell}^{-1}} \; .$$
Since $\|x-y\|_{H_{\ell}^{-1}}^2 \leq M_{\ell}$, we obtain
\[\mathbb{P}\left(|\langle x-y, \hat{\theta}_{\ell}-\theta^{*} \rangle| \leq  \sqrt{M_\ell}\left(\sqrt{2\log\left(\frac{|\mathcal{A}_{\ell-1}|^2-|\mathcal{A}_{\ell-1}|}{\delta}\right)}+ \sqrt{\lambda} \right), \; \forall x,y \in \mathcal{A}_{\ell-1} \right) \geq 1-\frac{\delta}{2} \; . \tag{6}
\]
Using the definition of \(\beta_\ell(\delta)\), we calculate $\beta_{\ell}(\delta+\delta\lceil \log_2\log_2 T \rceil)$ as
\[
\beta_{\ell}(\delta+\delta\lceil \log_2\log_2 T \rceil) = \left(\frac{\sqrt{(d-1)\log(\frac{4}{4\zeta^2-\zeta^4})+2\log(\frac{2\sqrt{2\pi d}}{\delta})} +\sqrt{\lambda}}{1-\zeta} \, \bigwedge \, \sqrt{2\log\left(\frac{|\mathcal{A}_{\ell-1}|^2-|\mathcal{A}_{\ell-1}|}{\delta}\right)} + \sqrt{\lambda}\right) \; .
\]
Combining the result from (5) and (6), we prove \cref{lemma 10}:
\[
\mathbb{P}\left(|\langle x-y, \hat{\theta}_{\ell}-\theta^{*} \rangle| \leq \sqrt{M_\ell} \cdot \beta_\ell(\delta+\delta\lceil \log_2\log_2T \rceil), \; \forall x,y \in \mathcal{A}_{\ell-1}\right) \geq 1-\delta \; .
\]
\end{proof}
\begin{proof}[Proof of Lemma 2] At the $\lceil \log_2\log_2 T \rceil$-th and $(1+\lceil \log_2\log_2 T \rceil)$-th batch, the number of arm pulls satisfies 
\[
T^{1-\frac{1}{2^{1+\lceil \log_2\log_2 T \rceil}}} \geq T^{1-\frac{1}{2^{\lceil \log_2\log_2 T \rceil}}} \geq T^{1-\frac{1}{\log_2T}} = \frac{T}{2} \; .
\]
Thus, the total number of batches $B$ is bounded by
$$B \leq 1+\lceil \log_2\log_2 T \rceil \; .$$
Let $E_{\ell}\coloneqq \{|\langle x-y,\hat{\theta}_\ell - \theta^* \rangle| \leq \varepsilon_\ell(\delta), \; \forall x,y \in \mathcal{A}_{\ell-1} \}$. By \cref{lemma 10}, we have
$$\mathbb{P}\left(E_{\ell}\right) \geq 1-\frac{\delta}{1+\lceil \log_2\log_2 T \rceil} \; .$$
By definition, $E = \cap_{\ell=1}^{B}E_{\ell}$, the following holds
$$\mathbb{P}(E^c) = \mathbb{P}(\overset{B}{\underset{\ell=1}{\cup}}E_{\ell}^{c}) \leq \sum_{\ell=1}^{B} \mathbb{P}(E_{\ell}^{c}) \leq \frac{B\delta}{1+\lceil \log_2\log_2 T \rceil} \leq \delta \; .$$
Therefore, we prove \cref{lemma:good-event}:
\[\mathbb{P}(E) \geq 1-\delta \; .\]
\end{proof}
\section{Proof of Lemma 3}
The proof of \cref{lemma:regularized-G-optimal-design} relies on the following four technical lemmas.
\begin{lemma}
\label{lemma 11} If $A : \mathbb{R} \rightarrow \mathbb{R}^{d\times d}$ is a $d\times d$ matrix, then the following holds
\[
\frac{d}{ds}\det(A(s)) = \text{trace}\left(\text{adj}(A)\frac{d}{ds}A(s)\right) \; .
\]
\end{lemma}
\begin{proof} Recall that $\det(A)$ can be expressed as a polynomial in the entries $a_{ij}$ of $A$. Concretely,
\[
\det(A) = \sum_{\sigma \in S_d} \text{sgn}(\sigma)a_{1,\sigma(1)}a_{2,\sigma(2)}\cdots a_{d,\sigma(d)}
\]
where the sum is over the symmetric group $S_d$ and $\text{sgn}(\sigma)$ denotes the signature of $\sigma$. Consequently, the partial derivative of $\det(A)$ with respect to a particular entry $a_{ij}$ involves only those terms in the polynomial that contain $a_{ij}$. From the definition of the adjugate, the $(j,i)$-th entry of $\text{adj}(A)$ is precisely the cofactor corresponding to $a_{ij}$. Concretely,
\[
\frac{\partial \det(A)}{\partial a_{ij}}
=
\bigl(\mathrm{adj}(A)\bigr)_{ji} \; . \tag{7}
\]
Next, let us regard $A$ as dependent on a variable $s$, so that each entry $a_{ij}$ becomes $a_{ij}(s)$. By the chain rule, we have
\[
\frac{d}{ds}\det(A(s)) = \sum_{1 \leq i,j \leq d} \frac{\partial \det(A)}{\partial a_{ij}} \cdot \frac{d}{ds}a_{ij}(s) \; .
\]
Substituting (7) into this sum yields
\[
\frac{d}{ds}\det(A(s))
=
\sum_{1\leq i,j \leq d} \bigl(\text{adj}(A)\bigr)_{ji}\cdot
\bigl(\tfrac{d}{ds}A(s)\bigr)_{ij} \; .
\]
Notice that the above expression is precisely the trace of the product \(\text{adj}(A) \cdot \tfrac{d}{ds}A(s)\). Indeed, writing matrix products in terms of their indices shows that
\[
\sum_{1\leq i,j \leq d} \bigl(\text{adj}(A)\bigr)_{ji} \cdot
\bigl(\tfrac{d}{ds}A(s)\bigr)_{ij}
=
\text{trace}\left(\text{adj}(A)\frac{d}{ds}A(s)\right) \; .
\]
Therefore, we prove \cref{lemma 11}:
\[
\frac{d}{ds}\det(A(s))
=
\text{trace}\left(\text{adj}(A)\frac{d}{ds}A(s)\right) \; .
\]
\end{proof}
\begin{lemma}
\label{lemma 12} Let $f:\mathcal{D}_\ell \rightarrow \mathbb{R}$ be defined as
\[
f(\pi_\ell) \coloneqq \log(\det(V_\ell(\pi_\ell))) = \log\left(\det\Bigg(\frac{\lambda}{c_\ell}I+\sum_{i=1}^{|\mathcal{A}_{\ell-1}|}\pi_{\ell i}T^{\frac{2^\ell-1}{2^\ell}}x^{(i)}{x^{(i)}}^T\Bigg)\right)\; .
\]
Then $f$ is a concave function.
\end{lemma}
\begin{proof} Define $\mathcal{T} \coloneqq \{X \in \mathbb{R}^{d\times d}:X > 0\}$, and let $g : \mathcal{T} \rightarrow \mathbb{R}$ be given by
\[
g(X) = \log(\det(X)) \; .
\]
The gradient of $g(X)$, using (7) and symmetry of $X$, is computed as
\[
\nabla_Xg(X) = \frac{\text{adj}(X)^T}{\det(X)} = \frac{\text{adj}(X)}{\det(X)} = X^{-1} \; .
\]
Using \cref{lemma 11}, for any symmetric matrix $U \in \mathbb{R}^{d\times d}$, the Hessian of $g(X)$ is computed as follows
\begin{align*}
\nabla^2_Xg(X)[U, U] &= \frac{d^2}{ds^2}\Big|_{s=0} \log(\det(X+sU)) \\
&= \frac{d}{ds}\Big|_{s=0} \frac{\text{trace}(\text{adj}(X+sU)U)}{\det(X+sU)} \\
&= \frac{d}{ds}\Big|_{s=0} \text{trace}((X+sU)^{-1}U) \\
&= -\text{trace}((X+sU)^{-1}U(X+sU)^{-1}U) \Big|_{s=0} \\
&= -\text{trace}(X^{-1}UX^{-1}U)
\end{align*}
Since $X^{-1}$ is positive definite and $U$ is symmetric, we have
\[
\text{trace}(X^{-1}UX^{-1}U) = \text{trace}(X^{-\frac{1}{2}}UX^{-\frac{1}{2}}X^{-\frac{1}{2}}UX^{-\frac{1}{2}}) = \text{trace}((X^{-\frac{1}{2}}UX^{-\frac{1}{2}})^TX^{-\frac{1}{2}}UX^{-\frac{1}{2}}) \geq 0 \; .
\]
Thus, the Hessian is negative semidefinite, which implies that $g(X)$ is concave for $X > 0$.
\\
Next, observe that \(V_\ell : \mathcal{D}_\ell \rightarrow \mathcal{T}\) is an affine map. Since the composition of a concave function with an affine map is concave, it follows that $f(\pi_\ell) = g(V_\ell(\pi_\ell))$ is concave. Specifically, for any
\(\pi_\ell,\tilde{\pi}_\ell \in \mathcal{D}_\ell\) and \(\lambda \in [0,1]\), we have
\[
g(V_\ell(\lambda\pi_\ell + (1-\lambda)\tilde{\pi}_\ell)) = g(\lambda V_\ell(\pi_\ell) + (1-\lambda) V_\ell(\tilde{\pi}_\ell)) \geq \lambda g(V_\ell(\pi_\ell)) + (1-\lambda)g(V_\ell(\tilde{\pi}_\ell)) \; .
\]
Therefore, $f(\pi_\ell)$ is a concave function of $\pi_\ell$. 
\end{proof}
\begin{lemma}
\label{lemma 13} Let $f:\mathbb{R}^d \rightarrow \mathbb{R}$ be a concave and differentiable function, and let $C \subseteq \mathbb{R}^d$ be a non-empty convex set. If \(x^* \in \text{argmax}_{x \in C} \, f(x)\), then the following holds
$$\langle x-x^*, \nabla f(x^*) \rangle \leq 0, \quad \forall x \in C \; .$$
\end{lemma}
\begin{proof} Define \(x(s) \coloneqq sx+(1-s)x^*\) for $s \in [0,1]$. Since $C$ is convex, we have $x(s) \in C$ for all $s \in [0,1]$. Let $\phi(s) \coloneqq f(x(s))$ for $s \in [0,1]$. Because $x^*$ is the maximizer of $f(x)$ over $C$, it follows that
$$\phi(0) = f(x^*) \geq f(x(s)) = \phi(s), \quad \forall s \in [0,1] \; .$$
Thus, $\phi(s)$'s right derivative at $s=0$ must be non-positive
\[0 \geq \phi'(0+) = \nabla f(x^*)^T (x-x^*) \; .\] 
Therefore, we prove \cref{lemma 13}:
$$\langle x-x^*, \nabla f(x^*) \rangle \leq 0, \quad \forall x \in C \; .$$
\end{proof}
\begin{lemma}
\label{lemma 14} After the $\ell$-th batch $(\ell \geq 1)$, the following bound holds
\[\underset{x \in \mathcal{A}_{\ell-1}}{\max} \|x\|^2_{V_{\ell}(\pi_\ell^*)^{-1}} \leq \frac{dc_\ell}{d\lambda + T^{\frac{2^\ell-1}{2^\ell}}c_\ell} \; .\]
\end{lemma}
\begin{proof} Let us define $f(\pi_\ell) \coloneqq \log(\det(V_\ell(\pi_\ell))$. We compute the gradient of $f(\pi_\ell)$ component-wise
\begin{align*}
(\nabla f(\pi_\ell))_i &= \frac{\partial}{\partial \pi_{\ell i}}\log(\det(V_\ell(\pi_\ell)) \\
&= \frac{1}{\det(V_\ell(\pi_\ell))} \cdot \frac{\partial}{\partial \pi_{\ell i}}\det(V_\ell(\pi_\ell)) \; .
\end{align*}
Using \cref{lemma 11}, we obtain
\begin{align*}
(\nabla f(\pi_\ell))_i &= \frac{1}{\det(V_\ell(\pi_\ell))} \cdot \text{trace}\left(\text{adj}(V_\ell(\pi_\ell))\frac{\partial V_\ell(\pi_\ell)}{\partial \pi_{\ell i}}\right)\\
&= \text{trace}\left(V_\ell(\pi_\ell)^{-1} \cdot \frac{\partial V_\ell(\pi_\ell)}{\partial \pi_{\ell i}}\right)\\
&= \text{trace}(V_\ell(\pi_\ell)^{-1} \cdot T^{\frac{2^\ell-1}{2^\ell}} x^{(i)}{x^{(i)}}^T) \\
&= T^{\frac{2^\ell-1}{2^\ell}}\|x^{(i)}\|_{V_\ell(\pi_\ell)^{-1}}^2 \; .
\end{align*}
Since $V_\ell(\pi_\ell)$ is a linear function of $\pi_\ell$, the function $f(\pi_\ell)$ is continuous. Furthermore, as the domain of $f$ is the compact set $\mathcal{D}_\ell$, the Weierstrass theorem guarantees the existence of a maximizer $\pi_\ell' \in \text{argmax}_{\pi_\ell \in \mathcal{D}_\ell} f(\pi_\ell)$. Additionally, it is well known that matrix inversion is a continuous operation on the set of invertible matrices, which implies that $V_\ell(\pi_\ell)^{-1}$ is a continuous function of $\pi_\ell$. Since the maximum of finitely many continuous functions is also continuous and the set $\mathcal{D}_\ell$ is compact, the Weierstrass theorem ensures the existence of a minimizer $\pi_\ell^* \in \text{argmin}_{\pi_\ell \in \mathcal{D}_\ell}\max_{x\in \mathcal{A}_{\ell-1}}\|x\|_{V_\ell(\pi_\ell)^{-1}}^2$.
\\
Since $\mathcal{D}_\ell$ is compact and $f(\pi_\ell)$ is concave by \cref{lemma 12}, \cref{lemma 13} implies
\[
0 \geq \langle \nabla f(\pi_\ell'), \pi_\ell-\pi_\ell' \rangle, \quad \forall \pi_\ell \in \mathcal{D}_\ell \; .
\]
Expanding this inequality yields
\[
0 \geq \sum_{i=1}^{|\mathcal{A}_{\ell-1}|} (\nabla f(\pi_\ell'))_i (\pi_{\ell i} - \pi_{\ell i}') 
= \sum_{i=1}^{|\mathcal{A}_{\ell-1}|} T^{\frac{2^\ell-1}{2^\ell}}\|x^{(i)}\|_{V_\ell(\pi_\ell')^{-1}}^2 (\pi_{\ell i} - \pi_{\ell i}') , \quad \forall \pi_\ell \in \mathcal{D}_\ell \; .
\]
When we set $\pi_\ell$ to be a Dirac distribution $(0,\dots,1,\dots,0)$ and divide by $T^{\frac{2^\ell-1}{2^\ell}}$, we obtain
\begin{align*}
0 &\geq \|x^{(i)}\|_{V_\ell(\pi_\ell')^{-1}}^2 - \sum_{j=1}^{|\mathcal{A}_{\ell-1}|} \|x^{(j)}\|_{V_\ell(\pi_\ell')^{-1}}^2 \pi_{\ell j}' \\
&= \|x^{(i)}\|_{V_\ell(\pi_\ell')^{-1}}^2 - \sum_{j=1}^{|\mathcal{A}_{\ell-1}|} \text{trace}(\pi_{\ell j}'x^{(j)}{x^{(j)}}^T V_\ell(\pi_\ell')^{-1}) \\
&= \|x^{(i)}\|_{V_\ell(\pi_\ell')^{-1}}^2 - T^{-\frac{2^\ell-1}{2^\ell}}\text{trace}(\sum_{j=1}^{|\mathcal{A}_{\ell-1}|} \pi_{\ell j}'T^{\frac{2^\ell-1}{2^\ell}}x^{(j)}{x^{(j)}}^T V_\ell(\pi_\ell')^{-1}) \\
&= \|x^{(i)}\|_{V_\ell(\pi_\ell')^{-1}}^2 - T^{-\frac{2^\ell-1}{2^\ell}}\text{trace}((V_\ell(\pi_\ell') - \frac{\lambda}{c_\ell} I )V_\ell(\pi_\ell')^{-1}) \\
&= \|x^{(i)}\|_{V_\ell(\pi_\ell')^{-1}}^2 - T^{-\frac{2^\ell-1}{2^\ell}}\text{trace}(I - \frac{\lambda}{c_\ell} V_\ell(\pi_\ell')^{-1}) \\
&= \|x^{(i)}\|_{V_\ell(\pi_\ell')^{-1}}^2 - dT^{-\frac{2^\ell-1}{2^\ell}} + \frac{\lambda T^{-\frac{2^\ell-1}{2^\ell}}}{c_\ell}\text{trace}(V_\ell(\pi_\ell')^{-1}) \; . \tag{8}
\end{align*}
Let $\mathcal{\lambda}_1',\mathcal{\lambda}_2',\cdots,\mathcal{\lambda}_d'$ be the eigenvalues of $V_\ell(\pi_\ell')$. By the Cauchy-Schwarz inequality, we have
\[
\text{trace}(V_\ell(\pi_\ell')^{-1}) = \sum_{i=1}^{d}\frac{1}{\lambda_i'} \geq \frac{d^2}{\sum_{i=1}^{d} \lambda_i'} = \frac{d^2}{\text{trace}(V_\ell(\pi_\ell'))} \; .
\]
Using Assumption~\ref{assum:norm}, we obtain
\begin{align*}
\text{trace}(V_\ell(\pi_\ell')) &= \text{trace}\left(\frac{\lambda}{c_\ell}I+\sum_{i=1}^{|\mathcal{A}_{\ell-1}|}\pi_{\ell i}'T^{\frac{2^\ell-1}{2^\ell}}x^{(i)}{x^{(i)}}^T\right) \\
&= \frac{d\lambda}{c_\ell}+\sum_{i=1}^{|\mathcal{A}_{\ell-1}|}\pi_{\ell i}'T^{\frac{2^\ell-1}{2^\ell}}\|x^{(i)}\|^2 \\
&\leq \frac{d\lambda}{c_\ell} + T^{\frac{2^\ell-1}{2^\ell}} \; ,
\end{align*}
which implies 
\[
\text{trace}(V_\ell(\pi_\ell')^{-1}) \geq \frac{d^2 c_\ell}{d\lambda + T^{\frac{2^\ell-1}{2^\ell}}c_\ell} \; . \tag{9}
\]
Combining (8) and (9), we obtain
\[
\|x^{(i)}\|_{V_\ell(\pi_\ell')^{-1}}^2 \leq dT^{-\frac{2^\ell-1}{2^\ell}} -\frac{d^2\lambda T^{-\frac{2^\ell-1}{2^\ell}}}{d\lambda + T^{\frac{2^\ell-1}{2^\ell}}c_\ell} = \frac{dc_\ell}{d\lambda + T^{\frac{2^\ell-1}{2^\ell}}c_\ell} \; .
\]
\\
Since this inequality holds for all $1 \leq i \leq |\mathcal{A}_{\ell-1}|$ and $\pi_\ell^*$ minimizes $\max_{x \in \mathcal{A}_{\ell-1}} \|x\|_{V_\ell(\pi_\ell)^{-1}}^2$ over $\mathcal{D}_\ell$, where
\[
\pi_\ell^* \in \underset{\pi_\ell \in \mathcal{D}_\ell}{\text{argmin}} \underset{x \in \mathcal{A}_{\ell-1}}{\text{max}} \|x\|_{V_\ell(\pi_\ell)^{-1}}^2 \; ,
\]
we conclude \cref{lemma 14}:
\[
\underset{x \in \mathcal{A}_{\ell-1}}{\max} \|x\|^2_{V_{\ell}(\pi_\ell^*)^{-1}}\leq \underset{x \in \mathcal{A}_{\ell-1}}{\max} \|x\|^2_{V_{\ell}(\pi_\ell')^{-1}} \leq \frac{dc_\ell}{d\lambda + T^{\frac{2^\ell-1}{2^\ell}}c_\ell} \; .
\]
\end{proof}
\begin{proof}[Proof of Lemma 3.] Define $\alpha_i \coloneqq \lceil T^{\frac{2^\ell-1}{2^\ell}} (c_\ell \pi_{\ell i}^* + (1-c_\ell) \cdot \bbone_{\{1\}}(i)) \rceil - c_\ell T^{\frac{2^\ell-1}{2^\ell}} \pi_{\ell i}^*$ for $1 \leq i \leq |\mathcal{A}_{\ell-1}|$, and let $X \coloneqq [\sqrt{\alpha_1}x^{(1)}, \sqrt{\alpha_2}x^{(2)}, \dots,\sqrt{\alpha_{|\mathcal{A}_{\ell-1}|}}x^{(|\mathcal{A}_{\ell-1}|)} ]$ be a matrix whose columns are the vectors $\sqrt{\alpha_i}x^{(i)}$. Then, the following holds
$$H_\ell = \lambda I + \sum_{i=1}^{|\mathcal{A}_{\ell-1}|} \lceil T^{\frac{2^\ell-1}{2^\ell}}(c_\ell \pi_{\ell i}^* + (1-c_\ell)\cdot \bbone_{\{1\}}(i)) \rceil x^{(i)}{x^{(i)}}^T = c_\ell V_\ell(\pi_{\ell}^*) + \sum_{i=1}^{|\mathcal{A}_{\ell-1}|} \alpha_i x^{(i)}{x^{(i)}}^T = c_\ell V_\ell(\pi_{\ell}^*) + XX^T \; .$$
\\
Using the Sherman-Morrison-Woodbury formula and the positive definiteness of $(I+\frac{1}{c_\ell}X^T V_{\ell}(\pi_\ell^*)^{-1} X)^{-1}$, we have
$$H_{\ell}^{-1} = \frac{1}{c_\ell}V_{\ell}(\pi_\ell^*)^{-1} - \frac{1}{c_\ell^2}V_{\ell}(\pi_\ell^*)^{-1}X(I+\frac{1}{c_\ell}X^T V_{\ell}(\pi_\ell^*)^{-1} X)^{-1}X^TV_{\ell}(\pi_\ell^*)^{-1} \leq \frac{1}{c_\ell}V_{\ell}(\pi_\ell^*)^{-1} \; .$$
Therefore, we prove \cref{lemma:regularized-G-optimal-design}:
\[ \underset{x\in \mathcal{A}_{\ell-1}}{\max}\|x\|_{H_{\ell}^{-1}}^2 \leq \underset{x\in \mathcal{A}_{\ell-1}}{\max}\|x\|_{\frac{1}{c_\ell}V_{\ell}(\pi_{\ell}^*)^{-1}}^2 \leq \frac{d}{d\lambda + T^{\frac{2^\ell-1}{2^\ell}}c_\ell} \; .
\]
\end{proof}
\section{Proof of Theorem 1}
\begin{proof}[Proof of Theorem 1] Define the nice event $E$ as 
\[E \coloneqq \bigcap\limits_{\ell = 1}^{B}\left\{|\langle x-y,\hat{\theta}_\ell - \theta^* \rangle| \leq \varepsilon_\ell, \; \forall x,y \in \mathcal{A}_{\ell-1}\right\} \; .
\] 
By \cref{lemma:good-event}, this nice event occurs with high probability
$$\mathbb{P}(E) \geq 1-\frac{1}{T} \; .$$
We can decompose the cumulative expected regret using the nice event $E$ as follows
\[
\mathcal{R}(T) = \mathbb{E}\left[\sum_{t=1}^T\langle x^*-x_t, \theta^* \rangle\bigg| E^c \right] \cdot \mathbb{P}(E^c) + \mathbb{E}\left[\sum_{t=1}^T\langle x^*-x_t, \theta^* \rangle\bigg| E \right] \cdot \mathbb{P}(E) \; .
\]
Using Assumption~\ref{assum:norm}, and the Cauchy-Schwarz inequality, we obtain
\begin{align*}
\langle x^*-x_t, \theta^* \rangle &\leq |\langle x^*-x_t, \theta^* \rangle| \\
&\leq |\langle x^*, \theta^* \rangle| + |\langle x_t, \theta^* \rangle| \\
&\leq \|x^*\|\cdot\|\theta^*\| + \|x_t\|\cdot\|\theta^*\| \\
&\leq 2 \; \tag{10}.
\end{align*}
Therefore, the following bound on cumulative expected regret holds
\begin{align*}
\mathcal{R}(T) &\leq 2T\cdot \mathbb{P}(E^c)+\mathbb{E}\left[\sum_{t=1}^T\langle x^*-x_t, \theta^* \rangle\bigg| E \right] \cdot \mathbb{P}(E) \\
&\leq \Ocal(1) + \mathbb{E}\left[\sum_{t=1}^T\langle x^*-x_t, \theta^* \rangle\bigg| E \right] \; .
\end{align*}
From now on, we assume that $E$ occurs. We claim that $x^* \in \mathcal{A}_{\ell}$ for $1 \leq \ell \leq B$. We prove this by mathematical induction. For $\ell = 1$, since $x^* \in \mathcal{A}_0$, we obtain
\begin{align*}
\langle \hat{\theta}_{1}, \hat{x}_{1}^*-x^* \rangle
&= \langle \hat{\theta}_{1} - \theta^* + \theta^*, \hat{x}_{1}^*-x^* \rangle \\
&= \langle \hat{\theta}_{1} - \theta^*, \hat{x}_{1}^* - x^* \rangle + \langle \theta^*, \hat{x}_{1}^* - x^* \rangle \\
&\leq \varepsilon_1 \; . 
\end{align*}
Therefore, $x^* \in \mathcal{A}_1$ holds, establishing the base case. Now assume $x^* \in \mathcal{A}_{\ell-1}$. Then
\begin{align*}
\langle \hat{\theta}_{\ell}, \hat{x}_{\ell}^*-x^* \rangle
&= \langle \hat{\theta}_{\ell} - \theta^* + \theta^*, \hat{x}_{\ell}^*-x^* \rangle \\
&= \langle \hat{\theta}_{\ell} - \theta^*, \hat{x}_{\ell}^* - x^* \rangle + \langle \theta^*, \hat{x}_{\ell}^* - x^* \rangle \\
&\leq \varepsilon_\ell \; .
\end{align*}
Therefore, $x^* \in \mathcal{A}_{\ell}$ holds. By induction, we conclude that $x^* \in \mathcal{A}_{\ell}$ for all $1 \leq \ell \leq B$.
\\
For each suboptimal arm $x(\neq x^*)$, define $\ell_x \coloneqq \min\{\ell\,|\, \Delta_x > 2\varepsilon_\ell\}$ as the first phase where the suboptimality gap of arm $x$ is larger than $2\varepsilon_\ell$. If a suboptimal arm $x(\neq x^*)$ is not eliminated in the first $\ell_{x}-1$ batches, after the $\ell_x$-th batch, we obtain
\begin{align*}
\langle \hat{\theta}_{\ell_x}, \hat{x}_{\ell_x}^{*}- \; x \rangle &\geq \langle \hat{\theta}_{\ell_x}, x^*- \;x \rangle \\
&= \langle \hat{\theta}_{\ell_x}-\; \theta^*+\theta^*, x^*-\; x \rangle \\
&= \langle \hat{\theta}_{\ell_x}-\; \theta^*, x^*-\;x \rangle + \langle \theta^*, x^* - \;x \rangle \\
&\geq -\varepsilon_{\ell_x} + \Delta_x \\
&> \varepsilon_{\ell_x} \; .
\end{align*}
Therefore, we know suboptimal arm $x(\neq x^*)$ will be eliminated in the first $\ell_x$ batches
$$x \notin \mathcal{A}_{\ell_x}, \quad \forall x \in  \mathcal{A}_0 \backslash \{x^*\} \; .$$
Thus, for $\ell \geq 2$, the suboptimality gap of any arm included in $\mathcal{A}_{\ell-1}$ is smaller than $2\varepsilon_{\ell-1}$ in $\ell$-th batch, where
\[
\Delta_x \leq 2\varepsilon_{\ell-1}, \quad \forall x \in \mathcal{A}_{\ell-1} \; . \tag{11}
\]
Using the triangle inequality, we obtain the following bound for $\ell \geq 2$
\begin{align*}
M_\ell &= \underset{x,y \in \mathcal{A}_{\ell-1}}{\max}\|x-y\|_{H_\ell^{-1}}^2 \\
&\leq \underset{x,y \in\mathcal{A}_{\ell-1}}{\max}(\|x\|_{H_{\ell}^{-1}}+\|y\|_{H_{\ell}^{-1}})^2 \\
&\leq \underset{x \in\mathcal{A}_{\ell-1}}{\max} 4\|x\|_{H_{\ell}^{-1}}^2 \; . \tag{12}
\end{align*}
Let $\text{Regret}_{\ell}$ denote the cumulative expected regret of the $\ell$-th batch when $E$ occurs. Combining (11) and (12), we obtain the following bound of cumulative expected regret
\begin{align*}
\sum_{\ell=2}^{B}\text{Regret}_\ell &\leq \sum_{\ell=2}^{B} (T^{\frac{2^\ell-1}{2^{\ell}}}+|\mathcal{A}_{\ell-1}|) 2\varepsilon_{\ell-1} \\
&\leq \sum_{\ell=2}^{B} \frac{2\sqrt{M_{\ell-1}}\left(\sqrt{(d-1)\log(\frac{4}{4\zeta^2-\zeta^4})+2\log(2T\sqrt{2\pi d}(1+\lceil \log_2\log_2 T \rceil))} +\sqrt{\lambda}\right)}{(1-\zeta)/(T^{\frac{2^\ell-1}{2^{\ell}}}+|\mathcal{A}_{\ell-1}|)} \\
&\leq \sum_{\ell=2}^{B} \frac{4\underset{x\in \mathcal{A}_{\ell-2}}{\max}\|x\|_{H_{\ell-1}^{-1}}\left(\sqrt{(d-1)\log(\frac{4}{4\zeta^2-\zeta^4})+2\log(2T\sqrt{2\pi d}(1+\lceil \log_2\log_2 T \rceil))} +\sqrt{\lambda}\right)}{(1-\zeta)/(T^{\frac{2^\ell-1}{2^{\ell}}}+|\mathcal{A}_{\ell-1}|)} \\
&\leq \sum_{\ell=2}^{B} \frac{4\sqrt{d}(T^{\frac{2^\ell-1}{2^{\ell}}}+|\mathcal{A}_{\ell-1}|)\left(\sqrt{(d-1)\log(\frac{4}{4\zeta^2-\zeta^4})+2\log(2T\sqrt{2\pi d}(1+\lceil \log_2\log_2 T \rceil))} +\sqrt{\lambda}\right)}{(1-\zeta)\sqrt{d\lambda+T^{\frac{2^{\ell-1}-1}{2^{\ell-1}}}c_{\ell-1}}}
\; .
\end{align*}
Here, we use 
\[\varepsilon_\ell \leq \sqrt{M_\ell} \cdot \frac{\sqrt{(d-1)\log(\frac{4}{4\zeta^2-\zeta^4})+2\log(2T\sqrt{2\pi d}(1+\lceil \log_2\log_2 T \rceil))} +\sqrt{\lambda}}{1-\zeta} \; .\]
Using $T\geq \Omega(K^\frac{4}{5})$ and $B \leq 1+ \lceil \log_2\log_2 T \rceil$, we derive the following bound for the cumulative expected regret incurred during the batches with $\ell \geq 2$
\begin{align*}
\sum_{\ell=2}^{B}\text{Regret}_\ell &= \sum_{\ell=2}^{B} \Ocal\left(\frac{(T^{\frac{2^\ell-1}{2^\ell}} + K)\left(\sqrt{d^2 + d\log(T\sqrt{d}\log\log T)} + \sqrt{d}\right)}{\sqrt{d+T^{\frac{2^{\ell-1}-1}{2^{\ell-1}}}}}\right) \\
&= \sum_{\ell=2}^{B} \Ocal\left(\frac{(\sqrt{T}+KT^{-\frac{2^{\ell-1}-1}{2^\ell}})\left(\sqrt{d^2 + d\log(T\log\log T)} + \sqrt{d}\right)}{\sqrt{dT^{-\frac{2^{\ell-1}-1}{2^{\ell-1}}}+1}}\right) \\
&= \Ocal\left(\frac{(B-1)(\sqrt{T} + KT^{-\frac{3}{4}})\sqrt{d^2 + d\log T}}{\sqrt{dT^{-\frac{2^{B-1}-1}{2^{B-1}}}+1}}\right) \\
&= \Ocal\left(\frac{(\sqrt{dT} + \sqrt{d}KT^{-\frac{3}{4}})\sqrt{d + \log T}\log\log T}{\sqrt{dT^{-1}+1}}\right) \\
&= \Ocal\left(\sqrt{dT}\sqrt{d + \log T}\log\log T\right) \\
&= \tilde{\Ocal}(d\sqrt{T}) \; .
\end{align*}
We can derive a similar upper bound using an alternative bound for $\varepsilon_\ell$,
\[
\varepsilon_\ell \leq \sqrt{M_\ell} \cdot \left(\sqrt{2\log\left(T(|\mathcal{A}_{\ell-1}|^2-|\mathcal{A}_{\ell-1}|)(1+\lceil \log_2\log_2T \rceil)\right)} + \sqrt{\lambda} \right)\; .
\]
This leads to the following bound for the cumulative regret after the second batch
\begin{align*}
\sum_{\ell=2}^{B}\text{Regret}_\ell &\leq \sum_{\ell=2}^{B} (T^{\frac{2^\ell-1}{2^{\ell}}}+|\mathcal{A}_{\ell-1}|) 2\varepsilon_{\ell-1} \\
&\leq \sum_{\ell=2}^{B} {2\sqrt{M_{\ell-1}}}(T^{\frac{2^\ell-1}{2^{\ell}}}+|\mathcal{A}_{\ell-1}|) \left(\sqrt{2\log(T(|\mathcal{A}_{\ell-2}|^2-|\mathcal{A}_{\ell-2}|)(1+\lceil \log_2\log_2T \rceil))}+\sqrt{\lambda}\right) \\
&\leq \sum_{\ell=2}^{B} {4\underset{x\in \mathcal{A}_{\ell-2}}{\max}\|x\|_{H_{\ell-1}^{-1}}}(T^{\frac{2^\ell-1}{2^{\ell}}}+|\mathcal{A}_{\ell-1}|) \left(\sqrt{2\log(T|\mathcal{A}_{\ell-2}|^2(1+\lceil \log_2\log_2T \rceil))}+\sqrt{\lambda}\right) \\
&\leq \sum_{\ell=2}^{B} \frac{4\sqrt{d}(T^{\frac{2^\ell-1}{2^{\ell}}}+|\mathcal{A}_{\ell-1}|)\left(\sqrt{2\log(T|\mathcal{A}_{\ell-2}|^2(1+\lceil \log_2\log_2T \rceil))}+\sqrt{\lambda}\right)}{\sqrt{d\lambda+T^{\frac{2^{\ell-1}-1}{2^{\ell-1}}}c_{\ell-1}}}
\end{align*}
Using $T\geq \Omega(K^\frac{4}{5})$ and $B \leq 1+ \lceil \log_2\log_2 T \rceil$, we derive the following bound for the cumulative expected regret incurred during the batches with $\ell \geq 2$
\begin{align*}
\sum_{\ell=2}^{B}\text{Regret}_\ell &= \sum_{\ell=2}^{B} \Ocal\left(\frac{\sqrt{d}(T^{\frac{2^\ell-1}{2^\ell}}+K)\left(\sqrt{\log(KT\log\log T)} +1\right)}{\sqrt{d+T^{\frac{2^{\ell-1}-1}{2^{\ell-1}}}}}\right) \\
&= \sum_{\ell=2}^{B} \Ocal\left(\frac{(\sqrt{dT} + \sqrt{d}KT^{-\frac{2^{\ell-1}-1}{2^{\ell}}})\left(\sqrt{\log(KT\log\log T)} +1\right)}{\sqrt{dT^{-\frac{2^{\ell-1}-1}{2^{\ell-1}}}+1}}\right) \\
&= \Ocal\left(\frac{(B-1)(\sqrt{dT} + \sqrt{d}KT^{-\frac{3}{4}})\left(\sqrt{\log(KT\log\log T)} +1\right)}{\sqrt{dT^{-\frac{2^{B-1}-1}{2^{B-1}}}+1}}\right) \\
&= \Ocal\left(\frac{(\sqrt{dT} + \sqrt{d}KT^{-\frac{3}{4}})\sqrt{\log(KT)}\log\log T}{\sqrt{dT^{-1}+1}}\right) \\
&= \Ocal\left({\sqrt{dT\log(KT)}\log\log T}\right) \\
&= \tilde{\Ocal}(\sqrt{dT\log K}) \; . \\
\end{align*}
Thus, the regret except for the first batch is bounded by
$$\sum_{\ell=2}^{B}\text{Regret}_\ell = \Ocal\big( \sqrt{dT}\big(\sqrt{\log(KT)}\wedge \sqrt{d+\log T}\big)\log\log T \big) = \tilde{\Ocal}\big(\sqrt{dT\log K}\wedge d\sqrt{T}\big) \; .$$
Using (10) and $T \geq \Omega(\frac{K^2}{(d \, \wedge \, \log K)d})$, the cumulative expected regret for the first batch can be easily bounded as follows
$$\text{Regret}_1 \leq 2(\sqrt{T}+K) = \Ocal\big(\sqrt{dT\log K}\wedge d\sqrt{T}\big) \; .$$
Thus, the worst-case regret is given by 
\[
\mathcal{R}(T) = \Ocal\big( \sqrt{dT}\big(\sqrt{\log(KT)}\wedge \sqrt{d+\log T}\big)\log\log T \big)  = \tilde{\Ocal}\big(\sqrt{dT\log K}\wedge d\sqrt{T}\big) \; .
\] 
\end{proof}

\section{Additional Experiments}\label{sec:additional-experiments}
\subsection{Runtime Comparison Analysis} \label{sec:runtime-comparison}
We provide a runtime comparison with batched linear bandit algorithms in \citet{ruan2021linear,hanna2023contexts,zhang2025almost}. The experiments were conducted with $K=50$ arms and a feature dimension of $d=5$, where all arms and the unknown parameter $\theta^*$ were sampled from a normal distribution. Under the same experimental setting, the \texttt{BLAE} algorithm requires only $7.3$ seconds for 10 runs when $T =$ 100,000. 
In contrast, as shown in Table~\ref{table:runtime-with-Ruan-and-Hanna}, the algorithm in \citet{ruan2021linear} requires $4642.2$ seconds for just $T=5000$, while the algorithm in \citet{zhang2025almost} takes $7178.1$ seconds for $T=5000$, demonstrating their limitation in large-scale problems. 
Furthermore, the algorithm in \citet{hanna2023contexts} faces severe computational challenges due to the construction of $\Theta'$ as mentioned in Section~\ref{sec:reason of fail}. The size of $\Theta'$ is $\mathcal{\Ocal}(T^d)$, meaning that for $T=1000$, $\Theta'$ would contain approximately $10^{15}$ vectors, making the algorithm infeasible even for moderate values of $T$. 
Due to these computational constraints, we were unable to measure its runtime. From this experiment, we conclude that the batched linear bandit algorithms proposed in \citet{ruan2021linear,zhang2025almost,hanna2023contexts} are impractical for our setting.
