\section{Proof of Theorem~\ref{thm:approx_lev_scores}}
\label{appendix:proof_thm_leverage_approximation}
\setcounter{thm}{2}
\begin{usethmcounterof}{thm:approx_lev_scores}
    Let data matrix $\K \in \R^{N \times d}$ and target dimension $k=\lceil r \cdot N \rceil$ be given. Let distortion factor $\epsilon \in (0, 1)$ and failure probability $\delta \in (0, 1)$ be given. Define $\mathbf \Phi \in \mathbb R^{d \times k}$ be a matrix whose entries are drawn i.i.d from $\mathcal N (0, \frac{1}{k})$. Compute the SVD of the sketched matrix $\mathbf {K \Phi}$ and approximate leverage scores $\tilde \ell_i$ as: 
    \[
    \textsc{svd}\left(\K\mathbf\Phi \right)= \mathbf {\tilde U} \mathbf{\tilde \Sigma} \mathbf{\tilde V}^\top \qquad \qquad \tilde \ell_i = ||\tilde U_i||_2^2 
    \]
    If $k \geq 12 \epsilon^{-2} \left(\operatorname{rank}(\K) \log (42\epsilon^{-1}) + \log(2\delta^{-1})\right)$
    Then we have that with probability $1- \delta$
    \[
    \kappa(\K)^{-1}\frac{1 - \epsilon}{(1 + \epsilon)} \ell_i \leq  \tilde \ell_i \leq  \kappa(\K) \frac{1 + \epsilon}{1 - \epsilon} \ell_i \qquad \qquad \forall i \in [N]
    \]
    where $\kappa(\K)$ is the condition number of $\K$.
\end{usethmcounterof}
\begin{proof}
    The proof of the above is straightforward. It relies on the following intermediary result from \cite{gilbert_sketched_2012}:
    \begin{cor}
        \label{cor:gilbert}
        Suppose $\mathbf \Phi$ and $k$ are chosen as above, then we have that with probability $1 - \delta$ 
        \[
        (1 - \epsilon) \leq \frac{(\sigma'_j)^2}{\sigma^2_j} \leq (1 + \epsilon)
        \]
        where $\sigma_j$ denote the singular values of $\mathbf K$ and $\sigma'_j$ denote the singular values of $\mathbf K\Phi$.
    \end{cor}
    Note that Corollary~\ref{cor:gilbert} also applies to the case of right sketching $\mathbf K$. Now consider the following SVDs 
    \[
    \mathbf K\mathbf\Phi = \tilde {\mathbf U} \tilde {\mathbf\Sigma} \tilde {\mathbf V}^\top  
    \qquad \qquad     \mathbf K = \mathbf U \mathbf \Sigma \mathbf V^\top  
    \]
    Because $\Phi$ is a subspace embedding, we have the following relationships between the norms of each row $K_i$ and $(K \Phi)_i$
    \[
    (1 - \epsilon)||K_i||^2_2 \leq ||(\mathbf K \mathbf \Phi)_i||_2^2 \leq (1 + \epsilon)||K_i||^2_2
    \]
    Because $\mathbf V$ is a unitary transformation, we further have that 
    \[
    (1 - \epsilon)||U_i\mathbf\Sigma||^2_2 \leq ||\tilde U_i \tilde {\mathbf \Sigma}||_2^2 \leq (1 + \epsilon)||U_i \mathbf\Sigma||^2_2
    \]
    We can define $m = \min_{i} \mathbf\Sigma_i^2$ and $M = \min_{i} \mathbf\Sigma_i^2 $ and $m' = \min_{i} \tilde {\mathbf{\Sigma}}_i^2$ and $M' = \min_{i} \tilde {\mathbf \Sigma_i}^2 $. It follows that $m' \leq (1 - \epsilon) m $ and $M' \leq (1 + \epsilon) M$. This implies the following bounds,
    \begin{equation*}
            \|\tilde U_i\|^{2}\geq\frac{1}{M'}\|\tilde U_i\tilde {\mathbf \Sigma}\|^{2}\ge\frac{1-\varepsilon}{M'}\|U_i\mathbf \Sigma\|^{2}\ge \frac{1-\varepsilon}{M'}m\|U_i\|^{2}
    \end{equation*}
\[
\|\tilde U_i\|^{2}\le\frac{1}{m'}\|\tilde U_i\tilde{\mathbf \Sigma}\|^{2}\le\frac{1+\varepsilon}{m'}\|U_i\mathbf\Sigma\|^{2}\le\frac{1+\varepsilon}{m'}M\|U_i\|^{2}
\]
Denote the condition number $\kappa_\Sigma = \frac{M}{m}$, and inserting the above bounds yields the following:
\[
\frac{1-\varepsilon}{1+\varepsilon}\frac{1}{\kappa_\Sigma}\|U_i\|^{2}
\leq
\|\tilde U_i\|^{2}
\le
\frac{1+\varepsilon}{1-\varepsilon}\kappa_\Sigma\|U_i\|^{2}
\]
which immediately implies the stated bound.
\end{proof}
\section{Non-Causal Attention Matrices}
\label{appendix:non_causal_attn_mat}
\begin{figure}[h]
  \centering
