    \multicolumn{2}{c}{}                                            & Sloth ($\gamma$) & No Sloth ($1-\gamma$) \\ \hline
    \multirow{2}{*}{MA} & Inspection ($\epsilon$)      & (${\tilde{U}^{p}_{MA}},~\tilde{U}^{p}_{MP}$)                             & (${\bar{U}_{MA}},~ U_{MP}$)                                  \\ \cline{2-4} 
