\begin{figure}[!t]
    \begin{center}
        \includegraphics[width=1\linewidth]{imgs/zhan13.pdf}
        \caption{The comparison results with varied $\epsilon_0$ and fixed $\gamma_0 = 0.5$, where (a) is the averaged utility of MA, (b) is the averaged utility of MP, and (c) is the averaged social welfare.}
        \label{fig13}
