\subsection{Geometric Control}

Let $y_d:\mathbb{T} \rightarrow \mathbb{Y}$ be a desired $\mathcal{C}^4$ position trajectory\footnote{ A function is $\mathcal{C}^k$ if it is $k$-times continuously differentiable. Computing $\dot{w}_d(t)$ requires the fourth derivative of $y_d$ with respect to time.}. As presented in Fig.~\ref{fig:frames}, the desired rotation matrix $R_d(t) = [b_{d,1}(t), b_{d, 2}(t), b_{d,3}(t)] \in \mathrm{SO}(3)$ where $b_{d, 1}(t)$, $b_{d, 2}(t)$ and $b_{d, 3}(t)$ are chosen as follows~\cite{lee2010geometric, serry2024reach}. The details are also illustrated in~\ref{apped:R_d}. The corresponding angular velocity is $\omega_d(t) = (R_d^{\top}(t) \dot{R}_d(t))^{\vee} \in \mathbb{R}^3$. 


Let $y_{\text{tr}}:\mathbb{T} \rightarrow \mathbb{R}^3$ be a tracking trajectory with rotation matrix $R(t) \in \mathrm{SO}(3)$ and angular velocity $\omega(t) \in \mathbb{R}^3$. The positive gain matrices $K_p$, $K_v$, $K_R$, and $K_\omega$ are defined as
$K_{*}=\operatorname{diag}(k_{*_1}, k_{*_2}, k_{*_3})$, for $* \in \{p, v, R, \omega\}$. Define the position, velocity, weighted rotational, and angular velocity errors as $e_p(t)$, $e_v(t)$, $e_{K,R}(t)$, $e_{\omega}(t) \in \mathbb{R}^3$, and the attitude error function $\Psi_K(t) \in \mathbb{R}$~\cite{invernizzi2017geometric}: 
\begin{align}
e_p(t) & :=y_{\text{tr}}(t)-y_d(t), \label{eq.e_p}\\
e_v(t) & :=\dot{y}_{\text{tr}}(t)-\dot{y}_d(t), \label{eq.e_v}\\
e_{K,R}(t) & :=\frac{1}{2}\left(K_RR^{\top}_d(t)R(t) -R^{\top}(t) R_d(t)K_R\right)^{\vee}, \label{eq.e_{K,R}} \\
e_\omega(t) & :=\omega(t)-R^{\top}(t) R_d(t)\omega_d(t), \label{eq.e_omega}\\
\Psi_K(t)  &:= \frac{1}{2}\operatorname{tr}\left(K_R(\mathrm{I}_3-R_d^{\top}(t) R(t))\right).
\label{eq.Psi(t)}
\end{align}
In this letter, the force $f(t)$ and torque $\tau(t)$ are defined as:
\begin{flalign}
&f(t) = F^{\top}_d(t)R(t) e_3, \label{eq.f} \\
&F_d(t)=-K_p e_p(t)-K_v e_v(t)+m g e_3+m \ddot{y}_d(t), \label{eq.Fd} \\
&\tau(t)= \!-e_{K,R}(t)-K_\omega e_\omega(t)+\omega(t) \times J \omega(t) \notag \\
& -J\left(\hat{\omega}(t) R^{\boldsymbol{\top}}(t) R_d(t) \omega_d(t)\!-\!R^{\top}(t) R_d(t) \dot{\omega}_d(t)\right).
\label{eq.tau}
\end{flalign}

\begin{proposition}[{Adapted from \cite{lee2012robust}; see also \cite[Prop.~1]{invernizzi2017geometric}}]
\label{prop:Inequality_Psi_K}
Supposing $K_R$ has distinct positive diagonal entries, define
$$
\begin{aligned}
h_1&=\min \left\{k_{R_1}+k_{R_2}, k_{R_1}+k_{R_3}, k_{R_2}+k_{R_3}\right\}, \\
h_2&=\max \left\{\left(k_{R_1}-k_{R_2}\right)^2,\left(k_{R_1}-k_{R_3}\right)^2,\left(k_{R_2}-k_{R_3}\right)^2\right\}, \\
h_3&=\max \left\{k_{R_1}+k_{R_2}, k_{R_1}+k_{R_3}, k_{R_2}+k_{R_3}\right\}.
\end{aligned}
$$
If $\Psi_K(t) < \psi < h_1$ for some positive $\psi$, then 
\begin{align}
g_1\,\|e_{K,R}(t)\|^2 \leq \Psi_K(t) \leq g_2\,\|e_{K,R}(t)\|^2,
\label{eq.g_1&_2}
\end{align}
where $g_1=\frac{h_1}{h_2+h^2_3}$ and $g_2=\frac{h_3}{h_1\left(h_1-\psi\right)}$. 
\end{proposition}



\subsection{Bézier Curves}

In this letter, a continuous-time desired position trajectory $y_d(t): \mathbb{T} \rightarrow \mathbb{Y}$ is parameterized by $N$ piecewise Bézier curves. Specifically, with a sampling time $\Delta t=\frac{T}{N}$, the desired trajectory $y$ is defined as follows:
\begin{equation}
y_d(t)= 
\begin{cases}
B_0(t), & t \in\left[t_0, t_1\right], \\ 
B_1(t), & t \in\left[t_1, t_2\right], \\ 
\vdots & \\ 
B_{N-1}(t), & t \in\left[t_{N-1}, t_{N}\right],
\end{cases}
\label{eq.y(t)}
\end{equation}
where $t_k=k \Delta t$ for $k=\{0, 1, \dots, N-1\}$. Each $B_k(t)$ is an $n$-degree Bézier curve defined as
\begin{equation}
B_k(t) = \sum_{i=0}^n b_i^n(\tau) c_{k,i}, \quad \tau = \frac{t - t_k}{\Delta t} \in [0,1],
\end{equation}
where $c_{k, i}$ is the $i$-th control point of the $k$-th Bézier curve, and $b_i^n(\tau)=\binom{n}{i}(1-\tau)^{n-i} \tau^i$ is the $n$-degree Bernstein polynomial. Since $\sum_{i=0}^n b_i^n(\tau)=1$ for any $\tau \in[0,1]$, this implies that each $B_k(t)$ lies within the convex hull $\mathcal{C H}_k:=\operatorname{conv}\left\{c_{k, 0}, \ldots, c_{k, n}\right\}$.

\subsection{Signal Temporal Logic}
Given a vector-valued function $\mu$ defined on $\mathbb{Y}$, an atomic predicate $\pi$ can be constructed as $\pi:=\mu(x)=b-H x \geq 0$, which evaluates to $\textit{true}$ iff the point $x$ lies inside the convex polytope $\operatorname{Poly}(H, b)$. In this work, only predicates of this form are considered. In particular, $x \in \operatorname{Poly}(H, b)$ if and only if $\mu(x) \geq 0$. The syntax of STL is defined as:
\begin{equation}
\varphi:= \pi \mid \neg \varphi \mid  \varphi_1 \wedge \varphi_2 \mid \varphi_1 \lor \varphi_2 \mid \varphi_1 \mathcal{U}_{I} \varphi_2,
\end{equation}
where $\neg$, $\wedge$ and $\lor$ are negation, conjunction and disjunction operators, respectively; $I=[a, b] \subseteq \mathbb{T}$ is a bounded time interval and $I$ is a non-singleton bounded interval ($a<b$); and $\mathcal{U}_I$ is \textit{Until}, which means $\varphi_2$ will be true at some point within $I$, \textit{until} that moment, and $\varphi_1$ has to remain true. Other temporal operators, \textit{Eventually} ($\Diamond$) and \textit{Always} ($\square$) can be formulated by the above operators. For instance, $\Diamond_{I} \varphi :=\text { True } \mathcal{U}_{I}$ and $\square_{I} \varphi:=\neg\left(\Diamond_{I} \neg \varphi\right)$. 

\begin{definition}{(STL semantics~\cite{donze2010robust})} 
\label{def. continuous semantic}
Given an STL specification $\varphi$ and a continuous-time signal $y: \mathbb{T} \rightarrow \mathbb{Y}$, STL semantics is defined over suffixes of signals as follows: 
$$
\begin{array}{lll}
(y, t) \models \pi & \Leftrightarrow & \mu(y(t)) > 0; \\ 
(y, t) \models \neg \varphi & \Leftrightarrow & \neg ((y, t) \models \varphi); \\
(y, t) \models \varphi_1 \wedge \varphi_2 & \Leftrightarrow & (y, t) \models \varphi_1 \wedge(y, t) \models \varphi_2; \\
(y, t) \models \varphi_1 \vee \varphi_2 & \Leftrightarrow & (y, t) \models \varphi_1 \vee(y, t) \models \varphi_2 ;\\
(y, t) \models \Diamond_{I}  \varphi & \Leftrightarrow & \exists t^{\prime} \in \tilde{I},\left(y, t^{\prime}\right) \models \varphi; \\
(y, t) \models \square_I \varphi & \Leftrightarrow & \forall t^{\prime} \in \tilde{I},\left(y, t^{\prime}\right) \models \varphi;\\
(y, t) \models \varphi_1 \mathcal{U}_{[a, b]} \varphi_2 & \Leftrightarrow & \exists t^{\prime} \in \tilde{I} \left(y, t^{\prime}\right) \models \varphi_2 \\
& & \wedge \forall t^{\prime \prime} \in\left[t, t^{\prime}\right],\left(y, t^{\prime \prime}\right) \models \varphi_1,\\
\end{array}
$$
where $\tilde{I} = (t+I) \cap \mathbb{T}$ and $ t+I=\left[t+a, t+b\right]$. The notation $(y, t) \models \varphi$ indicates that the signal suffix $(y, t)$ satisfies the STL formula $\varphi$, while $(y, t) \not\models \varphi$ denotes that it does not. For brevity, note that $y \models \varphi$ if $(y, 0) \models \varphi$.
\end{definition}

A time-varying robust trajectory is introduced to characterize whether a trajectory robustly satisfies the STL specification $\varphi$ at each time instant.

\begin{definition} (Time-varying robust trajectory~\cite{yuan2024signal})
\label{def:Time-varying Robustness}
Given a function $\rho^\varphi: \mathbb{T} \to \mathbb{R}_{>0}$, a position trajectory $y: \mathbb{T} \rightarrow \mathbb{Y}$ is said to be $\rho^\varphi$-robust with respect to an STL specification $\varphi$ if $\tilde{y} \models \varphi$  for every trajectory $\tilde{y}$ satisfying
\begin{equation}
\left\|\tilde{y}(t) - y(t)\right\| \leq \rho^\varphi(t),\quad \forall t \in \mathbb{T}.  
\end{equation}
\end{definition}

Note that $\rho^{\ell, \varphi}(t)$ is denoted as the time-varying robustness margin associated with the $\ell$-th agent’s desired trajectory with respect to the STL specification $\varphi$. 



\section{Problem Statement}
\label{sec:PS}

Given an STL specification $\varphi$, this letter aims to synthesize desired trajectories and a feedback controller for multiple quadrotors, ensuring their tracked trajectories $y_{\text{tr}}$ satisfy $\varphi$. To formalize the required robustness margin, a lower time-varying robustness bound $\gamma(t)$ is introduced as follows. 

\begin{definition}(Lower time-varying robustness bound) \label{def.MinTVRobust} 
Let $\gamma_c>0$ be a constant safety margin and let $\Gamma:\mathbb{T}\to\mathbb{R}_{>0}$ be a non-increasing function, i.e., $\Gamma(t)\le\Gamma(0)$ for all $t\in\mathbb{T}$.
The lower time-varying robustness bound $\gamma(t)$ is defined as 
\begin{equation}
\gamma(t):= \Gamma(t) + \gamma_c, \quad t \in \mathbb{T}.     
\end{equation} 
\end{definition}

Here $\Gamma(t)$ bounds the position tracking error, and $\gamma_c$ serves as a physical safety margin (e.g., quadrotor size). Thus, if $y_d(t) \models \varphi$ with robustness margin $\rho^{\varphi}(t)$ and $\rho^{\varphi}(t) \geq \gamma(t)>\Gamma(t)$, implying
\begin{equation}
\left\|y_{t r}(t)-y_d(t)\right\| \leq \Gamma(t)<\rho^{\varphi}(t) \Rightarrow y_{t r}(t) \models \varphi.
\end{equation}
Hence, the synthesis problem splits into two subproblems.

% \textit{Problem 1}: Derive the position tracking error bound for the geometric controller \eqref{eq.f}-\eqref{eq.tau} with the multidimensional control gains, so as to obtain the non-increasing lower time-varying robustness bound $\Gamma(t) \leq \Gamma(0)$.

\textit{Problem 1}: Compute the multidimensional control gains for the geometric controller in~\eqref{eq.f}–\eqref{eq.tau} and determine the position error bound, thereby obtaining a non-increasing lower time-varying robustness bound $\Gamma(t)$. 

\textit{Problem 2:}  Given an STL specification $\varphi$, a reference trajectory $y^{\ell}_{d}$ in \eqref{eq.y(t)} for each $\ell$-th agent is generated, such that $y^{\ell}_{d} \models \varphi$ with a robustness margin $\rho^{\ell, \varphi}(t) \geq \gamma(t) \geq \Gamma(t)$, while ensuring multi-agent safety and satisfying the element-wise velocity constraints $|\dot{y}_d^{\ell}(t)| \leq v_{\max } $ and $|\dot{y}_{\text{tr}}^{\ell}(t)| \leq v_{\max }$.


\section{Tracking Error Bounds}
\label{sec:expdecayerror}

In this section, the error bounds of the geometric controller and the corresponding initial conditions are first analyzed in Section~\ref{subsec:ErrorBoundAnalysis}. Then, an optimization problem is formulated in Section~\ref{subsec:opt-basedCG} to determine control gains such that the resulting error bounds satisfy the requirements stated in \textit{Problem 1} in Section~\ref{sec:PS}.

\subsection{Time-varying Error Bounds Analysis}
\label{subsec:ErrorBoundAnalysis}
The following analysis relies on known properties of geometric control~\cite{gamagedara2019geometric, invernizzi2017geometric, serry2024reach} and the controller defined in \eqref{eq.e_p}–\eqref{eq.tau}. To obtain tractable bounds on the tracking errors, a physical limit on the desired acceleration is first imposed.


\begin{assumption}[{\cite{gamagedara2019geometric}}]
\label{Assump:acc_d}
 Assume there exists a positive vector $b_{a} \in \mathbb{R}_{>0}^3$ such that the second derivative of $y_d$ satisfies
\begin{align}
\left|mg e_3+m\ddot{y}_d(t)\right| \leq b_{a}, \forall t \in \mathbb{T}
\label{eq.|ge_3+ay|<B1}
\end{align}
\end{assumption}  
This assumption bounds the desired trajectory’s acceleration and facilitates subsequent analysis of error bounds.

\subsubsection{Lyapunov Function for Translation-error Dynamics}
Let the translation-error vector be 
 $z^{\top}_1(t):= \begin{bmatrix}
e^{\top}_p(t) ~e^{\top}_v(t)
\end{bmatrix}$. Choose the Lyapunov candidate $\mathcal{V}_1$ as 
\begin{align}
\mathcal{V}_1(t) :=z_1^{\top}(t) M_1 z_1(t), \label{eq.V_1(t)}
\end{align}
where
\begin{align}
& M_1 =\frac{1}{2} \begin{bmatrix}
K_p & c_1\mathrm{I}_3\\
c_1\mathrm{I}_3 & m \mathrm{I}_3
\end{bmatrix} \in \mathbb{S}^6_{++}, \label{eq.M_1}\\ %
&c_1 = \nu_1 \min \left\{\sqrt{m \underline{\lambda}\left(K_p\right)},\min_{i=1,2,3} \left(\frac{4 m k_{p_i} k_{v_i}}{k_{v_i}^2+4 m k_{p_i}}\right)\right\},
\end{align}
with a tuning constant $\nu_1 \in (0,1)$. Its time derivative is
\begin{align}
\dot{\mathcal{V}}_1(t) =  -z_1^{\top}(t) W_1 z_1(t) - \Delta_f^{\top}(t)\left[\frac{c_1}{m}\mathrm{I}_3 \; \mathrm{I}_3\right] z_1(t), \label{eq.dotV_1(t)}
\end{align}
where 
\begin{align}
& W_1 = \frac{1}{2m}\begin{bmatrix}
2c_1 K_p & c_1 K_v \\ c_1 K_v & 2m\left(K_v-c_1\mathrm{I}_3\right)
\end{bmatrix} \in \mathbb{S}^6_{++}, \\ %\label{eq.W_1}
& \Delta_f(t) =\left\|F_d(t)\right\| \left(\left( b_{3,d}(t) - b^{\top}_{3, d}(t) b_3(t)\right)b_3(t)\right).
\end{align}


\subsubsection{Lyapunov Function for Rotational-error Dynamics}

Define $z^{\top}_2(t):= \begin{bmatrix}
e^{\top}_{K,R}(t) ~e^{\top}_\omega(t)
\end{bmatrix}$ as the rotational error vector and let the Lyapunov candidate function be
\begin{align} \mathcal{V}_2(t) := \frac{1}{2} e_\omega^{\top}(t) J e_\omega(t) + \Psi_K(t) + c_2 e_{K,R}^{\top}(t) e_\omega(t), \label{eq.V_2(t)} \end{align}
where 
\begin{equation}
\begin{aligned}
&c_2 := \nu_2 \min \Bigg\{\sqrt{2 g_m \underline{\lambda}(J)}, \; \frac{\sqrt{2} \underline{\lambda}(K_\omega)}{\operatorname{tr}(K_R)}, \\
& \qquad \qquad \qquad \qquad \min_{i =1,2,3} \frac{4 J_i k_{\omega_i}}{2 \sqrt{2} J_i \operatorname{tr}(K_R) + k_{\omega_i}^2} \Bigg\},
\end{aligned}
\end{equation}
with $g_m =\min\{g_1, g_2\}$ and $\nu_2 \in (0,1)$. 
From \eqref{eq.g_1&_2}, $\mathcal{V}_2(t)$ is bounded by
\begin{align}
z_2^{\top}(t) & M_{2,1} z_2(t) \leq \mathcal{V}_2(t) \leq z_2^{\top}(t) M_{2,2} z_2(t),
\label{eq.V_2_bounds}
\end{align}
where $M_{2,1}, M_{2,2} \in  \mathbb{S}_{++}^6$ are defined as
\begin{equation}
\begin{aligned}
M_{2,1} = \frac{1}{2} \begin{bmatrix} 
2g_1 \mathrm{I}_3 & c_2 \mathrm{I}_3 \\
c_2 \mathrm{I}_3 & J
\end{bmatrix}, %\label{eq.M_21}
M_{2,2} = \frac{1}{2} \begin{bmatrix}
2g_2 \mathrm{I}_3 & c_2 \mathrm{I}_3 \\
c_2 \mathrm{I}_3 & J
\end{bmatrix}.  %
\end{aligned}
\label{eq.M_21M_22} 
\end{equation}
The time derivative $\dot{\mathcal{V}}_2(t)$ satisfies:
\begin{align}
\dot{\mathcal{V}}_2(t) \leq -z_2^{\top}(t) W_2 z_2(t), \label{eq.dotV_2(t)}
\end{align}
where
\begin{align}
W_2 = \begin{bmatrix}
c_2 J^{-1} & \frac{c_2}{2} K_\omega J^{-1} \\
\frac{c_2}{2} K_\omega J^{-1} & K_\omega - \frac{c_2}{\sqrt{2}} \operatorname{tr}(K_R) \mathrm{I}_3
\end{bmatrix} \in \mathbb{S}_{++}^6. \label{eq.W_2}
\end{align}

\subsubsection{Time-varying Lyapunov Function Bound (see \ref{apped:Lyapunov_Bounds} for details)}
Combining \eqref{eq.V_2_bounds} and \eqref{eq.dotV_2(t)} and applying the Rayleigh quotient inequality yields
\begin{align}
\dot{\mathcal{V}}_2(t) \leq -\underline{\lambda}\left(M_{2,2}^{-\frac{1}{2}} W_2 M_{2,2}^{-\frac{1}{2}}\right) \mathcal{V}_2(t).
\end{align}

Applying the Grönwall–Bellman inequality yields
\begin{align}
\mathcal{V}_2(t) \leq e^{-\beta t} \mathcal{V}_2(0),
\end{align}
where $\beta :=\underline{\lambda}\left(M_{2,2}^{-\frac{1}{2}} W_2 M_{2,2}^{-\frac{1}{2}}\right)$. This further implies that $\sqrt{\mathcal{V}_2(t)} \leq  \mathcal{L}_2(\mathcal{V}_2(0), t)$ where 
\begin{align}
    \mathcal{L}_2(\mathcal{V}_2(0), t) := e^{-\frac{\beta}{2}t} \sqrt{\mathcal{V}_2(0)}.
\end{align}

Likewise, the bound on $\dot{\mathcal{V}}_1(t)$ in \eqref{eq.dotV_1(t)} can be obtained as: 
\begin{align}
\dot{\mathcal{V}}_1(t) \leq - (\alpha_0 - \alpha_1\sqrt{\mathcal{V}_2(t)})\mathcal{V}_1(t) + \alpha_2\sqrt{\mathcal{V}_2(t) \mathcal{V}_1(t)},
\label{eq.dot_V1_bound}
\end{align}
where
\begin{align}
\alpha_0 &= \underline{\lambda}\left(M_1^{-\frac{1}{2}} W_1 M_1^{-\frac{1}{2}}\right),  \label{eq.a0}\\ 
\alpha_1 &=\left\|\left[\frac{c_1}{m} \mathrm{I}_3, \mathrm{I}_3\right] M_1^{-\frac{1}{2}}\right\|\left\|\left[K_p, K_v \right] M_1^{-\frac{1}{2}}\right\| \beta^{\prime},  \label{eq.a1} \\
\alpha_2 
&=m\left\|b_a\right\|\left\|\left[\frac{c_1}{m} \mathrm{I}_3, \mathrm{I}_3\right] M_1^{-\frac{1}{2}}\right\| \beta^{\prime}, \label{eq.a2} \\
\beta^{\prime} &= \left\|\left[\mathrm{I}_3, \mathrm{0}_{3 \times 3} \right] M_{2,1}^{-\frac{1}{2}}\right\| \sqrt{\frac{4g_2}{h_1}}. \label{eq.beta_2}
\end{align}

Since $\sqrt{\mathcal{V}_2(t)} \leq \mathcal{L}_2(\mathcal{V}_2(0), t)$, using Grönwall’s inequality to \eqref{eq.dot_V1_bound} yields $\sqrt{\mathcal{V}_1(t)} \leq \mathcal{L}_1(\mathcal{V}_1(0), \mathcal{V}_2(0), t)$ where
\begin{align}
\mathcal{L}_1(\mathcal{V}_1(0), \mathcal{V}_2(0), t) & = 
e^{-\frac{\alpha_0 t}{2}}  \left[
e^{\frac{\alpha_1 \sqrt{\mathcal{V}_2(0)}}{\beta}} \sqrt{\mathcal{V}_1(0)} \right. \notag \\
& \left. + \frac{\alpha_2 \sqrt{\mathcal{V}_2(0)}}{2} \int_0^t e^{\frac{1}{2}(\alpha_0 - \beta) s} ds
\right].
\end{align}


It can be seen that both $\mathcal{L}_1\left(\mathcal{V}_1(0), \mathcal{V}_2(0), t\right)$ and $\mathcal{L}_2\left(\mathcal{V}_2(0), t\right)$ provide exponentially decaying upper bounds on the tracking errors over time. If there exist $\overline{\mathcal{V}}_1 \geq \mathcal{V}_1(0)$ and $\overline{\mathcal{V}}_2 \geq \mathcal{V}_2(0)$, then, $\mathcal{L}_1(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t) \geq \mathcal{L}_1(\mathcal{V}_1(0), \mathcal{V}_2(0), t)$ holds. From \eqref{eq.V_1(t)}, there exist the time-varying tracking error bounds $\|e_p(t)\| \leq \mathcal{L}_p(t)$ and $\|e_v(t)\| \leq \mathcal{L}_v(t)$ where
% $\|e_{K,R}(t)\| \leq \mathcal{L}_R(t)$ and $\|e_{\omega}(t)\| \leq \mathcal{L}_\omega(t)$ 
\begin{align}
\mathcal{L}_p(t) &:=\left\|\left[\mathrm{I}_3, \mathrm{0}_{3 \times 3} \right] M_1^{-\frac{1}{2}}\right\| \mathcal{L}_1(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t), \label{eq.Lpt}\\
\mathcal{L}_v(t) &:=\left\|\left[\mathrm{0}_{3 \times 3} , \mathrm{I}_3\right] M_1^{-\frac{1}{2}}\right\| \mathcal{L}_1(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t).\label{eq.Lvt}
% \mathcal{L}_R(t) &:= \left\|\left[\mathrm{I}_3, \mathrm{0}_{3\times 3}\right] M_{2,1}^{-\frac{1}{2}}\right\|\mathcal{L}_2(\overline{\mathcal{V}}_2, t), \label{eq.LRt}\\
% \mathcal{L}_\omega(t) &:= \left\|\left[\mathrm{0}_{3 \times 3}, \mathrm{I}_3\right] M_{2,1}^{-\frac{1}{2}}\right\|\mathcal{L}_2(\overline{\mathcal{V}}_2, t). \label{eq.Lwt}
\end{align}

Compared to~\cite{serry2024reach}, the proposed bounds are tighter, as they avoid over-approximating the entire system and are derived directly from $\mathcal{L}_1(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t)$. The following initial conditions specify how to choose $\overline{\mathcal{V}}_1$ and $\overline{\mathcal{V}}_2$ to determine the bounds $\mathcal{L}_p(t)$ and $\mathcal{L}_v(t)$.

\begin{proposition}[Initial conditions]
\label{prop.BoundsofError}
Given a $\mathcal{C}^4$-continuous trajectory $y_d:\mathbb{T} \rightarrow \mathbb{R}^3$ that satisfies \eqref{eq.|ge_3+ay|<B1}, if the tracking trajectory $y_{\text{tr}}$ meets the following initial error conditions:
\begin{align}
\Psi(0) & \leq \alpha_\psi \psi, \\
\frac{1}{2} e_\omega^{\top}(0) J e_\omega(0) & \leq \left(1-\alpha_\psi\right) \psi, \\
\mathcal{V}_1(0) & \leq \overline{\mathcal{V}}_1, \label{eq.v10<=barV1} 
\end{align}
where $\alpha_\psi \in (0,1)$, $\psi \in (0,h_1)$, and $\overline{\mathcal{V}}_1 \in (0, \infty)$ are user-defined. There exists
\begin{align}
\overline{\mathcal{V}}_2=\left(1 + c_2 \sqrt{\frac{2(1-\alpha_\psi)}{\underline{\lambda}(J)g_1}}\right) \psi \geq \mathcal{V}_2(0), \label{eq.v20<=barV2}
\end{align}
such that \eqref{eq.Lpt} and \eqref{eq.Lvt} are valid. 
\end{proposition}

The detailed proof can be found on \ref{apped:Error_Bounds}.

\subsection{Optimization-based Control Gains}
\label{subsec:opt-basedCG}

Selecting appropriate control gains is challenging due to the system's nonlinear dynamics. This letter obtains the control gains by minimizing $\mathcal{L}(\mathcal{V}_1, \mathcal{V}_2, t)$ to reduce the error bounds. To set up the optimization concisely, let $\zeta =\frac{\alpha_0-\beta}{2}$, $\bar{x} = \overline{\mathcal{V}}_1$, and $\bar{y} = \overline{\mathcal{V}}_2$. $\dot{\mathcal{L}}_1(\bar{x},\bar{y},t)$ is monotonic when $\zeta \neq 0$ and affine when $\zeta=0$, thus having at most one root. Let $t_c$ be the unique solution to $\tfrac{d}{dt}\,\mathcal{L}(\bar{x},\bar{y},t)=0$. Since $\ddot{\mathcal{L}}_1(\bar{x},\bar{y},t_c)<0$, it follows that
\begin{align}
\mathcal{L}_{1, \max}(\bar{x},\bar{y})
=\max_{t\in\mathbb{T}}\mathcal{L}_1(\bar{x},\bar{y},t)
=\mathcal{L}_1(\bar{x},\bar{y},t^{\ast}),
\label{eq.L1_max}
\end{align}
where $t^{\ast}:=\max\bigl(0,\min(t_c,T)\bigr)\in\mathbb{T}$ with
\begin{equation}
\hspace{-0.2cm}
t_c = \begin{cases}
\frac{2(\alpha_2 \sqrt{\bar{y}} - \alpha_0 \sqrt{\bar{x}} e^{\frac{\alpha_1 \sqrt{\bar{y}}}{\beta}})}{\alpha_0 \alpha_2 \sqrt{\bar{y}}}, &\!\text{if } \zeta = 0,\\
\frac{1}{\zeta} \ln\left(\frac{\alpha_0(\alpha_2 \sqrt{\bar{y}} - (\alpha_0 - \beta)\sqrt{\bar{x}} e^{\frac{\alpha_1 \sqrt{\bar{y}}}{\beta}} )}{\beta \alpha_2 \sqrt{\bar{y}}}\right), &\!\text{if } \zeta \neq 0.
\end{cases}
\label{eq.t_c}
\end{equation}

Furthermore, to satisfy the condition in Proposition \ref{prop:Inequality_Psi_K}, it is required that $ \Delta_{K_R} \geq 3$ where 
\begin{align}
\hspace{-0.2cm} 
\Delta_{K_R}=\sum_{1 \leq i<j \leq 3} \Delta_{i j},
\Delta_{i j}= \begin{cases}1, &\!\! \left|K_{R_i}-K_{R_j}\right| \geq \epsilon_R, \\ 0, &\!\! \text { otherwise. }\end{cases}
\end{align}
Then, Problem~\ref{optprobm_1} is formulated and solved using the Differential Evolution algorithm, a global optimizer that requires no initial guess and supports parallel computation.
\begin{problem}
\label{optprobm_1}
The control gains $\left\{K_p, K_v, K_R, K_\omega\right\}$ and auxiliary parameters $\left\{\nu_1, \nu_2\right\}$ are determined by solving the following optimization problem:
\begin{equation}
\label{problem 1}
\begin{aligned}
\underset{\substack{
K_p, K_v, K_R, K_\omega, \\
\nu_1, \nu_2
}}{\argmin} & \qquad  \mathcal{L}_{1,\max}\left(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2\right)\\
\text {such that} \quad 
& 0 <\nu_1, \nu_2<1, \\
& \Delta_{K_R} \geq 3 \quad \text{(Proposition \ref{prop:Inequality_Psi_K})},\\
% & \mathcal{L}_p(0) \leq \mathcal{L}_{p,\text{init}} \quad \text{(If applicable)},\\
\underline{k} \leq K_{p_i}, & K_{v_i},  K_{R_i}, K_{\omega_i} \leq \bar{k}, \; i \in \{1,2,3\}.
\end{aligned}
\end{equation}
Here, $\underline{k}$ and $\bar{k}$ denote the lower and upper bounds of the control gains, respectively.
\end{problem}



\section{Reference Trajectory Construction} 
\label{sec:refTrajConstruction}
This section formulates an optimization problem over the control points of Bézier curves to ensure that the desired trajectory satisfies the STL specifications with a robustness margin, thereby guaranteeing that the tracking trajectory also adheres to the same specifications.

After solving Problem \ref{optprobm_1}, the tracking bound $\mathcal{L}_p(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t)$ can be obtained. Ensuring both reference trajectories and the track trajectories satisfy the STL specifications and according to the Definition \ref{def.MinTVRobust}, choose $\Gamma(t)$ as
\begin{align}
\Gamma(t)= \begin{cases}
   \mathcal{L}_p(t^*), & \text{if } t \leq t^*, \\
\mathcal{L}_p(t), & \text{otherwise}. 
\label{eq.Gamma(t)}
\end{cases}
\end{align}
Thus, $\gamma(t) = \Gamma(t)+\gamma_c$. All quadrotors are assumed to share the same physical configuration and Lyapunov parameters. If different models are used, it suffices to adapt $\Gamma(t)$ for each model to account for the corresponding bounds.
\begin{problem}
Given an STL specification $\varphi$ and $L$ quadrators, the objective is to determine each position trajectory $y^{\ell}_d: \mathbb{T} \rightarrow \mathbb{R}^3$ ($1 \leq \ell \leq L$), parameterized by $N$ piecewise $n$-degree Bézier curves as defined in \eqref{eq.y(t)}, where Bézier curve $B^{\ell}_k$ is $\rho^{\ell,\varphi}$-robustness, with the robustness measure $\rho^{\ell,\varphi}(t) = \rho_k^{\ell,\varphi}\left(\mathcal{C}^{\ell}_k, a^{\ell}_k\right) \geq \gamma(t_k) > 0$ for all $t \in \left[t_k, t_{k+1}\right]$ and $k \in\{0, \dots, N-1\}$. Here, $\rho_k^{\ell,\varphi}\left(\mathcal{C}^{\ell}_k, a^{\ell}_k\right)$ represents the robustness measure of $B^{\ell}_k$, which depends on the maximum acceleration $a^{\ell}_k \in \mathbb{R}^d$ and the control points of $B^{\ell}_k$, denoted by $\mathcal{C}^{\ell}_k:=\{c^{\ell}_{k, i}\}^n_{i=0}$. The resulting optimization problem is formulated as a mixed-integer convex program (MICP) to maximize time-varying robustness while minimizing control effort of the reference trajectory.
\begin{equation}
\begin{aligned}
\argmin_{\mathcal{C}^{\ell}_k, v^{\ell}_k, a^{\ell}_k} \; \sum^{L}_{l=0}\sum_{k=0}^{N-1} &- \mathcal{W}\rho_k^{\ell, \varphi}(\mathcal{C}^{\ell}_k, a^{\ell}_k) +\mathcal{Q}\left\|v^{\ell}_k\right\|_1+\mathcal{R}\left\|a^{\ell}_k\right\|_1 \\
\text {such that} \quad &
% (B^{\ell}_k)^{(4)}(t_{k+1})  = (B^{\ell}_{k+1})^{(4)}(t_{k+1}),\\
B^{\ell}_k \; \text{and}  \; B^{\ell}_{k+1}  \; \text{are} \; \mathcal{C}^4 \text{-continuous},\\
% & |(B^{\ell}_k)^{\prime}| \leq v_{max} - \mathcal{L}_v(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t)\mathbf{1}_3, \\
& |(B^{\ell}_k)^{\prime}| \leq v_{max}, \\
 & (B^{\ell}_k)^{\prime \prime}\text{ satisfies } \eqref{eq.|ge_3+ay|<B1}  \\ %\text{ and } \eqref{eq.ay_z>=Lf}, \\
& \rho_k^{\ell,\varphi}\left(\mathcal{C}^{\ell}_k, a^{\ell}_k\right)  \geq \gamma(t_k),
% & y_d, y_{\text{tr}}\models \varphi, 
\end{aligned}
\end{equation}
where $\mathcal{W},\mathcal{Q}, \mathcal{R} \in \mathbb{R}$ are user-defined weights, $v^{\ell}_k, a^{\ell}_k \in \mathbb{R}^3$ are the maximum velocity and acceleration of $B_k$ over $t \in [t_k, t_{k+1}]$, respectively. 
\end{problem}

\subsection{Dynamic Constraints}
The Bézier curves are required to satisfy the dynamic constraints, which apply uniformly to all agents. The index $\ell$ is omitted in this subsection. A key property is utilized: the $\mathfrak{q}$-th derivative of a degree-$n$ Bézier curve is a degree-$(n-\mathfrak{q})$ Bézier curve.

\subsubsection{\texorpdfstring{$\mathcal{C}^4$}{C4} Continuity Constraints}
To ensure $\mathcal{C}^4$ continuity at the junction $t = t_{k+1}$ between consecutive Bézier segments $B_k$ and $B_{k+1}$, five constraints are imposed on their control points, expressed as follows for $\mathfrak{q} \in \{0, 1, 2, 3, 4\}$:
\begin{equation}
\sum_{\mathfrak{p}=0}^\mathfrak{q}(-1)^\mathfrak{p}\binom{\mathfrak{q}}{\mathfrak{p}} c_{k,n-\mathfrak{p}} = \sum_{\mathfrak{p}=0}^\mathfrak{q}(-1)^{\mathfrak{q}-\mathfrak{p}}\binom{\mathfrak{q}}{\mathfrak{p}} c_{k+1, \mathfrak{p}}.
\label{eq.contn_contrs}
\end{equation}
These constraints enforce equality of the backward finite differences of the $k$-th Bézier curve's end control points and the forward finite differences of the $(k+1)$-th Bézier curve's start control points at the junction time.

\subsubsection{Velocity Constraints}
Since the Bernstein polynomial of $B_k$ satisfies $\sum_{i=0}^{n-1} b_i^{n-1}(\tau)=1$ for all $\tau \in[0,1]$, then, 
\begin{equation}
% \hspace{-0.3cm}
\begin{aligned}
|\dot{y}_d(t)| %&= |B_k^{\prime}(t)| \\
&\leq \frac{n}{\Delta t}\left|\sum_{i=0}^{n-1}b_i^{n-1}(\tau) \right| \max_i |c_{k, i+1}-c_{k,i}| \\
&\leq v_{k}, 
\end{aligned}
\end{equation}
where $v_k$ is the maximum velocity of $k$-th Bézier curve. For ensuring $|\dot{y}_{\text{tr}}| \leq v_{\max }$, choose $\tilde{\mathcal{L}}_v(t)=\mathcal{L}_v(t^{\ast})$ for $t\le t^{\ast}$ and $\tilde{\mathcal{L}}_v(t)=\mathcal{L}_v(t)$ otherwise; then enforce 
\begin{align}
    |c_{k, i+1}-c_{k,i}| &\leq \frac{v_{k}\Delta t}{n}, \forall i \in \{0, \ldots, n-1\},  \label{eq.|cp|<v_k}\\
    0 < v_{k} 
    & \leq  v_{max} - \tilde{\mathcal{L}}_v(t_k)\mathbf{1}_3.
    \label{eq.v_k<v_max}
\end{align}

\subsubsection{Acceleration Constraints}
Similarly, to guarantee that $B_k^{\prime \prime}$ satisfies \eqref{eq.|ge_3+ay|<B1}, let $\Delta^2 c_{k,i} := c_{k,i+2} - 2c_{k,i+1} + c_{k,i}$, the acceleration constraints are enforced as
\begin{align}
& |\Delta^2 c_{k,i}| \leq  \frac{a_{k}\Delta t^2}{n(n-1)}, \label{eq.|cp|<a_k}\\
& \left|g e_3+ \frac{n(n-1)}{\Delta t^2} (\Delta^2 c_{k,i})^{\top} e_3\right|\leq  b_{a},
\end{align}
where $a_k$ is the maximum acceleration of $k$-th Bézier curve.


\subsection{Multi-agent STL Satisfactions Encoding}
\label{Section_stlspec}

This section presents a encoding of the STL specification $\varphi$ to ensure that each agent's Bézier curve and its tracking trajectory $y_{\mathrm{tr}}$ satisfy $\varphi$. A binary variable $z_k^{\ell, \varphi}$ is introduced to indicate whether the Bézier segment $B_k$ satisfies the specification; specifically, if $z_k^{\varphi}$ is true, then $\left(B_k, t\right) \vDash \varphi$ for all $t \in$ $\left[t_k, t_{k+1}\right]$.

\subsubsection{Continuous-time Robustness of Bézier curves}

To ensure that the tracking trajectory satisfies the STL specification, the robustness of the Bézier curves is required to exceed the tracking error bounds.


% As mentioned in Definition \ref{def.MinTVRobust}, we set $\Gamma(t) = \mathcal{L}_p\left(\overline{\mathcal{V}}_1,\overline{\mathcal{V}}_2, t\right)$. Therefore, $\gamma(t) = \mathcal{L}_p\left(\overline{\mathcal{V}}_1,\overline{\mathcal{V}}_2, t\right)+ \gamma_c$. 
% Since $\mathcal{L}_p\left(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t\right)$ is an nonincreasing function, we choose $\gamma\left(t_k\right)$ as the minimum robustness for the $k$-th Bézier curve $B_k$ over $t \in\left[t_k, t_{k+1}\right]$. 
As stated in \textit{Problem 2}, the robustness of $B^{\ell}_k$ is set as $\rho_k^{\varphi}\left(\mathcal{C}^{\ell}_k, a^{\ell}_k\right)=r^{\ell}_k-\epsilon^{\ell}_k \geq \gamma\left(t_k\right)$, where $r^{\ell}_k \in \mathbb{R}_{>0}$ specifies a positive margin to guarantee that the endpoints of the curve lie strictly within the required set, and $\epsilon_k \in \mathbb{R}_{>0}$ represents the margin used to constrain the intermediate control points within the same set, subject to acceleration constraints~\cite{yuan2024signal}.
\begin{align}
&{\scalebox{0.8}{$\bullet$}} \ 
\text{Predicate } \pi:   \notag \\ 
&z_k^{\ell, \pi}  = \bigwedge_{i=1}^{\operatorname{Row}(H)} \left(\bigwedge_{j=\{0,n\}} \frac{b_i-H_ic^{\ell}_{k, j}}{\left\|H_i\right\|_2} \geq r^{\ell}_k \right) \wedge z_{\epsilon^{\ell}_k}
    \label{eq.predicate}. \\
&{\scalebox{0.8}{$\bullet$}} \ 
\text{Negation} \neg \pi:  \notag \\
&z_k^{\ell, \neg \pi} =  \bigvee_{i=1}^{\operatorname{Row}(H)} \left(\bigwedge_{j=\{0,n\}}  \frac{H_i c^{\ell}_{k, j} - b_i}{\left\| H_i \right\|_2} \geq r^{\ell}_k  \right) \wedge z_{\epsilon^{\ell}_k}. \label{eq.negation} 
\end{align}
where 
\begin{equation}
\begin{aligned}
z_{\epsilon^{\ell}_k} &:= \left( \bigwedge_{j=\{1,n\}} |c^{\ell}_{k,j} - c^{\ell}_{k, j-1}| \leq \frac{a^{\ell}_k \Delta t^2}{2n} \right)\\
    &\quad \bigwedge \left(\bigwedge^d_{j=0}\frac{8\epsilon^{\ell}_k}{3\sqrt{d} \Delta t^2}-|a_{k,j}| \geq 0 \right).
\label{eq.z_epsilon}
\end{aligned}
\end{equation}

Based on the atomic predicates, the logic and temporal operators are constructed as follows. Given the finite interval $\tilde{I}=(t+I) \cap \mathbb{T}$, let $k_{\ell}=k+\lfloor a / \Delta t\rfloor$ and $k_r=\min (k+1+\lfloor b / \Delta t\rfloor, N-1)$ for brevity. Assume $k_l<k_r$, which is a mild assumption since $a<b$ and $N-1$ are the maximum segment index.
\begin{align}
    {\scalebox{0.8}{$\bullet$}} \ 
    &\text{Conjunctions} \ \varphi_1 \wedge \varphi_2: z_k^{\ell,\varphi_1 \wedge \varphi_2} = z_k^{\ell,\varphi_1} \wedge z_k^{\ell,\varphi_2}. & \label{eq.conj}  \\
    {\scalebox{0.8}{$\bullet$}}  \ &\text{Disjunctions} \ \varphi_1 \vee \varphi_2: z_k^{\ell,\varphi_1 \wedge \varphi_2} = z_k^{\ell,\varphi_1} \vee z_k^{\ell,\varphi_2}.  & \label{eq.disjun}  \\
    {\scalebox{0.8}{$\bullet$}}  \ &\text{Always}  \ \square_I \varphi: z_k^{\ell,\square_{I} \varphi} = \wedge_{k^\prime=k_l}^{k_r}z_{k^\prime}^{\ell,\varphi}. 
    & \label{eq.always} \\
    {\scalebox{0.8}{$\bullet$}} \ & \text{Eventually} \ \Diamond_{I} \varphi:  
    z_k^{\ell,\Diamond_{I} \varphi} = \vee_{k^\prime=k_l}^{k_r}z_{k^\prime}^{\ell,\varphi}. 
   & \label{eq.eventually}\\
    \scalebox{0.8}{$\bullet$} \ & \text{Until} \ \varphi = \varphi_1 \mathcal{U}_{I} \varphi_2: & \ \notag \\
    & \qquad \qquad  z_k^{\ell,\varphi} = \bigvee_{k^{\prime}=k_l}^{k_r} \Big(z^{\ell,\varphi_2}_{k^{\prime}}  \bigwedge \wedge_{k^{\prime\prime}=k}^{k^{\prime}-1}z^{\ell,\varphi_1}_{k^{\prime\prime}}\Big). & \label{eq.Until} 
\end{align}
\subsubsection{Multi-agent Collision Avoidance Encoding}
To ensure safety guarantees between any two agents $i$ and $j$ (where $1 \leq i<j \leq L$), for any $t \in\left[t_k, t_{k+1}\right]$, the distance between their Bézier  curves $B_k^i(t)$ and $B_k^j(t)$  is required to remain at least $\epsilon_{\text {inter }}$. For simplicity, $\mathcal{C} \mathcal{H}_k^i$ and $\epsilon_k^i$ are grouped into the tuple $A_k^i=\left(\mathcal{C H}_k^i, \epsilon_k^i\right)$. Then, the multi-agent safety specification is defined as follows: 
\begin{equation}
z_{\text{inter}}=\bigwedge_{1 \leq i < j \leq L} \operatorname{safe}\left(A_k^i, A_k^j, \epsilon_{\text{inter}}\right),
\end{equation}
where
\begin{equation}
\begin{aligned} 
\operatorname{safe}\left(A_k^i, A_k^j, \epsilon_{\text {inter }}\right)&:=  \left(\left\|\operatorname{cent}\left(B_k^i\right)-\operatorname{cent}\left(B_k^j\right)\right\|_1\right. \\ \geq & \left\|c_{k, 0}^i-c_{k, n}^i\right\|_1+\left\|c_{k, 0}^j-c_{k, n}^j\right\|_1 \\ & \left.+2\left(\epsilon_k^j+\epsilon_k^i\right)+\epsilon_{\text {inter }} \sqrt{d}\right).
\label{eq.agents_safe}
\end{aligned}
\end{equation}
and $\operatorname{cent}(B^i_{k}) = \frac{1}{n+1}\sum^n_{l=0} c^i_{k, l}$ is the geometric center of the convex hull $\mathcal{CH}^i_k$. The distance between the two curves is bounded by:
\begin{equation}
\left\|B^i_{k}(t)-B^j_{k}(t)\right\| \geq \epsilon_{\text{inter}}. 
\end{equation}
The proof of the soundness of the multi-agent safety can be seen in \ref{apped:Multi-agents}.

\begin{remark}
The encoding for multi-agent safety is stricter, as it considers the full convex hull of each Bézier curve necessary to ensure inter-agent safety. However, due to acceleration constraints and a moderate number of control points, the conservatism introduced by the convex-hull approximation remains tractable. Moreover, the $\ell_1$-norm is used in place of the $\ell_2$-norm to enable convex, piecewise-linear formulations suitable for MICP solvers.
\end{remark}

% \textbf{Complexity.} For the single agent, the complexity $\mathcal{O}(N|\varphi|)$ binaries and $\mathcal{O}(N)$ reals. The cooperative formulation scales to $\mathcal{O}\left(L N|\varphi|+L^2 N\right)$ binaries and $\mathcal{O}(L N)$ (or slightly more) continuous variables, with the pair-wise safety term imposing the dominant computational burden as the team size grows.

\section{Experiments}
\label{sec:exp}
