\section{Multi-agent Collision Avoidance}
\label{apped:Multi-agents}
\setcounter{equation}{0}
\renewcommand{\theequation}{I.\arabic{equation}}

The radius (or span) of the $k$-th Bézier segment $B_k^i$ of the $i$-th agent quantifies that segment's spatial extent (compactness) and is defined as the maximum Euclidean distance between its geometric centroid, $\operatorname{cent}\left(B_k^i\right)$, and any of its control points:
\begin{align}
\operatorname{span}\left(B_k^i\right)=\max _{0 \leq l \leq n}\left\|c_{k, l}^i-\operatorname{cent}\left(B_k^i\right)\right\|_2
\end{align}
where $\operatorname{cent}\left(B_k^i\right)=\frac{1}{n+1} \sum_{l=0}^n c_{k, l}^i$. From constraints \eqref{eq.z_epsilon},  it is proved in~\cite{yuan2024signal} that, for $\forall l\in \{1,2, \dots, n\}$,
\begin{align}
\min \left\{\left\|c^i_{k, l}-c^i_{k, 0}\right\|_2,\left\|c^i_{k, l}-c^i_{k, n}\right\|_2\right\} \leq \epsilon^i_k, 
\end{align}
which illustrates that every control point $c^i_{k, l}$ is close to at least one of the endpoints $c^i_{k, 0}$ or $c^i_{k, n}$. Denote
$
m_k^*=(c^i_{k, 0}+c^i_{k, n})/2
$
as the midpoint of the segment connecting the endpoints. Without loss of generality, assume that $c^i_{k,l}$ is closer to $c_{k, 0}$ than to $c_{k, n}$. Then,
\begin{equation}
\begin{aligned}
\left\|c^i_{k,l}-m_k^*\right\|_2 & \leq\left\|c^i_{k,l}-c^i_{k, 0}\right\|_2+\left\|c^i_{k, 0}-m_k^*\right\|_2 \\
% & \leq \epsilon_k+\left\|c^i_{k, 0}-\frac{c^i_{k, 0}+c^i_{k, n}}{2}\right\|_2 \\
& = \epsilon^i_k+\frac{1}{2}\left\|c^i_{k, 0}-c^i_{k, n}\right\|_2.
\end{aligned}
\end{equation}
The same holds if closer to $c_{k, n}$. Therefore, 
\begin{equation}
\begin{aligned}
\|\operatorname{cent}(B^i_k) - m^*\|_2 & = \|\frac{1}{n+1}\sum^{n}_{l=0} c^i_{k,l} - m^{*}\|_2 \\
% &\leq \frac{1}{n+1}\sum^{n}_{l=0} \|c^i_{k,l}-m^{*}\|_2 \\
% &\qquad \qquad \quad  \leq \frac{1}{n+1}\sum^{n}_{l=0} \left( \epsilon_k + \frac{1}{2}\left\|c^i_{k, 0}-c^i_{k, n}\right\|_2\right)\\
&\leq \epsilon_k + \frac{1}{2}\left\|c^i_{k, 0}-c^i_{k, n}\right\|_2
\end{aligned}
\end{equation}
% by the triangle inequality, 
Thus, for any control point $c^i_{k,l}$,  
\begin{align}
\left\|c^i_{k,l}-\operatorname{cent}\left(B^i_k\right)\right\|_2 &\leq \left\|c^i_{k,l}-m_k^*\right\|_2 
+\left\|\operatorname{cent}\left(B^i_k\right)-m_k^*\right\|_2 \notag \\
&\leq 2\epsilon^i_k + \|c^i_{k,0}-c^i_{k,n}\|_2.
\end{align}
yielding $\operatorname{span}(B^i_k) \leq 2\epsilon^i_k + \|c^i_{k,0}-c^i_{k,n}\|_2$. since any point at the Bézier curve $B^i_k(t)$ is within the convex hull, $\|B^i_k(t) - \operatorname{cent}(B^i_k)\|_2 \leq \operatorname{span}(B^i_k)$.  
% Moreover, $\|c^i_{k,0}-c^i_{k,n}\|_2 \leq \|c^i_{k,0}-c^i_{k,n}\|_1 $. 

Consider any two Bézier curves $B^i_{k}$ and $B^j_{k}$ over $t \in [t_k, t_{k+1}]$, with convex hulls $\mathcal{CH}^i_k = \{c^i_{k,l}\}^{n}_{l=0}$ and $\mathcal{CH}^j_k =\{c^j_{k,l}\}^{n}_{l=0}$. The constraint \eqref{eq.agents_safe} implies that
% \begin{equation}
\begin{align}
&\|\operatorname{cent}(B^i_{k}) - \operatorname{cent}(B^j_{k})\|_1 \geq 
2\epsilon^i_{k} + \|c^i_{k,0}-c^i_{k,n}\|_1 + 2\epsilon^j_{k} \notag \\
&\qquad \qquad \qquad  \qquad  \qquad  \quad + \|c^j_{k,0}-c^j_{k,n}\|_1 +\epsilon_{inter}\sqrt{d} \notag \\
& \qquad \qquad  \geq \operatorname{span}(B^i_{k}) +  \operatorname{span}(B^j_{k}) + (\epsilon_{inter}\sqrt{d}). 
\end{align}
% \end{equation}


Then, by the triangle inequality, for any $t \in [t_k, t_{k+1}]$, 
% $$
% \begin{aligned}
% \|\operatorname{cent}(B^i_{k}) - \operatorname{cent}(B^j_{k})\|_1 &\leq \|\operatorname{cent}(B^i_{k}) -B^i_{k}(t) \|_1 \\
% & \quad + \|\operatorname{cent}(B^j_{k}) -B^j_{k}(t) \|_1 \\
% & \quad + \|B^i_{k}(t) - B^j_{k}(t)\|_1 \\
\begin{equation}
\begin{aligned}    
\|B^i_{k}(t) - B^j_{k}(t)\|_1 &\geq \|\operatorname{cent}(B^i_{k})  - \operatorname{cent}(B^j_{k})\|_1 \\
& \quad - \operatorname{span}(B^i_{k}) -  \operatorname{span}(B^j_{k}) \\
& \geq \epsilon_{inter}\sqrt{d}.
\end{aligned}
\end{equation}
By the norm inequality $\|x\|_1 \leq \sqrt{d}\|x\|_2$, it follows that, 
\begin{equation}
\|B^i_{k}(t) - B^j_{k}(t)\| \geq \epsilon_{inter}.
\end{equation}


\section{Rotation Matrix}
\label{apped:R_d}
\setcounter{equation}{0}
\renewcommand{\theequation}{II.\arabic{equation}}

This appendix will illustrate how to  determine the desired rotation matrix $R_d(t) = [b_{d, 1}(t), b_{d, 2}(t), b_{d, 3}(t)] \in \mathrm{SO}(3)$. For ease of notation, $(t)$ is omitted in the following illustration. Since $R_d \in \mathrm{SO}(3)$, $b_{d, 1}, b_{d, 2}, b_{d, 3}$ forms an orthonormal basis in $\mathbb{R}^3$. This means that $b_{d, 1}, b_{d, 2}$ and $b_{d, 3}$ satisfy the following properties:
\begin{align}
b_{d, 1}^{\top} b_{d, 1} &= b_{d, 2}^{\top} b_{d, 2} = b_{d, 3}^{\top} b_{d, 3}=1,  \\ 
b_{d, 1}^{\top} b_{d, 2} &=  b_{d, 1}^{\top} b_{d, 3} =  b_{d, 2}^{\top} b_{d, 3}=0.
\end{align}

To enhance clarity, $b_{i, j}$ is used to denote the $j$-th element of $b_{d, i}$. Firstly, given $F_d$ in \eqref{eq.Fd}, choose $b_{d, 3} = \frac{F_d}{\|F_d\|}$, specifically, 
\begin{align}
b_{d,3} = \begin{bmatrix}
b_{3,1} \\
b_{3,2} \\
b_{3,3} \\
\end{bmatrix} = \frac{1}{\|F_d\|}\begin{bmatrix}
F_{d,1} \\
F_{d,2} \\
F_{d,3} \\
\end{bmatrix}.
\end{align}

The vector $b_{d, 1}$ is then computed from a given $b_{d, 3}$. Specifically, $b_{1,3}=-\frac{F_{d, 1}}{\left\|F_d\right\|}$ is selected, yielding
\begin{equation}
\begin{aligned}
& b_{d, 1}^{\top} b_{d, 3} = 0 \\
 & \Rightarrow 
b_{1,1} \frac{F_{d, 1}}{\left\|F_d\right\|}+b_{1,2} \frac{F_{d, 2}}{\left\|F_d\right\|}-\frac{F_{d, 1}}{\left\|F_d\right\|} \cdot \frac{F_{d, 3}}{\left\|F_d\right\|}=0.
\end{aligned}
\end{equation}
Intuitively, choose
\begin{equation}
\begin{aligned}
b_{1,1} = \frac{F_{d, 3} + F_{d, 2}}{\|F_d\|},  
b_{1, 2} = - \frac{F_{d, 1}}{\|F_d\|}. 
\end{aligned}
\end{equation}
However, without renormalisation one would obtain  $b_{1,2} = b_{1,1}$ and $\left\|b_{d, 1}\right\| \neq 1$. Thus, a scalar  $l >0$ is introduced  to rescale $b_{1,1}$ and $b_{1,2}$ for enforcing $\left\|b_{d, 1}\right\|=1$, namely,
\begin{equation}
\begin{aligned}
&  b_{1,1} = \frac{F_{d, 3} + F_{d, 2}l}{\|F_d\|},  
b_{1, 2} = - \frac{F_{d, 1}l}{\|F_d\|}, \\ 
\text{ and } & b^2_{1,1} +b^2_{1,2}+  b^2_{1,3} = 1, \\
\Rightarrow \quad  &  b^2_{1,1} +b^2_{1,2}  = 1 - \frac{F^2_{d, 1}}{\left\|F_d\right\|^2}
 = \frac{F^2_{d, 2}+F^2_{d, 3}}{\left\|F_d\right\|^2}, \\ 
\Rightarrow \quad  &  (F_{d, 3} + F_{d, 2}l)^2+ (F_{d, 1}l)^2   = F^2_{d, 2}+F^2_{d, 3}, \\ 
\Rightarrow \quad  & (\|F_d\|^2 - F^2_{d, 3}) l^2 + 2F_{d,3}F_{d,2}l -F_{d, 2}^2= 0, \\
\Rightarrow \quad  & l = \frac{F_{d, 2}}{\|F_{d}\| + F_{d, 3}}. 
\end{aligned}
\end{equation}
Therefore, the following is obtained.
\begin{equation}
b_{d, 1} = \begin{bmatrix}
b_{1, 1} \\
b_{1, 2} \\
b_{1, 3} \\
\end{bmatrix} = \frac{1}{\|F_d\|} \begin{bmatrix}
F_{d,3} + \frac{F^2_{d, 2}}{\|F_{d}\| + F_{d, 3}} \\
-\frac{F_{d, 1}F_{d, 2}}{\|F_{d}\| + F_{d, 3}}\\
-F_{d, 1}\\
\end{bmatrix}.
\end{equation}

The orthogonality condition $b_{d, 1}^{\top} b_{d, 3}=0$ can be verified to hold. Subsequently, solving $b_{d, 2}=b_{d, 3} \times$ $b_{d, 1}$ yields
$$
b_{d, 2} = \begin{bmatrix}
b_{2, 1} \\
b_{2, 2} \\
b_{2, 3} \\
\end{bmatrix} = \frac{1}{\|F_d\|} \begin{bmatrix}
-\frac{F_{d, 1}F_{d, 2}}{\|F_{d}\| + F_{d, 3}}\\
F_{d,3} + \frac{F^2_{d, 1}}{\|F_{d}\| + F_{d, 3}} \\
-F_{d, 2}\\
\end{bmatrix}.
$$

\section{Proof of Lyapunov Bounds}
\label{apped:Lyapunov_Bounds}
\setcounter{equation}{0}
\renewcommand{\theequation}{III.\arabic{equation}}


For $t \in \mathbb{T}$, the derivatives of the error functions $e_p(t)$, $e_v(t)$, $\Psi_K(t)$, $e_{K,R}(t)$, and $e_\omega(t)$ in \eqref{eq.e_p}-\eqref{eq.Psi(t)} are obtained by (See \ref{apped:deriv_errors})
\begin{align}
\dot{e}_p(t) & =e_v(t), \label{eq.dot_ep}\\
\dot{e}_v(t) & =-\frac{1}{m}(K_p e_p(t)+K_v e_v(t) +\Delta_f(t)), \label{eq.dot_ev}\\
\dot{\Psi}_K(t) & =e^{\top}_{K,R}(t) e_\omega(t), \label{eq.dot_psi_K}\\
\dot{e}_{K,R}(t) & =\mathcal{C}(t) e_\omega(t), \label{eq.dot_e_KR}\\
\dot{e}_\omega(t) & =-J^{-1}\left(e_{K,R}(t)+K_\omega e_\omega(t)\right) \label{eq.dot_e_w}, 
\end{align}
where
\begin{align}
\hspace{-0.5cm}
&\mathcal{C}(t) :=\frac{1}{2}\left(\operatorname{tr}\left[K_{R}R_d(t)R(t) \right] \mathrm{I}_3-K_{R}R_d(t)R(t)\right), \\
&\Delta_f(t) :=\left\|F_d(t)\right\| \left(\left( b_{3,d}(t) - b^{\top}_{3, d}(t) b_3(t)\right)b_3(t)\right).
\end{align}
\begin{lemma}[{\cite[Proposition 2]{lee2012robust}}]
\label{lem:C(t)_bounds}
Let $t \in \mathbb{T}$, then $\|\mathcal{C}(t)\|_2 \leq \frac{1}{\sqrt{2}}\operatorname{tr}[K_R]$.
\end{lemma}

\begin{lemma}[See \ref{apped:prof_lem2}]
\label{lem:delta_f_Bound}
Given $t \in \mathbb{T}$, suppose $K_R=\operatorname{diag}\left(k_{R_1}, k_{R_2}, k_{R_3}\right)$ is a diagonal positive-definite matrix, $R(t), R_d(t) \in \mathrm{SO}(3)$, and $\Psi_K(t) < \psi$ for some constant $\psi \in\left(0, h_1\right)$. Define $b_3(t)$ and $b_{3, d}(t)$ as the third columns of $R(t)$ and $R_d(t)$, respectively. Then:
\begin{align}
&\|\left(b_{3, d}(t)-b_{3, d}^{\top}(t) b_3(t)\right) b_3(t)\|  \leq \sqrt{\frac{4 g_2}{h_1}}\left\|e_{K, R}\right\|.
\end{align}
This further implies that
\begin{equation}
\hspace{-0.5cm}
\begin{aligned}
\|\Delta_f(t)\| &\leq \bigl(\|[K_p ~K_v] M_1^{-\frac{1}{2}}\|  \sqrt{\mathcal{V}_1(t)} \bigr. \\ & \qquad \qquad \qquad  \bigl.+ m \|b_a\|\bigr)\sqrt{\frac{4 g_2}{h_1}}\left\|e_{K, R}\right\|.
 \end{aligned}
\end{equation}

\end{lemma}


Since $\|\mathcal{C}(t)\| \leq \frac{1}{\sqrt{2}} \operatorname{tr}[K_R]$ in Lemma \ref{lem:C(t)_bounds}, the time derivative of $\mathcal{V}_2(t)$ is bounded by
% \hspace{-0.2cm}
\begin{align}
\dot{\mathcal{V}}_2(t) &=e^{\top}_{K,R}(t)(c_2J^{-1})e_{K,R}(t)  - e^{\top}_{\omega}(t)c_2K_wJ^{-1}e_{K,R}(t) \notag \\
&\quad -e^{\top}_{\omega}(t)\left(K_w - c_2\mathcal{C}(t)\right)e_{\omega}(t) \notag \\
&\leq - e^{\top}_{K,R}(t)(c_2J^{-1})e_{K,R}(t) - e^{\top}_{\omega}(t)c_2K_wJ^{-1}e_{K,R}(t) \notag \\
&\quad -e^{\top}_{\omega}(t)\left(K_w - \frac{c_2}{\sqrt{2}} \operatorname{tr}[K_R] \mathrm{I}_3\right)e_{\omega}(t) \notag\\
&= z^{\top}_2(t)W_2z_2(t).
\end{align}


With the generalized Rayleigh inequality, there exists
\begin{equation}
\begin{aligned}
\dot{\mathcal{V}}_2(t) &\leq  -\|W_2^{\frac{1}{2}}z_2(t)\|^2 \\
&\leq -\underline{\lambda}\left(M_{2,2}^{-\frac{1}{2}} W_2 M_{2,2}^{-\frac{1}{2}}\right)\left\|M_{2,2}^{\frac{1}{2}} z_2\right\|^2 \\
&\leq -\underline{\lambda}\left(M_{2,2}^{-\frac{1}{2}} W_2 M_{2,2}^{-\frac{1}{2}}\right) \mathcal{V}_2(t).
\end{aligned}
\end{equation}
By Grönwall’s inequality, it follows that
\begin{equation}
\mathcal{V}_2(t) \leq e^{-\beta t}\mathcal{V}_2(0), 
\end{equation}
where $\beta = \underline{\lambda}\left(M_{2,2}^{-\frac{1}{2}} W_2 M_{2,2}^{-\frac{1}{2}}\right)$. This implies 
\begin{equation}
\sqrt{\mathcal{V}_2(t)} \leq e^{-\frac{\beta}{2} t}\sqrt{\mathcal{V}_2(0)}.
\end{equation}
Since $z_2^{\top}(t)M_{2,1} z_2(t) \leq \mathcal{V}_2(t) \leq  e^{-\beta t}\mathcal{V}_2(0)$, implying that 
\begin{equation}
\begin{aligned}
 \|e_{K,R}(t)\|  & \leq \left\|\left[\mathrm{I}_3, \mathrm{0}_{3}\right] M_{2,1}^{-\frac{1}{2}}\right\| \sqrt{V_2(t)}  \\
  &\leq \left\|\left[\mathrm{I}_3, \mathrm{0}_{3}\right] M_{2,1}^{-\frac{1}{2}}\right\| e^{-\frac{\beta}{2} t}\sqrt{V_2(0)}.
\end{aligned}
\end{equation}
Define 
\begin{align}
\alpha_0 &= \underline{\lambda}\left(M_1^{-\frac{1}{2}} W_1 M_1^{-\frac{1}{2}}\right),  \\ 
\alpha_1 &=\left\|\left[\frac{c_1}{m} \mathrm{I}_3, \mathrm{I}_3\right] M_1^{-\frac{1}{2}}\right\|\left\|\left[K_p, K_v \right] M_1^{-\frac{1}{2}}\right\| \beta^{\prime},   \\
\alpha_2 
&=m\left\|b_a\right\|\left\|\left[\frac{c_1}{m} \mathrm{I}_3, \mathrm{I}_3\right] M_1^{-\frac{1}{2}}\right\| \beta^{\prime}, \\
\beta^{\prime} &= \left\|\left[\mathrm{I}_3, \mathrm{0}_{3 \times 3} \right] M_{2,1}^{-\frac{1}{2}}\right\| \sqrt{\frac{4g_2}{h_1}}. 
\end{align}

With Lemma \ref{lem:delta_f_Bound}, \eqref{eq.dot_ep} and \eqref{eq.dot_ev}, the time derivative of $\mathcal{V}_1(t)$ is bounded by
% \begin{equation}
\begin{align}
% \hspace{-0.2cm}
\dot{\mathcal{V}}_1(t)
&=-\frac{c_1}{m} e_p^{\top}(t) K_p e_p(t) - \frac{c_1}{m} e_p^{\top}(t) K_v e_v(t) \notag \\
&\quad - e_v^{\top}(t) \left(K_v -c_1\mathrm{I}_3\right)e_v(t) - \Delta_f^{\top}\left(\frac{c_1}{m} e_p(t) +e_v(t) \right) \notag \\
&= -z_1^{\top}(t) W_1 z_1(t)-\Delta_f^{\top}(t)\left[\frac{c_1}{m} \mathrm{I}_3 \; \mathrm{I}_3\right] z_1(t) \notag \\
&\leq -\underline{\lambda}(M^{-\frac{1}{2}}_1W_1M^{-\frac{1}{2}}_1)\mathcal{V}_1(t) + \left\|\Delta_f(t)\right\|\left\|\left[\frac{c_1}{m} \mathrm{I}_3 \; \mathrm{I}_3\right] z_1(t)\right\| \notag \\
&\leq  - (\alpha_0 - \alpha_1\sqrt{\mathcal{V}_2(t)})\mathcal{V}_1(t) + \alpha_2\sqrt{\mathcal{V}_2(t) \mathcal{V}_1(t)} \notag \\
&\leq - (\alpha_0 - \alpha_1 e^{-\frac{\beta}{2} t}\sqrt{\mathcal{V}_2(0)})\mathcal{V}_1(t) 
  \\
 & \qquad + \alpha_2 e^{-\frac{\beta}{2} t}\sqrt{\mathcal{V}_2(0)} \sqrt{\mathcal{V}_1(t)}. \notag
\end{align}
% \end{equation}
Since $\sqrt{\mathcal{V}_2(t)} \leq \mathcal{L}_2(\mathcal{V}_2(0), t)$, using a nonlinear Grönwall-type inequality for \eqref{eq.dot_V1_bound} yields $\sqrt{\mathcal{V}_1(t)} \leq \mathcal{L}_1(\mathcal{V}_1(0), \mathcal{V}_2(0), t)$ where
\begin{equation}
\begin{aligned}
&\mathcal{L}_1(\mathcal{V}_1(0), \mathcal{V}_2(0), t) = 
e^{-\frac{\alpha_0 t}{2}}  \left[
e^{\frac{\alpha_1 \sqrt{\mathcal{V}_2(0)}}{\beta}} \sqrt{\mathcal{V}_1(0)} \right.  \\
& \qquad \qquad \qquad \quad \left. + \frac{\alpha_2 \sqrt{\mathcal{V}_2(0)}}{2} \int_0^t e^{\frac{1}{2}(\alpha_0 - \beta) s} ds
\right].
\end{aligned}
\end{equation}

\section{Proof of Initial Conditions}
\label{apped:Error_Bounds}
\setcounter{equation}{0}
\renewcommand{\theequation}{III.\arabic{equation}}

With $g_1 \|e_{K,R}(t)\|^2 \leq \Psi_K(t)$ in Proposition \ref{prop:Inequality_Psi_K}, if the initial condition $\frac{1}{2}e^{\top}_{\omega}(0)Je_{\omega}(0) \leq (1-\alpha_\psi)\psi$ and $\Psi(0) \leq \alpha_\psi \psi$ are satisfied, then, 
\begin{align*}
\mathcal{V}_2(0) & =\frac{1}{2} e_\omega^{\top}(0) J e_\omega(0)+ \Psi_K(0)+c_2 e^{\top}_R(0)e_\omega(0) \\
& \leq \left(1-\alpha_\psi\right) \psi+ \alpha_\psi \psi +c_2\left\|e_{K,R}(0)\right\|\left\|e_\omega(0)\right\| \\
& \leq \psi + c_2 \sqrt{\frac{\psi}{g_1}}
 \left\|J^{-1 / 2}\right\|\left\|J^{1 / 2} e_\omega(0)\right\| \\
 & \leq \psi + c_2 \sqrt{\frac{\psi}{g_1}} \|J^{-1/2}\| \sqrt{2(1-\alpha_{\psi})\psi}\\
 &= \left(1 + c_2 \sqrt{\frac{2(1-\alpha_\psi)}{\underline{\lambda}(J)g_1}}\right) \psi = \overline{\mathcal{V}}_2.
\end{align*}
Given $z_1(t) = [e_p(t), e_v(t)]^{\top}$, 
\begin{align*}
e_p(t) & = [\mathrm{I}_3, 0_{3\times 3}]z_1(t) = [\mathrm{I}_3, 0_{3\times 3}] M^{-\frac{1}{2}}_1 M_1^{\frac{1}{2}}z_1(t) \\   
\Rightarrow \|e_p(t)\| &\leq \|[\mathrm{I}_3, 0_{3\times3} ]M^{-\frac{1}{2}}_1\| \|M_1^{\frac{1}{2}}z_1(t)\|
\end{align*}
Since $\mathcal{V}_1(t)= (M_1^{\frac{1}{2}}z_1(t))^{\top}(M_1^{\frac{1}{2}}z_1(t)) = \|M_1^{\frac{1}{2}}z_1(t)\|^2 \Rightarrow \sqrt{V_1(t)} = \|M_1^{\frac{1}{2}}z_1(t)\|$. Since the function $\mathcal{L}(\mathcal{V}_1(0), \mathcal{V}_2(0), t)$ is non-decreasing with respect to $\mathcal{V}_1(0)$ and $\mathcal{V}_2(0)$, it follows that $\sqrt{\mathcal{V}(t)} \leq \mathcal{L}\left(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t\right)$. Therefore, 
\begin{align*}
\|e_p(t)\| &\leq \|[\mathrm{I}_3, 0_{3\times3} ]M^{-\frac{1}{2}}_1\| \sqrt{\mathcal{V}_1(t)} \\
& \leq \|[\mathrm{I}_3, 0_{3\times3} ]M^{-\frac{1}{2}}_1\|\mathcal{L}_1\left(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t\right) \\
&= \mathcal{L}_p\left(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t\right)
\end{align*}
Likewise, the other error bounds can be derived as
\begin{align*}
\|e_v(t)\| &=  \|[0_{3\times3}, \mathrm{I}_3 ]M^{-\frac{1}{2}}_1 M^{\frac{1}{2}}_1 z_1(t)\|\\
& \leq \|[0_{3\times3}, \mathrm{I}_3 ]M^{-\frac{1}{2}}_1\| \mathcal{L}_1\left(\overline{\mathcal{V}}_1, \overline{\mathcal{V}}_2, t\right)
\end{align*}


\section{Proof of Lemma 2}
\label{apped:prof_lem2}
\setcounter{equation}{0}
\renewcommand{\theequation}{V.\arabic{equation}}
\begin{proof}
Let $G(t) := R^{\top}_d(t)R(t) \in \operatorname{SO}(3)$, then it can be rewritten as
% \begin{equation}
\begin{align}
\|\left(b_{3, d}(t)-b_{3, d}^{\top}(t) b_3(t)\right) b_3(t)\|^2
&=1-\left(\left(b_{3, d}(t) \cdot b_3(t)\right)\right)^2 \notag \\
&=1-\left(G_{3,3}(t)\right)^2.
\end{align}
% \end{equation}
where $G_{3,3}(t)$ is the element in the third row and third column of the matrix $G(t)$. 

Let  $x=[x_1,x_2,x_3]^{\top}\in\mathbb{R}^3$ be the rotation vector such that $G(t) = \exp(\hat{x})$, where $\hat{x} \in \mathfrak{so}(3)$ is the skew-symmetric matrix associated with $x$ and the rotation angle is $\|x\| = \theta \in [0, \pi]$. Define the unit rotation axis $u = x/\|x\| = [u_1, u_2, u_3]^\top$. By Rodrigues' rotation formula,
\begin{equation}
G(t) = I + \sin \theta \, \hat{u} + (1 - \cos \theta) \, \hat{u}^2.
\end{equation}
Using the standard component form of Rodrigues’ formula, the $(3,3)$ element of $G(t)$ is given by
\begin{equation}
\begin{aligned}
G_{3,3}(t) &= \cos \theta + (1 - \cos \theta) u_3^2 \\
&= \cos \theta + (1 - \cos \theta) \frac{x_3^2}{\|x\|^2}.
\label{eq.G_33}
\end{aligned}
\end{equation}
Define  
\begin{equation}
T:=\frac{(x_1^2+x_2^2)(\cos\theta-1)}{\|x\|^{2}},
\end{equation}
then \eqref{eq.G_33} implies $G_{3,3}=1+T$, thus, 
\begin{equation}
\begin{aligned}
1-G_{3,3}^2
   =1-(1+T)^2
   =-2T-T^{2}\le -2T.
\label{eq.1-G_33}
\end{aligned}
\end{equation}
Because $(x_1^2+x_2^2)/\|x\|^{2}\!\le\!1$ and $1-\cos\theta\ge 0$,  
\begin{equation}
\begin{aligned}
1-G_{3,3}^2 &\leq -2T \\
   &=2\frac{(x_1^2+x_2^2)(1-\cos\theta)}{\|x\|^{2}} \\
   &\le 2(1-\cos\theta).
\label{eq.T}
\end{aligned}
\end{equation}
From~\cite{lee2012robust}, $\Psi_K$ can be expressed as
\begin{equation}
\Psi_K =\frac{1-\cos (\|x\|)}{2\|x\|^2} \sum_{(i, j, k) \in \mathcal{C}}\left(k_{R,i}+k_{R,j}\right) x_k^2.
\label{eq.Psi_K}
\end{equation}
where $\mathcal{C}=\{(1,2,3),(2,3,1),(3,1,2)\}$. 

Since $
h_1=\min \left\{k_{R_1}+k_{R_2}, k_{R_2}+k_{R_3}, k_{R_1}+k_{R_3}\right\}
$, 
\begin{equation}
\sum_{(i, j, k) \in \mathcal{C}}\left(k_{R,i}+k_{R,j}\right) x_k^2 \geq h_1\sum_{k=1}^3 x_k^2=h_1\|x\|^2.
\end{equation}
Putting it back into \eqref{eq.Psi_K}  leads to
\begin{equation}
\begin{aligned}
\Psi_K &\geq \frac{1-\cos (\|x\|)}{2\|x\|^2}\left(h_1\|x\|^2\right)\\
&=\frac{h_1}{2}(1-\cos (\|x\|)).
\end{aligned}
\end{equation}
This implies that 
$1-\cos (\|x\|) \leq \frac{2}{h_1} \Psi,
$
which yields
\begin{equation}
\hspace{-0.5cm}
\begin{aligned}
\|\left(b_{3, d}(t)-b_{3, d}^{\top}(t) b_3(t)\right) b_3(t)\|^2 &= 
1-G_{3,3}^2  \\
&\leq 2(1-\cos (\|x\|)) \\
&\leq \frac{4}{h_1} \Psi.
\end{aligned}
\end{equation}

Using the quadratic bounds $\Psi_{K}(t)\le g_{2}\|e_{K,R}\|^{2}(t)$, 
\begin{align}
\|\left(b_{3, d}(t)-b_{3, d}^{\top}(t) b_3(t)\right) b_3(t)\|  \leq \sqrt{\frac{4 g_2}{h_1}}\left\|e_{K, R}\right\|.
\end{align}


Combining with the definition of $F_d(t)$ in \eqref{eq.Fd} and Assumption \ref{Assump:acc_d}, using the triangular inequality gives 
\begin{equation}
\begin{aligned}
\|F_d(t)\| &\leq \| -K_p e_p(t)-K_v e_v(t)+m g e_3+m \ddot{y}_d(t)\| 
\\
&\leq  \|K_p e_p(t)+K_v e_v(t)\| + m\|b_a\|
\end{aligned}
\end{equation}
Furthermore, using the definitions of $\mathcal{V}_1(t)$ in \eqref{eq.V_1(t)} yields
\begin{equation}
\begin{aligned}
\left\|K_p  e_p(t)+K_v e_v(t)\right\| &= \|[K_p ~K_v]z_1(t)\| \\
& \leq \|[K_p ~K_v] M_1^{-\frac{1}{2}}\| \sqrt{\mathcal{V}_1(t)}
\end{aligned}
\end{equation}
Therefore, $\|\Delta_f(t)\|$ is bounded by:
$$
\begin{aligned}
\|\Delta_f(t)\| \leq &\|F_d(t)\|\|\left(b_{3, d}(t)-b_{3, d}^{\top}(t) b_3(t)\right) b_3(t)\| \\
\leq &\bigl(\|[K_p ~K_v] M_1^{-\frac{1}{2}}\|  \sqrt{\mathcal{V}_1(t)} \bigr. \\ & \qquad \qquad \qquad  \bigl.+ m \|b_a\|\bigr)\sqrt{\frac{4 g_2}{h_1}}\left\|e_{K, R}\right\|.
\end{aligned}
$$
Since $z_2^{\top}(t)M_{2,1} z_2(t) \leq \mathcal{V}_2(t)$, then,
\begin{equation}
\|e_{K,R}(t)\| \leq \left\|\left[\mathrm{I}_3, \mathrm{0}_{3 \times 3} \right] M_{2,1}^{-\frac{1}{2}}\right\| \sqrt{\mathcal{V}_2(t)}.
\end{equation}
\end{proof}




\section{Derivatives of the error functions}  
\label{apped:deriv_errors}
\setcounter{equation}{0}
\renewcommand{\theequation}{VI.\arabic{equation}}


This appendix shows how to calculate the derivative of these error functions. 


{\scalebox{0.8}{$\bullet$}} \textbf{The derivative of $e_p(t)$:}  

$\dot{e}_p(t) = \dot{y}_{tr}(t) - \dot{y}_d(t) =  e_v(t).$

{\scalebox{0.8}{$\bullet$}}\textbf{The derivative of $e_v(t)$:}  

From \eqref{eq.dv} and \eqref{eq.|ge_3+ay|<B1} in Assumption \ref{Assump:acc_d}, it follows that
\begin{align}
m\ddot{y}_{tr}(t) &= -mg e_3+ f(t) R(t) e_3, \\
m \ddot{y}_d(t) &= F_d(t)+K_p e_p(t)+K_v e_v(t)-m g e_3.
\end{align}
Therefore, 
\begin{align}
m\dot{e}_v(t) &= m\ddot{y}_{tr}(t) - m\ddot{y}_d(t) \notag \\
&= \left(-mg e_3+ f(t) R(t) e_3\right) \\
&\quad - \left(F_d(t)+K_p e_p(t)+K_v e_v(t)-m g e_3\right) \notag\\
&= -(K_p e_p(t)+K_v e_v(t)) - \left(F_d(t)-f(t) R(t) e_3\right). \notag
\end{align}

Since $f(t)=F_d^{\top}(t) R(t) e_3$ and $b_{3, d}(t)=\frac{F_d(t)}{\left\|F_d(t)\right\|}$, then,
\begin{equation}
\begin{aligned}
F_d^{\top}(t) R(t) e_3 &= F_d^{\top}(t)b_3(t) \\
&=\left\|F_d(t)\right\| \frac{F^{\top}_d(t)}{\left\|F_d(t)\right\|} b_3(t)\\
&=\left\|F_d(t)\right\|\left(b^{\top}_{3, d}(t) b_3(t)\right).  
\end{aligned}
\end{equation}
Thus, 
\begin{equation}
\hspace{-0.2cm}
\begin{aligned}
F_d(t)& - f(t) R(t) e_3 \\
&=\left\|F_d(t)\right\| \frac{F_d(t)}{\left\|F_d(t)\right\|}  -(F_d^{\top}(t) R(t) e_3)R(t)e_3 \\
&= \left\|F_d(t)\right\|b_3(t) - \left\|F_d(t)\right\|\left(b^{\top}_{3, d}(t) b_3(t)\right)b_3(t) \\
&= \left\|F_d(t)\right\| \left(\left( b_{3,d}(t) - b^{\top}_{3, d}(t) b_3(t)\right)b_3(t)\right)\\
&\triangleq \Delta_f(t).
\end{aligned}
\end{equation}
$$ \Rightarrow \dot{e}_v(t) = -\frac{1}{m}(K_p e_p(t)+K_v e_v(t) +\Delta_f(t)).$$


{\scalebox{0.8}{$\bullet$}} \textbf{The derivative of $\Psi_K(t)$:} 

Let $G(t) = R^{\top}_d(t) R(t) \in \mathrm{SO}(3)$, then 
\begin{equation}
\dot{\Psi}_K(t)= \frac{1}{2}\operatorname{tr}(-K_R\dot{G}(t)).
\end{equation}
Moreover, with $\hat{\omega}_d(t) \in \mathfrak{s o}(3)$, the following properties hold:
\begin{align}
\hat{\omega}^{\top}_d(t) &= -\hat{\omega}_d(t) \\
G(t)G^{\top}(t) &= 1 \\
G^{\top}(t) \hat{\omega}_d(t) G(t) &=\left(G^{\top}(t) \omega_d(t)\right)^{\wedge}.
\end{align}
Using these identities, the derivative of $G(t)$ can be computed as
\begin{equation}
\begin{aligned}
\dot{G}(t) & =\dot{R}_d^{\top}(t) R(t)+R_d^{\top}(t) \dot{R}(t) \\
& =\left(R_d(t) \hat{\omega}_d(t)\right)^{\top} R(t)+G(t) \hat{\omega}(t) \\
& =-\hat{\omega}_d(t) G(t)+G(t) \hat{\omega}(t) \\
& =G(t)\left(\hat{\omega}(t)-G^{\top}(t) \hat{\omega}_d(t)G(t)\right) \\
&=G(t)\left(\hat{\omega}(t)-\left(G^{\boldsymbol{\top}}(t) \omega_d(t)\right)^{\wedge}\right) \\
&=G(t)\left(\omega(t)-G^{\boldsymbol{\top}}(t) \omega_d(t)\right)^{\wedge} \\
&=G(t) \hat{e}_\omega(t).
\end{aligned}
\end{equation}
Using the trace identity $\operatorname{tr}[A \hat{x}]=-x^{\top}\left(A-A^{\top}\right)^{\vee}$ and the definition of $e_{K, R}(t)$ yields 
\begin{equation}
\begin{aligned}
\dot{\Psi}(t) &=- \frac{1}{2} \operatorname{tr}(K_RG(t) \hat{e}_\omega(t)) \\
&= \frac{1}{2} e^{\top}_{\omega}(t)\left(K_RG(t) - (K_RG(t))^{\top}\right)^{\vee}\\
&= e^{\top}_\omega(t)e_{K,R}(t).
\end{aligned}
\end{equation}

{\scalebox{0.8}{$\bullet$}} \textbf{The derivative of $e_{K,R}(t)$:} 
\begin{equation}
\begin{aligned}
\dot{e}_{K,R}(t) & =\frac{1}{2}\left(K_R\dot{G}(t)-\dot{G}^{\top}(t)K_R\right)^{\vee} \\
&=\frac{1}{2}\left(K_RG(t) \hat{e}_\omega(t)+\hat{e}_\omega(t) G^{\top}(t)K_R\right  )^{\vee}.
\end{aligned}
\end{equation}
Since $A \hat{x}+\hat{x}A^T=((\operatorname{tr}(A)\mathrm{I}-A)x)^{\wedge}$, let $A(t) = K_RG(t)$, since $K_R$ is a diagonal matrix, $A(t)^{\top} = G^{\top}(t)K_R$. Hence,
\begin{equation}
\begin{aligned}
\dot{e}_{K,R}(t) & =\frac{1}{2}\left(A(t)\hat{e}_\omega(t)+\hat{e}_\omega(t) A^{\top}(t)\right)^{\vee} \\
& =\frac{1}{2}\left(\operatorname{tr}(A(t))\mathrm{I}_3-A(t)\right) e_\omega(t)\\
&=\mathcal{C}(t) e_\omega(t).
\end{aligned}
\end{equation}
where $\mathcal{C}(t) := \frac{1}{2}\left(\operatorname{tr}(K_RR^{\top}_d(t) R(t))\mathrm{I}_3-K_RR^{\top}_d(t) R(t)\right)$.

{\scalebox{0.8}{$\bullet$}} \textbf{The derivative of $e_{\omega}(t)$}:

Rewrite $e_{\omega}(t)= \omega(t)-G^{\top}(t)\omega_d(t)$, then
\begin{equation}
\begin{aligned}
\dot{e}_\omega(t) & = \dot{\omega}(t) - \dot{G}^{\top}(t)\omega_d(t) - G^{\top}(t)\dot{\omega}_d(t) \\
& =\dot{\omega}(t)-\hat{e}_\omega^{\top}(t) G^{\boldsymbol{\top}}(t) \omega_d(t)-G^{\boldsymbol{\top}}(t) \dot{\omega}_d(t).
\end{aligned}
\end{equation}
Given the definition of $\dot{\omega}(t)$ and $\tau(t)$, it follows that
\begin{equation}
\begin{aligned}
\dot{e}_\omega(t)&=  J^{-1}(-\omega(t) \times J \omega(t)+\tau(t)) \\
& \quad +\hat{e}_\omega(t) G^{\boldsymbol{\top}}(t) \omega_d(t) -G^{\boldsymbol{\top}}(t) \dot{\omega}_d(t) \\
&=J^{-1}\left(-e_{K,R}(t)-k_\omega e_\omega(t)\right) \\
&\quad -\hat{\omega}(t) G^{\boldsymbol{\top}}(t) \omega_d(t)+\hat{e}_\omega(t) G^{\boldsymbol{\top}}(t) \omega_d(t)
\end{aligned}
\end{equation}

With the property of hat operator $R \hat{x} R^T=(R x)^{\wedge}$, it follows that 
\begin{equation}
\begin{aligned}
\hat{e}_\omega(t) &=\left(\omega(t)-G^{\mathbf{\top}}(t) \omega_d(t)\right)^{\wedge} \\
&=\hat{\omega}(t)-\left(G^{\mathbf{\top}}(t) \omega_d(t)\right)^{\wedge} \\
&=\hat{\omega}(t)-G^{\boldsymbol{\top}}(t) \hat{\omega}_d(t) G(t).
\end{aligned}
\end{equation}
Since $G(t)G^{\boldsymbol{\top}}(t) = 1$ and $\hat{\omega}_d(t)\omega_d(t)=0$, then, 
\begin{align}
\hat{e}_\omega(t) G^{\boldsymbol{\top}}(t) \omega_d(t)-\hat{\omega}(t) G^{\boldsymbol{\top}}(t) \omega_d(t)=0 \\
\Rightarrow 
\dot{e}_\omega(t)= -J^{-1}\left(e_{K,R}(t)+k_\omega e_\omega(t)\right). \notag
\end{align}
