    The most important part for our congruence is the following relation, which describes a connection between the $\rho$-$\lambda$-splits of two words.
    \begin{definition}\label{def:singleRankerPair}
      Let $u, v \in \Sigma^*$, $m \in \Np$, $\rho$ an $X$-ranker and $\lambda$ a $Y$-ranker. We let $u \sim_{m, \rho, \lambda} v$ if and only if
      \begin{enumerate}[noitemsep]
        \item $u$ and $v$ are $\rho$-$\lambda$-compatible and,
        \item for all prefixes $\rho'$ of $\rho\Xinfty$ and $\lambda'$ of $\lambda\Yinfty$ with $\rho'(u) \leq \lambda'(u)$ and $\rho'(v) \leq \lambda'(v)$, we have that, if $(u_0, u_1, u_2)$ is the $\rho'$-$\lambda'$-split of $u$ and $(v_0, v_1, v_2)$ is the $\rho'$-$\lambda'$-split of $v$, then $\alphabet u_1 = \alphabet v_1$ and
        \[
          \forall a \not\in \alphabet u_1 = \alphabet v_1: |u_0|_a \equiv |v_0|_a \bmod m \text{ and } |u_2|_a \equiv |v_2|_a \bmod m
        \]
        hold.
      \end{enumerate}
    \end{definition}
