    \begin{remark*}
      Despite \autoref{fct:simRhoLambdaIsEquivalence}, $\sim_{m, \rho, \lambda}$ is not a congruence in general. For example, consider the words $u = bc$ and $v = cb$ and the rankers $\rho = X_a X_b$ and $\lambda = \varepsilon$. The words are $\{ \rho, \lambda \}$-compatible and, for any prefix $\rho'$ of $\rho\Xinfty$ and $\lambda'$ of $\lambda\Yinfty$, the $\rho'$-$\lambda'$-split can only be $(u, \varepsilon, \varepsilon)$ for $u$ and $(v, \varepsilon, \varepsilon)$ for $v$, $(\varepsilon, u, \varepsilon)$ for $u$ and $(\varepsilon, v, \varepsilon)$ for $v$ or $(\varepsilon, \varepsilon, u)$ for $u$ and $(\varepsilon, \varepsilon, v)$ for $v$. Thus, we have $u \sim_{m, \rho, \lambda} v$. Clearly, we also have $a \sim_{m, \rho, \lambda} a$ but we do not have $au \sim_{m, \rho, \lambda} av$ as $\rho' = \rho = X_a X_b$ and $\lambda' = \lambda = \varepsilon$ split $u$ into $(a, c, \varepsilon)$ and $v$ into $(ac, \varepsilon, \varepsilon)$, so the alphabets of the middle parts ($c$ and $\varepsilon$) do not coincide.
    \end{remark*}

    However, we obtain a congruence -- and this is the congruence we will use to describe $\DAb$ -- by taking a finite intersection of some relations $\sim_{m, \rho, \lambda}$.
    \begin{definition}\label{def:congruence}
      Let $u, v \in \Sigma^*$ and $m \in \Np$, $n \in \mathbb{N}$. We let $u \approx_{m, n} v$ if $u \sim_{m, \rho, \lambda} v$ holds for all pairs of an $X$-ranker $\rho$ and a $Y$-ranker $\lambda$ with $|\rho| + |\lambda| \leq n$.
    \end{definition}

    \begin{fact}
      For all $m \in \Np$, $n \in \mathbb{N}$, the relation $\approx_{m, n}$ is a congruence of finite index.
    \end{fact}
    \begin{proof}
      By definition, $\approx_{m, n}$ is the intersection of all $\sim_{m, \rho, \lambda}$ for the pairs of an $X$-ranker $\rho$ and a $Y$-ranker $\lambda$ with $|\rho| + |\lambda| \leq n$. Since these finitely many $\sim_{m, \rho, \lambda}$ are equivalences of finite index (by \autoref{fct:simRhoLambdaIsEquivalence}), this also holds for $\approx_{m, n}$.

      Thus, the only interesting part of the proof is to show that $\approx_{m, n}$ is compatible. For this, let $u_\ell, v_\ell, u_r, v_r \in \Sigma^*$ with $u_\ell \approx_{m, n} v_\ell$ and $u_r \approx_{m, n} v_r$ and consider an $X$-ranker $\rho$ and a $Y$-ranker $\lambda$ with $|\rho| + |\lambda| \leq n$. Furthermore, let $\rho'$ be a prefix of $\rho\Xinfty$ and $\lambda'$ a prefix of $\lambda\Yinfty$. We have to show $\operatorname{ord}[\rho', \lambda'; u_\ell u_r] = \operatorname{ord}[\rho', \lambda'; v_\ell v_r]$
      and, if $\rho'(u_\ell u_r) \leq \lambda'(u_\ell u_r)$ (and, thus, also $\rho'(v_\ell v_r) \leq \lambda'(v_\ell, v_r)$), that, for the $\rho'$-$\lambda'$-split $(u_0, u_1, u_2)$ of $u_\ell u_r$ and the $\rho'$-$\lambda'$-split $(v_0, v_1, v_2)$ of $v_\ell v_r$, we have $\alphabet u_1 = \alphabet v_1$ and
      \[
        \forall a \not\in \alphabet u_1 = \alphabet v_1: |u_0|_a \equiv |v_0|_a \bmod m \text{ and } |u_2|_a \equiv |v_2|_a \bmod m \text{.}
      \]

      Let $\rho' = \rho'_0 \rho'_1$ where $\rho'_0$ is the longest prefix of $\rho'$ such that $\rho'_0(u_\ell) < +\infty$ (possibly empty). We first show
      \[
        \rho'(u_\ell u_r) = \begin{cases}
          \rho'(u_\ell) & \text{if } \rho'(u_\ell) < +\infty \\
          |u_\ell| + \rho'_1(u_r) & \text{otherwise}
        \end{cases}
      \]
      where we let $|u_\ell| + \infty = +\infty$. Note that $\rho'_1(u_r) = -\infty$ implies that $\rho'_1$ must be empty and that $\rho'_1$ being empty implies $\rho'(u_\ell) = \rho'_1(u_\ell) < +\infty$ (i.\,e.\ we are in the second case).

      The first case obviously holds and, in the second case, $\rho'_1$ cannot be empty. Thus, we may write $\rho' = \rho'_0 \Xinfty \rho''_1$ or $\rho' = \rho'_0 X_a \rho''_1$ for some $a \in \Sigma$ where $\rho''_1$ is some suffix of $\rho'$. In the former case, we $\rho'(u_\ell u_r) = +\infty = \Xinfty \rho''_1(u_r) = \rho'_1(u_r)$ and, in the latter case, we obtain the following situation:
      \begin{center}
        \begin{tikzpicture}[baseline=(ul.base)]
          \node[text height=0.8em, text depth=0.2em, inner sep=2pt, minimum width=3cm] (ul) {$u_\ell$};
          \node[text height=0.8em, text depth=0.2em, inner sep=2pt, minimum width=6cm, right=0pt of ul] (ur) {$u_r$};

          \draw (ul.north west) rectangle (ur.south east);
          \draw (ul.north east) -- (ul.south east);

          \node[below right=2pt and 0pt of ul.south west, inner sep=0pt] (1) {$\scriptstyle 1$};
          \node[below left=2pt and 2pt of ul.south east, inner sep=0pt] (ulpos) {$\scriptstyle |u_\ell|$};
          \node[below right=2pt and 2pt of ur.south west, inner sep=0pt] (ul+1pos) {$\scriptstyle |u_\ell| + 1$};
          \node[below left=2pt and 2pt of ur.south east, inner sep=0pt] (ul+urpos) {$\scriptstyle |u_\ell| + |u_r|$};

          \draw[->] ($(ul.north west) + (-0.75cm, 1cm)$) .. controls +(1cm, 0cm) and +(0cm,1cm) .. node[below, pos=0] {$\rho'_0$} ($(ul.north east)+(-1cm,2pt)$);
          \draw[->, shorten <= 1ex] ($(ul.north east)+(-1cm,2pt)$) .. controls +(0.25cm, 0.75cm) and +(0cm,1cm) .. node[midway, above] {$X_a$} ($(ur.north west)+(1.5cm,2pt)$);
          \draw[->, shorten <= 1ex] ($(ur.north west)+(1.5cm,2pt)$) .. controls +(0.25cm, 0.75cm) and +(0cm,1cm) .. node[midway, above] {$\rho''_1$} ($(ur.north east)+(-2cm,2pt)$);

          \draw[decorate, decoration={brace}] ($(ulpos.south -| ur.south west)+(1.5cm,-2pt)$) -- node[below] {no $a$} ($(ulpos.south -| ul.south east)+(-1cm,-2pt)$);
        \end{tikzpicture},
      \end{center}
      which shows that we have $\rho'(u_\ell u_r) = |u_\ell| + X_a\rho''_1(u_r) = |u_\ell| + \rho'_1(u_r)$.

      We also get an analogous statement for $v_\ell v_r$ and, by left-right symmetry, a statement for $\lambda$: Let $\lambda' = \lambda'_0 \lambda'_1$ where $\lambda'_0$ is the longest prefix of $\lambda'$ such that $-\infty < \lambda'_0(u_r)$. Then, we have
      \[
        \lambda'(u_\ell u_r) = \begin{cases}
          |u_\ell| + \lambda'(u_r) & \text{if } -\infty < \lambda'(u_r) \\
          \lambda'_1(u_\ell) & \text{otherwise}
        \end{cases}
      \]
      (where we again let $|u_\ell| + \infty = +\infty$) and an analogous statement for $v$.

      One consequence of these statements is that we have
      \[
        \rho'(u_\ell u_r) \leq |u_\ell| \iff \rho'(u_\ell) < +\infty
        \iff \rho'(v_\ell) < +\infty \iff \rho'(v_\ell v_r) \leq |v_\ell|
      \]
      where we have used that $u_\ell$ and $v_\ell$ are $\rho$-$\lambda$-compatible for the second equivalence (using $\rho'$ and the empty $Y$-ranker as the prefixes). The negation of this statement also yields $|u_\ell| < \rho'(u_\ell u_r) \iff |v_\ell| < \rho'(v_\ell v_r)$.

      In the same way, we obtain
      \[
        |u_\ell| < \lambda'(u_\ell u_r) \iff -\infty < \lambda'(u_r) \iff -\infty < \lambda'(v_r) \iff |v_\ell| < \lambda'(v_\ell v_r)
      \]
      and, by negation, $\lambda'(u_\ell u_r) \leq |u_\ell| \iff \lambda'(v_\ell v_r) \leq |v_\ell|$.

