Suppose that $(I,I\cup \{v\})$ is on the path from $K$ to $L$. Along the path, all vertices from $K\cap A_v$ have been removed, all vertices from $K\cap L_v$ have been changed to the vertices of $L\cap L_v$, and the vertices of $K \cap R_v$ have not been modified. Thus, $I\cap L_v = L\cap L_v$, $I\cap R_v = K\cap R_v$. Thus, 
$$
\sum_{\substack{K,L\in \mathcal{I}(G) \\ (I,I\cup\{v\})\in \gamma_{K,L}}} \pi(K)\pi(L) \leqslant \left(\sum_{\substack{K\in \mathcal{I}(G) \\ K\cap R_v = I\cap R_v}} \pi(K) \right) 
    \left(\sum_{\substack{L\in \mathcal{I}(G) \\ L\cap L_v = I\cap L_v}} \pi(L) \right)
$$

We bound the first of two sum on the above equation. By applying Lemma~\ref{lemma:Technical}.(\ref{lemma:Technical1}) on $G$, subset $R_v\subseteq V(G)$ and independent set $I\cap R_v$, we have 
$$
\sum_{\substack{K\in \mathcal{I}(G) \\ K\cap R_v = I\cap R_v}} \pi(K) \leqslant \frac{\lambda^{|I\cap R_v|}}{Z_{G}(\lambda)} Z_{V(G) \setminus R_v}
$$
Then, by Lemma~\ref{lemma:Technical}.(\ref{lemma:Technical2}) on graph $G[V(G)\setminus R_v]$ and partition $(L_v,A_v)$ of $V(G)\setminus R_v$, we get 
$$
\sum_{\substack{K\in \mathcal{I}(G) \\ K\cap R_v = I\cap R_v}} \pi(K) \leqslant \frac{\lambda^{|I\cap R_v|}}{Z_G(\lambda)} Z_{L_v}(\lambda) Z_{A_v}(\lambda)
$$
Similarly, we bound the second sum as follows :
$$
\sum_{\substack{L\in \mathcal{I}(G) \\ L\cap L_v = I\cap L_v}} \pi(L) \leqslant \frac{\lambda^{|I\cap L_v|}}{Z_G(\lambda)} Z_{R_v}(\lambda) Z_{A_v}(\lambda)
$$
Combining the inequalities above, we obtain that 
\begin{align*}
    \rho(\Gamma_{\mathcal{T},G}, (I, I\cup \{v\})) %\\[1em]
    &\leqslant 2n^2\frac{\lambda+1}{\lambda}\frac{Z_G(\lambda)}{\lambda^{|I|}} \sum_{\substack{K,L\in \mathcal{I}(G) \\ (I,I\cup\{v\})\in \gamma_{K,L}}} \pi(K)\pi(L) \\
    &\leqslant 2n^2\frac{\lambda+1}{\lambda}  \frac{Z_G(\lambda)}{\lambda^{|I|}} \left(\sum_{\substack{K\in \mathcal{I}(G) \\ K\cap R_v = I\cap R_v}} \pi(K) \right) 
    \left(\sum_{\substack{L\in \mathcal{I}(G) \\ L\cap L_v = I\cap L_v}} \pi(L) \right)\\[1em]
    &\leqslant 2n^2\frac{\lambda+1}{\lambda}\frac{Z_G(\lambda)}{\lambda^{|I|}} \frac{\lambda^{|I\cap L_v|} \lambda^{|I\cap R_v|}}{Z_G(\lambda)^2}
    Z_{L_v}(\lambda) Z_{R_v}(\lambda)Z_{A_v}(\lambda)^2 \\[1em]
    &= 2n^2\frac{\lambda+1}{\lambda} \frac{1}{\lambda^{|I\cap A_v|}}\frac{Z_{L_v}(\lambda) Z_{R_v}(\lambda)}{Z_G(\lambda)} Z_{A_v}(\lambda)^2 
\end{align*}
where the last inequality holds since $\frac{\lambda^{|I\cap L_v|} \lambda^{|I\cap R_v|}}{\lambda^{|I|}} = \frac{1}{\lambda^{|I\cap A_v|}}$.

Notice that $R_v$ and $L_v$ are disconnected in $G$, thus if $K\in \mathcal{I}(G[L_v])$ and $L\in \mathcal{I}(G[R_v])$, then $K\cup L$ is an independent set of $G$. It follows that
$$
\left(\sum_{K \in \mathcal{I}(G[L_v])}  \lambda^{|K|}  \right) 
    \left(\sum_{L \in \mathcal{I}(G[R_v])} \lambda^{|L|} \right) \leqslant \sum_{I\in \mathcal{I}(G)}\lambda^{|I|} = Z_G(\lambda)
$$
and finally, 
$$
\rho(\Gamma, (I, I\cup \{v\}))  \leqslant 2n^2\frac{\lambda+1}{\lambda} \frac{1}{\lambda^{|I\cap A_v|}} Z_{A_v}(\lambda)^2 
$$
\end{proof}

\begin{lemma}\label{lemma:Congestion2}
Let $G$ be a graph, $\mathcal{T}$ a separator tree of $G$, $I$ an independent set of $G$, and $v\in I$. Then, for any $\lambda>0$,
$$
\rho(\Gamma_{\mathcal{T},G}, (I,I\setminus\{v\}) \leqslant
 2n^2\frac{\lambda+1}{\lambda^{|I\cap A_v|}}Z_{A_v}(\lambda)^2
$$
\end{lemma}

\begin{proof}
Similarly to the proof of Lemma~\ref{lemma:Congestion1}, by Equation~\ref{Congestion} we obtain 
\begin{align*}
    \rho(\Gamma_{\mathcal{T},G}, (I, I\setminus\{v\}) &= \frac{1}{\pi(I) P(I,I\setminus\{v\})} \sum_{\substack{K,L\in \mathcal{I}(G) \\ (I,I')\in \gamma_{K, L}}} \pi(K)\pi(L) |\gamma_{K, L}| \\
    &\leqslant 2n\frac{Z_G(\lambda)}{\lambda^{|I|}}n(\lambda+1) \sum_{\substack{K,L\in \mathcal{I}(G) \\ (I,I')\in \gamma_{K, L}}} \pi(K)\pi(L) \\
\end{align*}

Consider the following order on the nodes of $T$ : for $t,t'\in V(T)$, we state $t \prec t'$ if and only if $t$ is strictly before $t'$ in the pre-order of $T$. Then, we define two sets :
$$
\begin{array}{ll}
     R_v &= \bigcup_{t \in V(T) \mid t_v\prec t} X_{t} \\
     %A_v &=\bigcup_{t\in V(T) \mid \text{$t$ ancestor of $t_v$ in $T$}} X_t \\
     L_v &= V(G) \setminus (A_v\cup R_v)
\end{array}
$$
Note that $(L_v,A_v,R_v)$ is a separation of $V(G)$. An illustration of the three sets is given in Figure~\ref{fig:2ndCase}.

