Suppose that $(I,I\setminus \{v\})$ is on the path from $K$ to $L$. Along the path, all vertices from $K\cap A_v$ have been removed, all vertices from $K\cap L_v$ have been changed to the vertices of $L\cap L_v$, and the vertices of $K \cap R_v$ have not been modified. Thus, $I\cap L_v = L\cap L_v$ and $I\cap R_v = K\cap R_v$. 

Following the same exact step of computation as in Lemma~\ref{lemma:Congestion1}, we obtain that :
$$
\sum_{\substack{K,L\in \mathcal{I}(G) \\ (I,I')\in \gamma_{K, L}}} \pi(K)\pi(L) \leqslant
\frac{\lambda^{|I\cap L_v|}\lambda^{|I\cap R_v|}}{Z_G(\lambda)}\underbrace{\frac{Z_{L_v}(\lambda)Z_{R_v}(\lambda)}{Z_G(\lambda)}}_{\leqslant 1}Z_{A_v}(\lambda)^2
$$
and finally, 
$$
\rho(\Gamma_{\mathcal{T},G}, (I, I\setminus\{v\}) \leqslant 2n^2 \frac{\lambda+1}{\lambda^{|I\cap A_v|}} Z_{A_v}(\lambda)^2
$$
\end{proof}


\begin{lemma}\label{lemma:Congestion3}
Let $G$ be a graph, $\mathcal{T}=(T,\{X_t\}_{t\in V(T)})$ be a separator tree of $G$. Then, for any $\lambda>0$, 
$$
\rho(\Gamma_{\mathcal{T},G}) \leqslant 4n^2\tilde{\lambda}^{2\alpha+1}\max_{v\in V(G)}|\mathcal{I}(G[A_v])|^2
$$
where  $\tilde{\lambda} = e^{|\ln \lambda|}$ and $\alpha = \max_{v\in V(G)} \alpha(G[A_v])$.
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lemma:Congestion3}]
Let $(I,I')$ be a transition of the Markov chain. By definition of $\Gamma := \Gamma_{\mathcal{T},G}$, no canonical path uses the transition $(I,I)$, since at each step, either a vertex is added to or removed from the current independent set. It follows that $\rho(\Gamma, (I,I))=0$. Thus, we only need to consider the cases where either $I' = I \cup \{v\}$ for some $v \in V(G) \setminus N[I]$ or $I' = I \setminus \{v\}$ for some $v \in I$. A direct application of Lemma~\ref{lemma:Congestion1} and Lemma~\ref{lemma:Congestion2} gives  
$$
\rho(\Gamma,(I,I')) \leqslant 2n^2 \max\left(\lambda+1,\frac{\lambda+1}{\lambda}\right) \frac{1}{\lambda^{|I\cap A_v|}}Z_{A_v}(\lambda)^2
$$
First, suppose that $\lambda \geqslant 1$. In this case, the equality $\tilde{\lambda} = \lambda$ holds, and by Lemma~\ref{lemma:Technical}.(\ref{lemma:Technical0}),  
$$
Z_{A_v}(\lambda) \leqslant \tilde{\lambda}^{\alpha(G[A_v])} |\mathcal{I}(G[A_v])|
$$
Since $\frac{1}{\lambda^{|I\cap A_v|}} \leqslant 1$ and $\lambda+1 \leqslant 2\lambda$, we obtain:  
$$
\rho(\Gamma,(I,I')) \leqslant 4n^2 \tilde{\lambda}^{2\alpha(G[A_v])+1} |\mathcal{I}(G[A_v])|^2
$$
Next, suppose that $\lambda \in (0,1)$. In this case, the equality $\tilde{\lambda} = \lambda^{-1}$ holds. Since $\lambda^{\alpha(G[A_v])} \leqslant 1$, Lemma~\ref{lemma:Technical}.(\ref{lemma:Technical0}) implies $Z_{A_v}(\lambda) \leqslant |\mathcal{I}(G[A_v])|$. Furthermore, we have $\max\left(\lambda+1, \frac{\lambda+1}{\lambda} \right) \leqslant 2\tilde{\lambda}$, and $\frac{1}{\lambda^{|I\cap A_v|}} \leqslant \tilde{\lambda}^{\alpha(G[A_v])}$. It follows that  
$$
\rho(\Gamma,(I,I')) \leqslant 4n^2 \tilde{\lambda}^{\alpha(G[A_v])+1} |\mathcal{I}(G[A_v])|^2
$$
The conclusion is straightforward.

\end{proof}



\subparagraph*{Main result.} Lemma~\ref{lemma:Congestion3} gives an upper bound on the congestion of $\Gamma_{\mathcal{T}, G}$ depending on $\max_{v\in V(G)} \alpha(G[A_v])$ and $\max_{v\in V(G)} |\mathcal{I}(G[A_v])|$. However, this result does not rely on any specific properties beyond $\mathcal{T}$ being a separator tree. Theorem~\ref{thm:SubexpMixingTime} leverages the fact that $\mathcal{T}$ is a clique-based separator tree of $G$ to derive a subexponential bound on the congestion, and consequently, on the mixing time.

\begin{theorem}\label{thm:SubexpMixingTime}
Let $\mathcal{C}$ be a hereditary class of graphs, such that any $n$-vertex graph $G\in \mathcal{C}$ has a $(a,cn^{1-b}\ln^d(n))$-clique based separator for some constants $a$, $b$, $c$ and $d$ depending on~$\mathcal{C}$. Let $G\in \mathcal{C}$ be a $n$-vertex graph. The mixing time of the Glauber dynamic on $G$ with fugacity $\lambda> 0$ satisfies :
$$
\tau_{G,\lambda} = (2\tilde{\lambda})^{O(n^{1-b}\ln^d(n))}
$$
where $\tilde{\lambda}=e^{|\ln \lambda|}$.
\end{theorem}

\begin{proof} Let $g : \mathbb{R} \rightarrow \mathbb{R}$ be the function defined by $g(x) = cx^{1-b}\ln^d(x)$, and let $\mathcal{T} = (T, \{X_t\}_{t\in V(T)})$ be a $(a,g)$-clique based separator tree of $G$.

We show that the congestion is bounded on the set of canonical paths $\Gamma :=\Gamma_{\mathcal{T},G}$. By Lemma~\ref{lemma:Congestion3}, we have 
$$
\rho(\Gamma) \leqslant 4n^2 \tilde{\lambda}^{1+2\max_{v\in V(G)} \alpha(G[A_v])} \max_{v\in V(G)}|\mathcal{I}(G[A_v])|^2
$$
Consider $v\in V(G)$, and we bound both $\alpha(G[A_v])$ and $|\mathcal{I}(G[A_v])|$.
We describe how to construct an independent set of $G[A_v]$. Let $t_0...t_{k-1}$ be the ancestors of $t_v$ in $T$, where $t_0$ is the root and $t_{k-1}=t_v$, and notice that $X_{t_0},...,X_{t_{k-1}}$ forms a partition of $A_v$. Since any independent set $J \in \mathcal{I}(G[A_v])$ is the union of $k$ disjoint independent sets of $G[X_{t_0}],...,G[X_{t_{k-1}}]$ respectively, we have both inequalities
$$
\begin{array}{rl}
\alpha(G[A_v]) &\leqslant \sum_{i=0}^{k-1} \alpha(G[X_{t_i}]) \\[1em]
|\mathcal{I}(G[A_v])| &\leqslant \prod_{i=0}^{k-1} |\mathcal{I}(G[X_{t_i}])|
\end{array}
$$
Using Observation~\ref{Obs:CliqueBased}, there at most $2^{g(n)}$ independent sets in $G[X_{t_0}]$, and each of them has size at most $g(n)$.  Similarly, since $X_{t_1}$ is a clique based separator in a graph with less than $an$ vertices, $G[X_{t_1}]$ contains at most $2^{g(an)}$ independent sets of size at most $g(an)$. Repeating the same reasoning, we obtain that 
$$
\alpha(G[A_v]) \leqslant \sum_{i=0}^{k-1} g(a^in)
$$
and also
$$
|\mathcal{I}(G[A_v])|  \leqslant \prod_{i=0}^{k-1} 2^{g(a^in)}
= 2^{\sum_{i=0}^{k-1} g(a^in)}
$$
The sum can be bounded above :
\begin{align*}
    \sum_{i=0}^{k-1} g(a^in) &= \sum_{i=0}^{k-1} c(a^in)^{1-b}\ln^d(a^in) \\
    &= cn^{1-b}\sum_{i=0}^{k-1} (a^{1-b})^i\ln^d(a^in) \\
    &\leqslant cn^{1-b}\ln^d(n) \sum_{i=0}^{k-1} (a^{1-b})^i\\
    &\leqslant \frac{c}{1-a^{1-b}}n^{1-b}\ln^d(n) 
\end{align*}
where the last inequality holds since $a^{1-b} <1$ and $\sum_{i=0}^{+\infty}(a^{1-b})^i = \frac{1}{1-a^{1-b}}$. Altogether, the congestion verifies: 
$$
\rho(\Gamma) \leqslant 4n^2 (2\tilde{\lambda})^{2\frac{c}{1-a^{1-b}} n^{1-b}\ln^d(n)+1} \\
$$
Finally, using Theorem~\ref{thm:BoundCanonicalPaths} and $\min_{I\in \mathcal{I}(G)} \pi_{G,\lambda}(I) \geqslant (2\tilde{\lambda})^{-n}$,
\begin{align*}
    \tau_{G,\lambda} &\leqslant 4n^2(2\tilde{\lambda})^{2\frac{c}{1-a^{1-b}} n^{1-b}\ln^d(n)+1}\ln\left( 4(2\tilde{\lambda})^n\right) \\[1em]
    &\leqslant (2\tilde{\lambda})^{\gamma_{a,b,c}n^{1-b}\ln^d(n)}
\end{align*}
where $\gamma_{a,b,c}$ is a large enough constant depending only on $a$, $b$ and $c$. 
\end{proof}


We now discuss implications of Theorem~\ref{thm:SubexpMixingTime} together with previous works on clique-based separators from \cite{de2018framework,de2023clique}. A geometric object in $\mathbb{R}^d$ is said to be \emph{convex} if, for any two points inside the object, the entire line segment connecting them also lies within the object. A set of geometric objects is \emph{fat} if there exists a constant $c>0$ such that each object $O$ contains a ball of radius $r$ and is contained in a ball of radius at most $c \cdot r$. In particular, similarly-sized fat objects are those where the ratio between the largest and smallest enclosing balls is bounded. A \emph{map graph} is a graph obtained as follows: consider a planar graph $H$ with vertices representing regions in a planar map. The map graph is then constructed by connecting two vertices if their corresponding regions share a boundary. These graphs generalize planar graphs and may have unbounded clique sizes. A family of regions in the plane forms a collection of \emph{pseudo-disks} if the boundaries of any two regions intersect at most twice. That is, for any two regions, their intersection consists of at most two connected components. Pseudo-disk intersection graphs generalize disk graphs.

\begin{corollary}
Let $G$ be a graph with $n$ vertices. The mixing time of the Glauber dynamics on $G$ with fugacity $\lambda > 0$ satisfies:
\begin{itemize}
    \item If $G$ is the intersection graph of $d$-dimensional convex fat objects, or similarly-sized fat objects, then 
        $
        \tau_{G,\lambda} = (2\tilde{\lambda})^{O(n^{1-1/d})}.
        $
    \item If $G$ is the intersection graph of pseudo-disks, then
        $
        \tau_I{G,\lambda} = (2\tilde{\lambda})^{O(n^{\frac{2}{3}\ln(n)})}.
        $
    \item If $G$ is a map graph, then
        $
        \tau_{G,\lambda} = (2\tilde{\lambda})^{O(\sqrt{n})}.
        $
\end{itemize}
where $\tilde{\lambda} = e^{|\ln \lambda|}$.
\end{corollary}

The proof of Theorem~\ref{thm:BallGraphs} follows directly, as ball graphs in $\mathbb{R}^d$ are intersection graphs of convex objects. 

\section{Parameterized mixing time}\label{sec:Parameterized}

This section is dedicated to the proof of Theorems~\ref{thm:Path} and \ref{thm:TreeIndependenceNumber}. All the upper bounds on the mixing time follow the same outline as in the previous section: we construct a set of canonical paths, which in this case depend on path decompositions rather than separator trees. We then show that the congestion of these paths is bounded by the desired function of the parameter. Finally, we extend these results to the tree independence number by establishing structural connections between path and tree decompositions.

\subparagraph*{Path independence number and pathwidth.}
Let $\mathcal{P}=\{X_t\}_{1\leqslant t \leqslant p}$ be a path decomposition of a graph $G$, where $p$ is the number of bags in the path decomposition. Up to adding a bag, we suppose that $X_p$ is empty. Given two independent sets $I,J\in \mathcal{I}(G)$, we define the canonical path from $I$ to $J$ as follows. The step $1$ consists in, starting from $I$,  removing all the vertices of $I\cap X_1$ in arbitrary order. Then, for any $2\leqslant i \leqslant p$ successively, step $i$ consists in removing the vertices from $I\cap X_{i}$ in arbitrary order, and adding all the vertices from $J\cap X_{i-1}\setminus X_i$ in arbitrary order as well.  We call $\gamma_{I,J}$ the set of transitions obtained. It is straightforward to prove that $\gamma_{I,J}$ is indeed a path from $I$ to $J$, since each vertex $v\in I$ is removed at step $t_0$ where $t_0 = \min \{i \mid v\in X_i\}$, and any vertex $v\in J$ is added at step $t_1$ where $t_1= \min \{i\mid v\in X_{i-1} \wedge v\notin X_i\}$. We call $\Gamma_{\mathcal{P},G}$ the set of canonical path $\gamma_{I,J}$ obtained for all pair of independent sets $I,J\in \mathcal{I}(G)$.


The next lemma is the equivalent of Lemma~\ref{lemma:Congestion1} for path decomposition instead of separator tree.
\begin{lemma}\label{lemma:CongestionPath1}
Let $G$ be a graph, $\mathcal{P} = \{X_t\}_{1\leqslant t\leqslant p}$ a path decomposition of $G$ with $X_p=\emptyset$, $I\in \mathcal{I}(G)$ and $v\notin N[I]$. In addition, let $t = \min \{i \mid v\in X_{i-1} \wedge v\notin X_i\}$. Then, for any $\lambda> 0$,
$$
\rho(\Gamma_{\mathcal{P},G}, (I, I\cup \{v\})) \leqslant 2n^2\frac{\lambda+1}{\lambda}\frac{1}{\lambda^{|I\cap X_t|}} Z_{X_t}(\lambda)^2
$$
\end{lemma}

\begin{proof}
By Equation~\ref{Congestion} and similarly to in the proof of Lemma~\ref{lemma:Congestion1}, we have 
$$
\rho(\Gamma_{\mathcal{P},G}, (I, I\cup \{v\}) 
     \leqslant 2n^2\frac{\lambda+1}{\lambda} \frac{Z_G(\lambda)}{\lambda^{|I|}}\sum_{\substack{K,L\in \mathcal{I}(G) \\ (I,I')\in \gamma_{K, L}}} \pi(K)\pi(L) 
$$
Suppose that $(I,I\cup\{v\})\in \gamma_{K,L}$ for some independent sets $K,L \in \mathcal{I}(G)$. We define two sets 
$$
\begin{array}{ll}
     L_t &= \bigcup_{1\leqslant i \leqslant t-1} X_{i} \setminus X_t\\
     R_t &= V(G) \setminus (L_v\cup X_t)
\end{array}
$$

Suppose that $(I,I\cup \{v\})$ is on the path $\gamma_{K,L}$. This transition has to be used in the step $t$ of the path, when the vertices of $X_{t-1}\setminus X_t$ are added to the current independent set. In particular, all the steps from $1$ to $t-1$ have been done, and thus all the vertices from $K\cap \bigcup_{1\leqslant j \leqslant t-1}X_j \setminus X_t$ have been replaced by the vertices of $L\cap \bigcup_{1\leqslant j \leqslant t-1}X_j \setminus X_t$. It follows that $I\cap L_t = L$. Similarly, all the steps from $t+1$ to $p$ have yet to be executed, and thus the vertices of $K\cap \bigcup_{t+1\leqslant j \leqslant p} X_j \setminus X_t$ have not been modified. It follows that $I\cap R_t = K\cap R_t$. We obtain that 
$$
\sum_{\substack{K,L\in \mathcal{I}(G) \\ (I,I\cup\{v\})\in \gamma_{K,L}}} \pi(K)\pi(L) \leqslant \left(\sum_{\substack{K\in \mathcal{I}(G) \\ K\cap R_t = I\cap R_t}} \pi(K) \right) 
    \left(\sum_{\substack{L\in \mathcal{I}(G) \\ L\cap L_t = I\cap L_t}} \pi(L) \right)
$$
As in the proof of Lemma~\ref{lemma:Congestion1}, a successive application of Lemmas~\ref{lemma:Technical}.(\ref{lemma:Technical1}) and~\ref{lemma:Technical}.(\ref{lemma:Technical2}) gives :
$$
\sum_{\substack{K\in \mathcal{I}(G) \\ K\cap R_t = I\cap R_t}} \pi(K) \leqslant \frac{\lambda^{|I\cap R_t|}}{Z_G(\lambda)}Z_{L_t}(\lambda)Z_{X_t}(\lambda) 
$$
$$
\sum_{\substack{K\in \mathcal{I}(G) \\ K\cap L_t = I\cap L_t}} \pi(K) \leqslant \frac{\lambda^{|I\cap L_t|}}{Z_G(\lambda)}Z_{R_t}(\lambda)Z_{X_t}(\lambda)
$$
By combining the inequalities, it follows
$$
\rho(\Gamma_{\mathcal{P},G}, (I, I\cup \{v\})) \leqslant 2n^2\frac{\lambda+1}{\lambda} \frac{\lambda^{|I\cap L_t|+|I\cap R_t|}}{\lambda^{|I|}} \frac{Z_{L_t}(\lambda) Z_{R_t}(\lambda)Z_{X_t}(\lambda)^2 }{ Z_G(\lambda)}
$$
Finally, by Lemma~\ref{lemma:Technical}.(\ref{lemma:Technical2}), we obtain 
$$
\rho(\Gamma_{\mathcal{P},G}, (I, I\cup \{v\})) \leqslant 2n^2\frac{\lambda+1}{\lambda}\frac{1}{\lambda^{|I\cap X_t|}} Z_{X_t}(\lambda)^2
$$
\end{proof}


Similarly, the next lemma is the equivalent of Lemma~\ref{lemma:Congestion2} for path decomposition instead of separator tree.
\begin{lemma}\label{lemma:CongestionPath2}
Let $G$ be a graph, $\mathcal{P} = \{X_t\}_{1\leqslant t\leqslant p}$ a path decomposition of $G$ with $X_p=\emptyset$, $I\in \mathcal{I}(G)$ and $v\in I$. In addition, let $t = \min \{i \mid v\in X_i\}$. Then, for any $\lambda> 0$,
$$
\rho(\Gamma_{\mathcal{P},G}, (I, I\setminus \{v\})) \leqslant 2n^2(\lambda+1)\frac{1}{\lambda^{|I\cap X_t|}} Z_{X_t}(\lambda)^2
$$
\end{lemma}

\begin{proof}
By Equation~\ref{Congestion} and similarly to in the proof of Lemma~\ref{lemma:Congestion2}, we have 
$$
\rho(\Gamma_{\mathcal{P},G}, (I, I\setminus\{v\}) 
    \leqslant 2n^2 \frac{Z_G(\lambda)}{\lambda^{|I|}}(\lambda+1) \sum_{\substack{K,L\in \mathcal{I}(G) \\ (I,I')\in \gamma_{K, L}}} \pi(K)\pi(L)
$$
Suppose that $(I,I\setminus\{v\})\in \gamma_{K,L}$ for some independent sets $K,L \in \mathcal{I}(G)$. We define two sets 
$$
\begin{array}{ll}
     L_t &= \bigcup_{1\leqslant i \leqslant t-1} X_{i} \setminus X_t\\
     R_t &= V(G) \setminus (L_v\cup X_t)
\end{array}
$$

Suppose that $(I,I\setminus \{v\})$ is on the path $\gamma_{K,L}$. This transition is used in the step $t$ of the path, that is when the vertices of $K\cap X_t$ are removed. Similarly to the proof of Lemma~\ref{lemma:CongestionPath1}, we have  $I\cap L_t = L$ and $I\cap R_t = K\cap R_t$. Again, we obtain that, 
$$
\sum_{\substack{K,L\in \mathcal{I}(G) \\ (I,I\setminus\{v\})\in \gamma_{K,L}}} \pi(K)\pi(L) \leqslant \left(\sum_{\substack{K\in \mathcal{I}(G) \\ K\cap R_t = I\cap R_t}} \pi(K) \right) 
    \left(\sum_{\substack{L\in \mathcal{I}(G) \\ L\cap L_t = I\cap L_t}} \pi(L) \right)
$$
Following the exact same proof of Lemma~\ref{lemma:CongestionPath1}, the result holds.
\end{proof}



The next Lemma is the equivalent of Lemma~\ref{lemma:Congestion3} for path decomposition instead of separator tree.

\begin{lemma}\label{lemma:CongestionPath3}
Let $G$ be a graph, $\mathcal{P} = \{X_t\}_{1\leqslant t\leqslant p}$ a path decomposition of $G$ with $X_p=\emptyset$. Then, for any any $\lambda>0$,
$$
\rho(\Gamma_{\mathcal{P},G}) \leqslant 4n^2\tilde{\lambda}^{2\alpha+1}\max_{1\leqslant t\leqslant p}|\mathcal{I}(G_{X_t})|^2
$$
where $\tilde{\lambda}=e^{|\ln \lambda|}$ and $\alpha = \max_{1\leqslant t\leqslant p} \alpha(G[X_t])$.
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lemma:CongestionPath3}]
Let $(I,I')$ be a transition of the Markov chain. By definition of $\Gamma:= \Gamma_{\mathcal{P},G}$, no canonical path use the transition $(I,I)$, since at each step either a vertex is added or is deleted to the current independent set. Thus, we only consider the cases $I'=I\cup \{v\}$ for some $v\in V(G)\setminus N[I]$ or $I'= I\setminus \{v\}$ for some vertex $v\in I$. In both cases, by Lemma~\ref{lemma:CongestionPath1} and Lemma~\ref{lemma:CongestionPath2}, there exists a $t \in \{1,\cdots, p\}$ such that 
$$
\rho(\Gamma,(I,I')) \leqslant 2n^2\max\left(\lambda+1, \frac{\lambda}{\lambda+1} \right)\frac{1}{\lambda^{|I\cap X_t|}}Z_{X_t}(\lambda)^2 
$$
First, suppose that $\lambda \geqslant 1$. In this case, the equality $\tilde{\lambda} = \lambda$ holds, and by Lemma~\ref{lemma:Technical}.(\ref{lemma:Technical0}),  
$$
Z_{X_t}(\lambda) \leqslant \tilde{\lambda}^{\alpha(G[X_t])} |\mathcal{I}(G[X_t])|
$$
Since $\frac{1}{\lambda^{|I\cap X_t|}} \leqslant 1$ and $\lambda+1 \leqslant 2\lambda$, we obtain:  
$$
\rho(\Gamma,(I,I')) \leqslant 4n^2 \tilde{\lambda}^{2\alpha(G[X_t])+1} |\mathcal{I}(G[X_t])|^2
$$
Next, suppose that $\lambda \in (0,1)$. In this case, the equality $\tilde{\lambda} = \lambda^{-1}$ holds. Since $\lambda^{\alpha(G[X_t])} \leqslant 1$, Lemma~\ref{lemma:Technical}.(\ref{lemma:Technical0}) implies $Z_{A_v}(\lambda) \leqslant |\mathcal{I}(G[X_t])|$. Furthermore, we have $\max\left(\lambda+1, \frac{\lambda+1}{\lambda} \right) \leqslant 2\tilde{\lambda}$, and $\frac{1}{\lambda^{|I\cap X_t|}} \leqslant \tilde{\lambda}^{\alpha(G[X_t])}$. It follows that  
$$
\rho(\Gamma,(I,I')) \leqslant 4n^2 \tilde{\lambda}^{\alpha(G[X_t])+1} |\mathcal{I}(G[X_t])|^2
$$
The conclusion is straightforward.
\end{proof}

We are now equipped to prove the main result of this section, which is Theorem~\ref{thm:Path}.

\begin{proof}[Proof of Theorem~\ref{thm:Path}]
Let $\mathcal{P}=\{X_t\}_{1\leqslant t \leqslant p}$ be a path decomposition of $G$, where $p$ is the number of bags in the path decomposition and $X_p = \emptyset$. We bound the congestion of the set of canonical paths $\Gamma :=\Gamma_{\mathcal{P},G}$. The reasoning follows exactly as in the proof of Theorem~\ref{thm:SubexpMixingTime}. By Lemma~\ref{lemma:CongestionPath3}, we have
$$
\rho(\Gamma) \leqslant 4n^2 \tilde{\lambda}^{1+2\max_{1\leqslant t \leqslant p} \alpha(G[X_t])}\max_{1\leqslant t\leqslant p}|\mathcal{I}(G[X_t])|^2
$$
 Then, we bound both $\alpha(G[X_t])$ and $|\mathcal{I}(G[X_t])|$ for all $1\leqslant t \leqslant p$, depending on whether the path decomposition is a witness for $\pw(G)$ or $\pa(G)$.

Firstly, suppose that, for any $1\leqslant t\leqslant p$, $|X_t|\leqslant \pw(G)+1$. It follows that $G[X_t]$ contains at most $2^{\pw(G)+1}$ distinct independent sets, each of size at most $\pw(G)+1$. Thus, 
$$
\rho(\Gamma) \leqslant 4n^2 \tilde{\lambda}^{2\pw(G)+3}2^{2\pw(G)+2} \leqslant 4n^2(2\tilde{\lambda})^{2\pw(G)+3}
$$
Using Theorem~\ref{thm:BoundCanonicalPaths} and $\min_{I\in \mathcal{I}(G)} \pi_{G,\lambda}(I) \geqslant (2\tilde{\lambda})^{-n}$,
$$
\tau_{G,\lambda} \leqslant 4n^2(2\tilde{\lambda})^{2\pw(G)+3} \ln\left( 4(2\tilde{\lambda})^{-n}\right)
$$
and finally $\tau_{G,\lambda} = (2\tilde{\lambda})^{2\pw(G)+4} \cdot n^{O(1)}$.

Secondly, suppose that, for any $1\leqslant t\leqslant p$, $\alpha(G[X_t])\leqslant \pa(G)$ and $|X_t| \leqslant b$. It follows that $G[X_t]$ contains at most $b^{\pa(G)}$ distinct independent sets, each of size at most $\pa(G)$. Thus, 
$$
\rho(\Gamma) \leqslant 4n^2 \tilde{\lambda}^{2\pa(G)+1}b^{2\pa(G)} \leqslant 4n^2(b\tilde{\lambda})^{2\pa(G)+1}
$$
Using Theorem~\ref{thm:BoundCanonicalPaths}, we obtain that $\tau_{G,\lambda} = (b\tilde{\lambda})^{2\pa(G)+2} \cdot n^{O(1)}$.
\end{proof}



\subparagraph{Tree independence number.}
To establish bounds on the mixing time parameterized by the tree independence number, there are two possible approaches. One option is to use a separator-tree-based method, as in Section~\ref{sec:GeometricGraphs}. The other is to relate the width of path decompositions to the width of tree decompositions. A result of this type is already known for sparse parameters: for any $n$-vertex graph, it is known that $\pw(G) = O(\ln(n))\tw(G)$~\cite{korach1993tree}. We provide a strengthening of this result for the dense case. 


\begin{lemma}\label{lemma:structural_bounds}
Let $G$ be a graph with $n$ vertices, and let $\mathcal{T}=(T,\{X_t\}_{t\in V(T)})$ be a tree decomposition of $G$ such that $|V(T)|\leqslant 4n$ and for any $t\in V(T)$, $|X_t|\leqslant b$ and $\alpha(G[X_t])\leqslant k$. Then, there exists a path decomposition $\mathcal{P}=\{Y_i\}_{1\leqslant i \leqslant p}$ such that for each $1\leqslant i \leqslant p$ :
\begin{itemize}
    \item $|Y_i|\leqslant b(\log_2(n)+3)$ ;
    \item $\alpha(G[Y_i])\leqslant k(\log_2 n + 3)$ ;
    \item  $|\mathcal{I}(G[Y_i])|\leqslant b^{(\log_2 n + 3)k}$.
\end{itemize}
\end{lemma}


\begin{proof}
We begin by proving the following well-known bound on the pathwidth of trees.

\begin{claim}
For any tree $T$ with $n$ vertices, $\pw(T) \leqslant \log_2 n$.
\end{claim}

\begin{proof}
We proceed by induction on $n$. The base case is trivial for trees with at most two vertices. Assume the statement holds for all trees with at most $n-1$ vertices. 

Let $T$ be a tree with $n$ vertices. Define a vertex $r \in V(T)$ such that the maximum size of a connected component of $T - r$ is minimized. Let $T_1, \dots, T_k$ be these connected components. By the choice of $r$, each $T_i$ has at most $n/2$ vertices; otherwise, the only vertex adjacent to $r$ in $T_i$ would contradict the minimality condition. By the induction hypothesis, for each $1\leqslant i \leqslant k$, we have $\pw(T_i) \leqslant \log_2(n/2)$. 

Concatenating the $k$ path decompositions of $T_1, \dots, T_k$ and adding $r$ to each bag results in a path decomposition of $T$ of width at most $\log_2(n/2) + 1 = \log_2 n$, completing the induction.
\end{proof}

Now, we use this claim to establish both statements of the lemma. By the previous claim, $T$ admits a path decomposition $\mathcal{P}_{T}=(U_i)_{1\leqslant i \leqslant p}$ such that for any $1\leqslant i \leqslant p$, $|U_i| \leqslant \log_2(4n)+1 = \log_2 n + 3$. For each $1\leqslant i \leqslant p$, define $Y_i = \bigcup_{t\in U_i}X_t$. Then, $\mathcal{P}=(Y_i)_{1\leqslant i \leqslant p}$ is a path decomposition of $G$.Let $1\leqslant i \leqslant p$. 
\begin{itemize}
    \item Since for any $t\in U_i$, $|X_t|\leqslant b$, it follows that $|Y_i| \leqslant b(\log_2(n)+3)$.
    \item Any independent set of $G[Y_i]$ is the disjoint union of independent sets $I_t$, where each $I_t \subseteq X_t$ for some $t\in U_i$. Since $\alpha(G[X_t]) \leqslant k$ for $t\in U_i$, it follows that $\alpha(G[Y_i])\leqslant k(\log_2 n + 3)$. 
    \item Similarly, since $G[X_t]$ has at most $t^k$ independent sets for $t\in U_i$, it follows that $|\mathcal{I}(G[Y_i])|\leqslant b^{k(\log_2 n + 3)}$. 
\end{itemize}
\end{proof}


Using these inequalities, we derive new bounds on the mixing time of the Glauber dynamics for independent sets in terms of treewidth and tree independence number. The first case of the following theorem corresponds to the result of Eppstein and Frishberg \cite{eppstein2023rapid}. The second result, which is exactly Theorem~\ref{thm:TreeIndependenceNumber}, generalizes the result of Bez\'akov\'a and Sun \cite{bezakova2020mixing}, as chordal graphs are exactly graph of tree independence number $1$.



\begin{theorem}\label{thm:generalized_mixing_time}
Let $G$ be a graph with $n$ vertices. The mixing time of the Glauber dynamics on $G$ with fugacity $\lambda > 0$ satisfies:
\begin{itemize}
    \item $\tau_{G,\lambda} = n^{O(\tw(G))\ln(\tilde{\lambda})} $ ;
    \item $\tau_{G,\lambda} = n^{O(\ta(G))\cdot \ln(b\tilde{\lambda})} $, where $b$ is the minimum width (plus one) of a tree decomposition of tree independence number $\ta(G)$.
\end{itemize}
where $\tilde{\lambda}=e^{|\ln \lambda|}$.
\end{theorem}

\begin{proof}
The first case is a direct consequence of Theorem~\ref{thm:Path} and Lemma~\ref{lemma:structural_bounds}. We focus on the second case. Let $\mathcal{P}=\{X_i\}_{1\leqslant i \leqslant p}$ be a path decomposition of a graph $G$, where $p$ is the number of bags in the path decomposition and $X_p = \emptyset$. In addition, from Lemma~\ref{lemma:structural_bounds}, suppose that for each $1\leqslant i \leqslant p$, we have $\alpha(G[X_i])\leqslant (\log_2(n)+3)\ta(G)$ and $|\mathcal{I}(G[X_i])|\leqslant b^{(\log_2(n)+3)\ta(G)}$.

We show that the congestion is bounded on the set of canonical paths $\Gamma :=\Gamma_{\mathcal{P},G}$. The reasoning follows exactly as in the proof of Theorem~\ref{thm:Path}. By Lemma~\ref{lemma:CongestionPath3}, we have
\begin{align*}
\rho(\Gamma) &\leqslant 4n^2 \tilde{\lambda}^{1+2\max_{1\leqslant t \leqslant p} \alpha(G[X_t])}\max_{1\leqslant t\leqslant p}|\mathcal{I}(G[X_t])|^2  \\
&\leqslant 4n^2\tilde{\lambda}^{1+2(\log_2(n)+3)\ta(G)} b^{2(\log_2(n)+3)\ta(G)}
\end{align*}
Using Theorem~\ref{thm:BoundCanonicalPaths}, we obtain that $\tau_{G,\lambda} = n^{O(\ta(G))\cdot \ln(b\tilde{\lambda})}$.
\end{proof}


\section{Lower bound on the mixing time of Glauber dynamics}\label{sec:LowerBounds}



This section is dedicated to reviewing and establishing lower bounds on the mixing time of the Glauber dynamics, based on upper bounds on the conductance of the Markov chain. We demonstrate that our parameterized mixing time bounds for dense graphs are tight by constructing, in each case, a family of graphs that matches the upper bounds stated in Theorems~\ref{thm:Path} and~\ref{thm:TreeIndependenceNumber}. %In Appendix~\ref{appendix:ETHLowerBound}, we discuss other kinds of lower bounds, based on computational complexity assumptions.

\subsection{Geometric intersection graphs}

Most of the research on Glauber dynamics has focused on the distinction between fast mixing and torpid mixing, where the latter corresponds to an exponential mixing time. Lattices provide a prototypical example of graphs exhibiting torpid mixing. In their seminal work, the authors of~\cite{borgs1999torpid} studied Glauber dynamics on the $d$-dimensional torus and established the following result:


\begin{theorem}[\cite{borgs1999torpid}]\label{thm:LowerBoundTorus}
Let $T_{L,d}$ be the $d$-dimensional torus with side length $L$. For $d\geqslant 2$ and $\lambda$ sufficiently large, the mixing time of the glauber dynamcis on $T_{L,d}$ verifies :
$$
\tau_{T_{L,d},\lambda} \geqslant e^{cL^{d-1}/\ln^2(L)}
$$
where $c$ is a constant depending only on $d$.
\end{theorem}

This theorem already demonstrates some tightness in the bound of Theorem~\ref{thm:SubexpMixingTime}. Indeed, let $\mathcal{H}(T_{L,d})$ be the set of induced subgraphs of $T_{L,d}$, which forms a hereditary class by definition. It is easy to observe that any $n$-vertex graph $G \in \mathcal{H}(T_{L,d})$ has a balanced separator consisting of at most $\sqrt{n}$ vertices, and thus admits a $(1/2, \sqrt{n})$-clique-based separator. Consequently, in the statement of Theorem~\ref{thm:SubexpMixingTime}, it is not possible to improve the exponent of $n$.

However, it is important to note that the 2-dimensional torus (resp. the $d$-dimensional torus) is not a disk graph (resp. a $d$-dimensional ball graph), and thus Theorem~\ref{thm:LowerBoundTorus} does not directly provide a lower bound for Theorem~\ref{thm:BallGraphs}. Nevertheless, for sufficiently large $L$, the torus $T_{L,d}$ is a $(d+1)$-dimensional ball graph. As a result, the exponent in Theorem~\ref{thm:BallGraphs} cannot be improved beyond $(d-2)/d$.

In the two-dimensional case, Randall~\cite{randall2006slow} established a stronger lower bound on the mixing time of Glauber dynamics on the 2-dimensional grid. Using the direct implication of Theorem~\ref{thm:LowerBoundConductance}, it follows :

\begin{theorem}[\cite{randall2006slow}]
Let $\Lambda_{L,2}$ be the $2$-dimensional grid with side length $L$. For  $\lambda\geqslant 58.612$, the mixing time of the glauber dynamics on $\Lambda_{L,2}$ verifies :
$$
\tau_{\Lambda_{L,2},\lambda} \geqslant e^{cL}
$$
where $c$ is a constant.
\end{theorem}

The generalization to the $d$-dimensional grid remains to be proven but appears to hold. Notably, in the case of the Ising model, which shares many similarities with the hard-core model, Thomas~\cite{thomas1989bound} demonstrated that the mixing time is indeed exponential in $n^{1-1/d}$ on the $d$-dimensional grid with $n$ vertices.

\subsection{Pathwidth and path independence number.} 

Using a conductance argument, the simplest graph on which Glauber dynamics mixes in exponential time is the complete bipartite graph $K_{t,t}$. Indeed, to transition from an independent set contained entirely in one part to an independent set contained in the other, the dynamics must pass through the empty independent set, which has significantly lower energy compared to any other state. Observe that this graph has pathwidth exactly $t$. We show that this graph establishes the tightness of the FPT mixing time bound in terms of pathwidth.

\begin{theorem}\label{thm:LowerBoundPw}
For any $c>0$, there exists a $n$-vertex graph $G$  such that for any $\lambda\geqslant 1$,  
$$
\tau_{G,\lambda} \geqslant  \left(\frac{\lambda+1}{2}\right)^{\pw(G)} \cdot n^{c}
$$
\end{theorem}

\begin{lemma}\label{lemma:PiEdgeless}
Let $G$ be an edgeless graph with $n$ vertices. Then, for any $\lambda>0$, $Z_G(\lambda)=(\lambda+1)^n$.
\end{lemma}

\begin{proof}
For any $0\leqslant k \leqslant n$, $G$ has $\binom{n}{k}$ independent sets of size exactly $k$. It follows that 
$$
Z_G(\lambda) = \sum_{k=0}^n \binom{n}{k}\lambda^k = (\lambda+1)^n
$$
\end{proof}



\begin{proof}[Proof of Theorem~\ref{thm:LowerBoundPw}]
Let  $\Omega_t = \mathcal{I}(K_{t,t})$ as the set of independent sets of $K_{t,t}$. It is straightforward to verify that $K_{t,t}$ has pathwidth exactly $t$. Let $(A_t,B_t)$ be the unique bipartition of $V(G_t)$ such that both $A_t$ and $B_t$ are maximum independent sets of $G_t$. Define $\Omega_A$ (resp. $\Omega_B$) as the set of independent sets of $G_t$ contained entirely within $A_t$ (resp. $B_t$). 

Notice that any path from $\Omega_A$ to $\Omega_B$ in $\mathcal{G}(K_{t,t})$ must pass through the empty set. Otherwise, such a path would contain an independent set which intersect both $A_t$ and $B_t$, contradicting the definition of an independent set. By Theorem~\ref{thm:LowerBoundConductance}, and using the fact that $\pi(\Omega_A) = \pi(\Omega_B)$ by symmetry, we obtain :
$$
\tau_{G,\lambda} \geqslant \frac{\ln(2)}{4}\left( \frac{\pi(\Omega_A)}{\pi(\{\emptyset\})}-2\right) 
$$  
Since $\pi(\emptyset) = \frac{1}{Z_G(\lambda)}$ and $\pi(\Omega_A) = \frac{(\lambda+1)^t}{Z_G(\lambda)}$ by Lemma~\ref{lemma:PiEdgeless}, it follows that
$$
\tau_{G,\lambda} \geqslant \frac{\ln(2)}{4}(\lambda+1)^t
$$  
Then, observe that there exists some constant $t_c\geqslant 1$ such that for any $t\geqslant t_c$, the following inequality holds:
$$
\frac{\frac{\ln(2)}{4}(\lambda+1)^{t}}{\left(\frac{\lambda+1}{2}\right)^t\cdot (2t)^c } = \frac{\ln(2)}{4}2^{t-c\log_2(2t)}>1
$$
which finally leads to 
$$
\tau_{G,\lambda} \geqslant \left(\frac{\lambda+1}{2}\right)^{t} \cdot (2t)^c 
$$  
when $t$ is large enough.
\end{proof}



By replacing each vertex in $K_{t,t}$ with a clique, we establish the tightness of the mixing time in terms of the path independence number.

\begin{theorem}\label{thm:LowerBoundPa}
For any $t\geqslant 1$, there exists infinitely many graphs $G$ such that $\pa(G)=t$ and for any $\lambda \geqslant 1$,
$$
\tau_{G,\lambda} \geqslant c_t\left(n\lambda\right)^{t}
$$
where $n=|V(G)|$ and $c_t$ is a constant which only depends on $t$.
\end{theorem}

\begin{lemma}\label{lemma:P3-free}
Let $G$ be a graph which is the disjoint union of $t$ cliques of size $n$. Then, for any $\lambda>0$, $Z_G(\lambda)=(n\lambda+1)^t$.
\end{lemma}

\begin{proof} 
For any $0\leqslant k \leqslant t$, $G$ has exactly $n^k \binom{t}{k}$ independent sets of size exactly $k$. Indeed, any independent set must intersect each clique in at most one vertex, meaning that choosing an independent set corresponds to selecting $k$ cliques and picking exactly one vertex inside each chosen clique. It follows that:
$$
Z_G(\lambda) = \sum_{k=0}^t \binom{t}{k}n^k \lambda^k = (n\lambda+1)^t
$$
\end{proof}


\begin{lemma}[Folklore]\label{lemma:Neighboroodtree}
For any graph $G$ and tree decomposition $\mathcal{T}=(T,\{X_t\}_{t\in V(T)})$ of $G$, there exist $v\in V(G)$ and $t\in V(T)$ such that $N[v] \subseteq X_t$.
\end{lemma}

\begin{comment}
\begin{proof}
Root the tree $T$ at an arbitrary node $r \in V(T)$. For each vertex $v \in V(G)$, let $d_v$ be the minimum distance from $r$ to a node $t \in V(T)$ such that $v \in X_t$. Let $u \in V(G)$ be a vertex for which $d_u$ is maximal, and let $t_u \in V(T)$ be the closest node to $r$ satisfying $u \in X_{t_u}$. We will prove that $N(u) \subseteq X_{t_u}$.

Suppose, for contradiction, that there exists a vertex $v \in N(u)$ such that $v \notin X_{t_u}$. If $t_u \neq r$, let $t$ be the parent of $t_u$. By the maximality of $d_u$, we have $u \notin X_t$. Thus, by the definition of a tree decomposition, $u$ appears only in bags associated with nodes in the subtree of $T$ rooted at $t_u$.

Since there exists a node $t \in V(T)$ such that ${u,v} \subseteq X_t$, this node $t$ must also belong to the subtree rooted at $t_u$. Because $v \notin X_{t_u}$ and, by the connectivity condition of a tree decomposition, $v$ appears only in bags within the subtree rooted at $t_u$, it follows that $d_v > d_u$, which contradicts the choice of $u$. Hence, we conclude that $N[u] \subseteq X_{t_u}$.
\end{proof}
