\begin{lemma}\label{lemma:PropertiesGk}
Let $k\geqslant 0$. The following properties hold.
\begin{enumerate}[(i)]
    \item\label{sublemma:TwoMIS} The graph $G_k$ has $2^{k+2}-2$ vertices and exactly two distinct MIS $I_k$ and $J_k$ of size $\alpha(G_k) = 2^{k+1}-1$, and they form a partition of $V(G_k)$.
    \item\label{sublemma:SmallIS} There is a constant $c_1$ such that for every path $(W_i)_{0\leqslant i \leqslant p}$ from $I_k$ to $J_k$ in $\mathcal{G}(G_k)$, there exists some $0\leqslant i \leqslant p$ such that $|W_i| \leqslant \alpha(G_k) - \lfloor c_1 \cdot k \rfloor$.
    \item\label{sublemma:CountIS} For any $d\geqslant 0$, $G_k$ contains at most $2^{2d+1}\alpha(G_k)^d$ independent sets of size exactly $\alpha(G_k) - d$.
\end{enumerate}
\end{lemma}



\begin{proof}
We start by proving point (\ref{sublemma:TwoMIS}). We prove the result by induction on $k$. The base case $k=0$ is straightforward: $G_0$ consists of two adjacent vertices, so it has $|V(G_0)| = 2$ and exactly one maximum independent set of size $\alpha(G_0) = 1$.

Now, suppose the statement holds for $G_{k-1}$. By construction, $G_k$ is obtained from $G_{k-1}$ by adding a new root node $r$ to the binary tree, along with its corresponding set $X_t = {u_t, v_t}$.  By the induction hypothesis, both copies of $G_{k-1}$ in $G_k$, that we call $G_1$ and $G_2$, in $G_k$ contains exactly two distinct MIS, each of size $2^{k}-1$. Let $r_1 \in V(T_k)$ (resp. $r_2$) be the child of $r$ in $T_k$ which correspond to the root bag of $G_1$ (resp. $G_2$). For $i\in \{1,2\}$, let $I_{i,u}$ be the MIS of $G_1$ which contain $u_{r_i}$, and let $I_{i,v}$ be the MIS of $G_2$ that contains $v_{r_i}$. In $G_k$, we construct two MIS as follows:
\begin{itemize}
\item The first MIS, denoted $I_k$, is exactly $\{u_r\}\cup I_{1,v} \cup I_{2,v}$.
\item The second MIS, denoted $J_k$, is exactly $\{v_r\}\cup I_{1,u} \cup I_{2,u}$.
\end{itemize}
Since every vertex belongs to exactly one of these two independent sets, they partition $V(G_k)$. Additionally, the size of each MIS in $G_k$ satisfies:
$$
\alpha(G_k) = 1+2\alpha(G_{k-1}) = 1+2(2^{k}-1) = 2^{k+1}-1
$$
Thus, the lemma holds for all $k \geqslant 0$.\newline

Then, we prove point (\ref{sublemma:SmallIS}), i.e. that any path from $I_k$ to $J_k$ in the reconfiguration graph $\mathcal{G}(G_k)$ pass through a small independent set, using the isoperimetric value of a complete tree.


\begin{claim}[\cite{bharadwaj2009bounds}]\label{lemma:BinaryTree}
There exists a universal constant $c_1 > 0$ such that  
$$
\max_{1\leqslant i\leqslant |V(T_k)|} \min_{\substack{S\subseteq V(T_k) \\ |S|=i}} |N_{T_k}(S)| \geqslant c_1 \cdot k.
$$
\end{claim}
Let $\text{iso}(k)$ be the index at which the maximum is attained.


For each $0\leqslant i \leqslant p$, define $J_i = W_i\cap J_k$. Observe that for all $1\leqslant i <p$, we have $|J_{i+1}|\leqslant |J_i|+1$, with $|J_0|=0$ and $|J_t|=n$. Let $i_0$ be the smallest index such that $|J_{i_0}| = \text{iso}(k)$, and define $S = \{t\in V(T_k) \mid X_t\cap W_{i_0} \neq \emptyset\}$. 

By Claim~\ref{lemma:BinaryTree}, we have $|N_{T_k}(S)|\geqslant c_1\cdot k$. Let $t' \in N_{T_k}(S)$, and note that $X_{t'}\cap W_{i_0} =\emptyset$. Indeed, if $X_{t'}\cap W_{i_0} \cap J_k \neq \emptyset$, then $t'\in S$, contradicting our assumption. Similarly, if $X_{t'}\cap W_{i_0} \cap I_k \neq \emptyset$, then $W_i$ would contain two adjacent vertices, which is impossible. Thus, $W_{i_0}$ intersects at most $|V(T_k)| - \lfloor c_1\cdot k \rfloor$ sets $X_t$, implying that $|W_{i_0}| \leqslant 2^{k+1}-1 - \lfloor c_1 \cdot k \rfloor$. 

Since for any $0\leqslant i <p$, the symmetric difference between $W_i$ and $W_{i+1}$ has size at most~$1$, there must exists some $i$ such that $|W_i| = \alpha(G_k) - \lfloor c_1 \cdot k \rfloor$.\newline

Finally, we prove point (\ref{sublemma:CountIS}). Note that this result was not necessary to prove that TAR-reconfiguration threshold is unbounded in \cite{de2018independent}, but in our case, obtaining such a bound is necessary to apply a conductance argument.

Let $D \subseteq V(T_k)$ be a subset of $d$ nodes of $T_k$. Since $T_k$ is a tree, removing all vertices in $D$ results in a forest. Let $R_D$ be the set of nodes that serve as the roots of the connected components in the forest $T_k - D$. More formally, a node $t \in V(T_k) \setminus D$ belongs to $R_D$ if and only if either $t$ is the child of a node $t' \in D$ or $t$ is the root of $T_k$.

We now prove that there exists a bijection between the independent sets of $G_k$ of size $\alpha(G_k) - d$ and the set $\mathcal{D} = \{(D,\{0,1\}^{R_D}\}_{D\subseteq V(T_k), |D|=d}$.

Given a subset $D \subseteq V(T_k)$ with $|D| = d$ and a function $c_D : R_D \to {0,1}$, we define an independent set $I = f(D, c_D)$ of $G_k$ as follows: 
\begin{itemize}
    \item $I$ intersects each bag $X_t$ for all $t \in V(T_k) \setminus D$.
    \item For each $t \in R_D$, if $c_D(t) = 0$, then $u_t \in I$; otherwise, $v_t \in I$.
\end{itemize}


Now, we prove that there exists a unique independent set $I$ of size $\alpha(G_k) - d$ that satisfies the two conditions above. We will use the following claim. 

\begin{claim}\label{claim:UniqueIS}
Let $T$ be a subtree of $T_k$ with root $r\in V(T)$. Then $G_k[\bigcup_{t\in V(T)} X_t]$ has exactly two independent sets of size $|V(T)|$, one containing $u_r$ and the other containing $v_r$.
\end{claim}

\begin{proof}
We prove the result by induction on $|V(T)|$.  If $T$ consists of a single node $r$, then $X_r = \{u_r, v_r\}$, and the only two independent sets of size $1$ are $\{u_r\}$ and $\{v_r\}$, which satisfies the claim.  Suppose the result holds for all subtrees of $T_k$ with at most $m-1$ nodes. Let $T$ be a subtree of $T_k$ with $m \geqslant 2$ nodes, rooted at $r\in V(T)$. Suppose that $r$ has two children, $r_1$ and $r_2$, both belonging to $V(T)$. Let $T_1$ and $T_2$ be the subtrees of $T$ rooted at $r_1$ and $r_2$, respectively.  

Since both $T_1$ and $T_2$ have at most $m-1$ nodes, we can apply the induction hypothesis to them. This means that:  
\begin{itemize}
\item $G_k[\bigcup_{t\in V(T_1)} X_t]$ has exactly two independent sets of size $|V(T_1)|$, one containing $u_{r_1}$, called $I_{1,u}$ and the other containing $v_{r_1}$, called $I_{1,v}$.  
\item $G_k[\bigcup_{t\in V(T_2)} X_t]$ has exactly two independent sets of size $|V(T_2)|$, one containing $u_{r_2}$, called $I_{2,u}$ and the other containing $v_{r_2}$, called $I_{2,v}$.  
\end{itemize}
To construct an independent set $I$ of $G_k[\bigcup_{t\in V(T)} X_t]$ of size $|V(T)|$, we must include exactly one vertex from each bag $X_t$ for every $t \in V(T)$. 

Thus, we have exactly two choices for constructing $I$:  
\begin{itemize}
\item If $u_r \in I$, then we must take $v_{r_1} \in I$ and $v_{r_2} \in I$ since $u_r$ is adjacent to both vertices $u_{r_1}$ and $u_{r_2}$. By induction, this forces us to take the unique independent sets $I_{1,v}$ and $I_{2,v}$ corresponding to $T_1$ and $T_2$ that contain $v_{r_1}$ and $v_{r_2}$, respectively. Hence,  
  $$
  I = \{u_r\} \cup I_{1,v} \cup I_{2,v}.
  $$
\item Similarly, if $v_r \in I$, then we must take $u_{r_1} \in I$ and $u_{r_2} \in I$, leading to the unique independent sets $I_{1,u}$ and $I_{2,u}$ that contain $u_{r_1}$ and $u_{r_2}$, respectively. Hence,  
  $$
  I = \{v_r\} \cup I_{1,u} \cup I_{2,u}.
  $$  
\end{itemize}
If $r$ has only one child $r_1$ belonging to $V(T)$, then a similar reasoning applies: the only two independent sets of size $|V(T)|$ must contain either $u_r$ or $v_r$, and they uniquely extend to $I_{1,v}$ or $I_{1,u}$, respectively, by the induction hypothesis.

Since these are the only two ways to construct an independent set of size $|V(T)|$, the claim follows.  
\end{proof}


Consider a tree $T$ in the forest $T_k - D$, and let $r \in R_D$ be its root. Consider the independent set $I_T=I\cap~\bigcup_{t\in V(T)} X_t$. Since $I$ intersects all bags $X_t$ for $t\in V(T)$, it follows that $I_T$ is an independent set of $G_k[\bigcup_{t\in V(T)} X_t]$ of size $|V(T)|$. By Claim~\ref{claim:UniqueIS}, the graph $G_k[\bigcup_{t\in V(T)} X_t]$ has exactly two independent sets of size $|V(T)|$: one containing $u_r$, denoted by $I_{T,u}$, and the other containing $v_r$, denoted by $I_{T,v}$.

If $c_D(r) = 0$, then $I \cap X_r = {u_r}$, which implies $I_T = I_{T,u}$. Otherwise, if $c_D(r) = 1$, then $I \cap X_r = {v_r}$, leading to $I_T = I_{T,v}$. Thus, for each tree $T$ in the forest $T_k - D$, there is a unique choice for the independent set $I$ restricted to the bags corresponding to $T$. Applying this argument to all trees in the forest ensures that $I$ is uniquely determined.

It follows that the function $f$ is indeed a bijection. It remains to count the number of elements in $\mathcal{D}$. There are exactly $\binom{|V(T_k)|}{d}$ ways to choose a subset $D \subseteq V(T_k)$ of size $d$. Given such a subset $D$, we observe that the set $R_D$ has at most $2d+1$ elements. Indeed, there are at most $2d$ nodes of $T_k$ whose parent belongs to $D$, and additionally, the root of $T_k$ is included in $R_D$ whenever it does not belong to $D$. This results in at most $2^{2d+1}$ possible choices for functions in $\{0,1\}^{R_D}$.

Thus, the total number of pairs $(D, c_D)$ is at most $\binom{|V(T_k)|}{d}2^{2d+1}$ in total. Finally, we can bound $\binom{|V(T_k)|}{d}$ by $|V(T_k)|^d$ and use the fact that $\alpha(G_k) = |V(T_k)|$ to conclude the proof.
\end{proof}



\begin{theorem}
For any $t\geqslant 1$, there exist infinitely many graphs $G$ such that $\ta(G)=2t$ and for any $\lambda\geqslant 1$,
$$
\tau_{G,\lambda} \geqslant (\lambda n)^{ct\ln(n)} 
$$
where $n=|V(G)|$ and $c$ is a constant.
\end{theorem}

\begin{proof}
Consider the graph $H_{k,t}$ obtained by replacing each vertex $v\in V(G_k)$ with a set of vertices $Y_v$ inducing a disjoint union of $t$ cliques of size $2^{2k}$. For each edge $uv\in E(G_k)$, we add all possible edges between $Y_u$ and $Y_v$. For any subset $V'\subseteq V(H_{k,t})$, define $p(V') = \{u\in V(G_k) \mid Y_u\cap S\neq \emptyset\}$, and observe that if $V'$ is an independent set of $H_{k,t}$, $p(V')$ is an independent set of $G_k$. Let $I_{k,t}$ be a maximum independent set of $H_{k,t}$ such that $p(I_{k,t}) =I_k$. Notice that $|I_{k,t}|=t\alpha(G_k)$. We partition $\mathcal{I}(H_{k,t})$ as follows:
\begin{itemize}
\item $\Omega_S$: independent sets $S$ such that $p(S)$ is an independent set of $G_k$ of size exactly $s =  \alpha(G_k) - \lfloor c_1 k \rfloor$, where $c_1$ is the constant of Lemma~\ref{lemma:PropertiesGk}.(\ref{sublemma:SmallIS}).
\item $\Omega_I$: independent sets $I$ for which there exists a path of independent sets in $\mathcal{G}(H_{k,t})$ from $I_{k,t}$ to $I$ avoiding $\Omega_S$.
\item $\Omega_J$: the remaining independent sets.
\end{itemize}
By definition, $\Omega_S$ separates $\Omega_I$ and $\Omega_J$ in the reconfiguration graph $\mathcal{G}(H_{k,t})$. Indeed, suppose there exists a path from an independent set $I \in \Omega_I$ to an independent set $J \in \Omega_J$ that avoids $\Omega_S$. Then, by the definition of $\Omega_I$, there must also be a path from $I_{k,t}$ to $J$ that avoids $\Omega_S$. This implies that $J \in \Omega_I$, contradicting the assumption that $J \in \Omega_J$.

We denote by $\pi$ the distribution $\pi_{H_{k,t},\lambda}$. To bound the conductance, we first establish an upper bound on $\pi(\Omega_S)$ and a lower bound on $\min(\pi(\Omega_I), \pi(\Omega_J))$.

\begin{claim}\label{claim:LowerBoundOmegaS}
$\pi(\Omega_S) \leqslant 2^{\lfloor c_1k \rfloor (k+3)+1}((2^{2k}\lambda +1)^{t}-1)^s$.
\end{claim}

\begin{proof}
By Lemma~\ref{lemma:PropertiesGk}.(\ref{sublemma:CountIS}), there are at most $2^{2\lfloor c_1 k \rfloor+1} \alpha(G_k)^{\lfloor c_1 k \rfloor}$ independent sets of size $\alpha(G_k) - \lfloor c_1 k \rfloor$.  Let $J \in \mathcal{I}(G_k)$ be an independent set of size $s$. Observe that any independent set $I\in \mathcal{I}(H_{k,t})$ such that $p(I)=J$ is uniquely defined by the $|J|$ pairwise disjoint independent sets $\{I_v\}_{v\in J}$ such that $I_v\in \mathcal{I}(H_{k,t}[Y_v])\setminus \{\emptyset\}$. Thus, it follows that  
$$
\sum_{\substack{I \in \mathcal{I}(H_{k,t}) \\ p(I) = J }} \lambda^{|I|} = \prod_{v\in J} \left( \sum_{I\in \mathcal{I}(H_{k,t}[Y_v]) \setminus \{\emptyset\}} \lambda^{|I|} \right).
$$  
 For any $v \in V(G_k)$, the graph $H_{k,t}[Y_v]$ is a disjoint union of $t$ cliques of size $2^{2k}$. We obtain  
$$
\sum_{I\in \mathcal{I}(H_{k,t}[Y_v]) \setminus \{\emptyset\}} \lambda^{|I|} = (2^{2k} \lambda + 1)^t - 1
$$  
which gives the bound  
$$
\prod_{v\in J} \left( \sum_{I\in \mathcal{I}(H_{k,t}[Y_v])} \lambda^{|I|} \right) = ((2^{2k}\lambda+1)^t -1)^{s} 
$$  
Thus, we obtain  
\begin{align*}
    \pi(\Omega_S) &= \sum_{\substack{I \in \mathcal{I}(H_{k,t}) \\ |p(I)| = s} } \lambda^{|I|} \\
    &= \sum_{\substack{J \in \mathcal{I}(G_k) \\ |J|=s} } \sum_{\substack{I \in \mathcal{I}(H_{k,t}) \\ p(I) = J  }} \lambda^{|I|} \\[2em]
    &\leqslant 2^{2\lfloor c_1 k\rfloor +1} \alpha(G_k)^{\lfloor c_1k\rfloor} ((2^{2k}\lambda +1)^{t}-1)^s.
\end{align*}  
The final result follows by bounding $\alpha(G_k)$ by $2^{k+1}$.
\end{proof}

\begin{claim}
$\min(\pi(\Omega_I),\pi(\Omega_J)) \geqslant ((2^{2k}\lambda+1)^t -1)^{\alpha(G_k)}$.
\end{claim}

\begin{proof}
First, observe that $\Omega_I$ contains all independent sets $I\in \mathcal{I}(H_{k,t})$ such that $p(I) = I_k$. Using a similar argument as in the proof of Claim~\ref{claim:LowerBoundOmegaS}, we obtain  
$$
\pi(\Omega_I) \geqslant \sum_{\substack{I \in \mathcal{I}(H_{k,t}) \\ p(I) = I_k}} \lambda^{|I|} = ((2^{2k}\lambda+1)^t-1)^{\alpha(G_k)}.
$$

Next, we show that a similar bound holds for $\pi(\Omega_J)$. Specifically, we prove that $\Omega_J$ contains all independent sets $J\in \mathcal{I}(H_{k,t})$ such that $p(J) = J_k$.  

Assume for contradiction that there exists $J\in \Omega_I$ such that $p(J) = J_k$. Then, there must exist a path $W_0, W_1, \dots, W_p$ in $\mathcal{G}(H_{k,t})$ such that $W_i\in \Omega_I$ for all $0\leqslant i \leqslant p$ and $W_0=I_{k,t}$. We show that $p(W_0), p(W_1), \dots, p(W_p)$ forms a path from $I_k$ to $J_k$ in $\mathcal{G}(G_k)$.  Indeed, we have $p(W_0)= I_k$ and $p(W_p)=J_k$. Consider any step $0\leqslant i < p$ where $W_{i+1} = W_i\cup \{x\}$ for some vertex $x\in V(H_{k,t})$. Let $v\in V(G_k)$ be the unique vertex such that $x\in Y_v$. There are two cases:  
\begin{itemize}
\item If there exists a vertex $y\in W_i\cap Y_v$, then $p(W_{i+1})=p(W_i)$.  
\item If $W_i\cap Y_v = \emptyset$, then $p(W_{i+1}) = p(W_i)\cup \{v\}$.  
\end{itemize}
A similar argument holds when $W_{i+1} = W_i \setminus \{x\}$ for some vertex $x\in V(H_{k,t})$, ensuring that $|p(W_{i+1})\Delta p(W_i)|\leqslant 1$.  Since no index $0\leqslant i\leqslant p$ satisfies $|p(W_i)|=s$ (otherwise $W_i$ would belong to $\Omega_S$), this path from $I_k$ to $J_k$ in $\mathcal{G}(G_k)$ avoids all independent sets of size~$s$, contradicting Lemma~\ref{lemma:PropertiesGk}.(\ref{sublemma:SmallIS}).  Thus, we conclude that $\Omega_J$ contains all independent sets $J\in \mathcal{I}(H_{k,t})$ such that $p(J) = J_k$, implying  
$$
\pi(\Omega_J) \geqslant ((2^{2k}\lambda+1)^t -1)^{\alpha(G_k)}
$$
This completes the proof of the claim.
\end{proof}
Using Theorem~\ref{thm:LowerBoundConductance}, we obtain:  
\begin{align*}
     \tau_{H_{k,t},\lambda} &\geqslant \frac{\ln(2)}{4}\left( \frac{((2^{2k}\lambda+1)^t -1)^{\alpha(G_k)}}{2^{\lfloor c_1k \rfloor (k+3)+1}((2^{2k}\lambda +1)^{t}-1)^s}-2\right) \\[1em]
    &= \frac{\ln(2)}{4}\left( \frac{((2^{2k}\lambda+1)^t -1)^{\lfloor c_1k\rfloor}}{2^{\lfloor c_1k \rfloor(k+3)+1}}-2\right)
\end{align*}
Let $n = |V(H_{k,t})|$. We have  $n = t 2^{2k} (2^{k+2}-2) \leqslant t2^{3k+2}$, which implies 
$\log_2(n) \leqslant \log_2(t)+3k+2$. Rearranging, we obtain $k \geqslant \frac{1}{3}(\log_2(n)-\log_2(t) -2)$.

It is straightforward to observe that there exists a threshold $k_{t}$ such that for any $k\geqslant k_{t}$, the following inequalities hold:  
$$
\left\lbrace 
\begin{array}{l}
     k \geqslant \frac{\ln(2)}{4}\log_2(n),  \\[1em]
     ((2^{2k}\lambda+1)^t -1)^{\lfloor c_1k\rfloor} \geqslant 2^{\frac{4}{3}\lfloor c_1k\rfloor k t+3c_1k+3}\lambda^{\frac{2}{3}c_1kt}
\end{array}
\right.
$$
Thus, for any $k\geqslant k_{t}$, we obtain  
$$
\tau_{H_{k,t}, \lambda}\geqslant \lambda^{\frac{2}{3}c_1kt}2^{\lfloor c_1k\rfloor k\left( \frac{4}{3}t-1\right)} 
$$
and finally since $k\geqslant \frac{\log_2(n)}{4}$ and $\frac{4}{3}t-1 \geqslant \frac{t}{3}$ whenever $t\geqslant 1$, there exists a small enough constant $c>0$ such that 
$$
\tau_{H_{k,t}, \lambda} \geqslant (\lambda n)^{ct\ln n}
$$
\end{proof}


\section{Conclusion}

We showed that the mixing time of the Glauber dynamics for the hard-core model is subexponential on geometric intersection graphs. Additionally, we established tight parameterized mixing time bounds for this Markov chain, enabling a more fine-grained understanding of mixing times beyond the classical polynomial-versus-exponential dichotomy. 

In particular, for geometric intersection graphs, our results demonstrate that the Glauber dynamics is as efficient as exact algorithms for computing the partition function and activation probabilities of each vertex, while being significantly more practical to implement. Moreover, our approach does not require knowledge of the geometric representation of the graph. 

 We recall two major open questions and propose potential future directions:

\begin{itemize}
    \item For any $d\geqslant 3$, does the Glauber dynamics mix in time $2^{\Omega(n^{1-\frac{1}{d}})}$ on the $d$-dimensional grid with $n$ vertices? Such a result would require generalizing the work of Randall~\cite{randall2006slow} to higher dimensions.
    \item For any $\lambda > 1$, can the mixing time $\tau_{G,\lambda}$ on $n$-vertex graphs be bounded by a function of the form $n^{o(\tw(G))}$, or even by $f(\tw(G)) \cdot n^{O(1)}$, where $f$ is a computable function?

    \item On planar graphs, is it possible to combine the subexponential and parameterized approaches to achieve such a mixing time? Indeed, all the lower bounds we presented involve large complete bipartite induced subgraphs, which do not exist in geometric intersection graphs.
    \item Does there exist a chordal graph $G$ such that $\tau_{G,\lambda}=\Omega(n^{\ln n})$ for a large enough constant~$\lambda$?
\end{itemize}

