\section{Preliminaries on Markov chains}\label{appendix:Markov}

This section provides a brief overview of Markov chains and the canonical paths technique for analyzing mixing times. We use the notation of \cite{sinclair1992improved}, and we also refer to \cite{guruswami2016rapidly,levin2017markov,montenegro2006mathematical} for more details.

\paragraph*{Markov chains}

A finite Markov chain $\mathcal{M}$ is defined by a state space $\Omega$ and a transition matrix $P$ of dimension $|\Omega| \times |\Omega|$, where $P(x, y)$ represents the probability of transitioning from $x \in \Omega$ to $y \in \Omega$. A step of the Markov chain corresponds to a single such transition. A distribution $\pi$ on $\Omega$ is stationary if $\pi P = \pi$. In an \emph{ergodic} Markov chain, the stationary distribution $\pi$ is unique and represents the long-term behavior of the chain as $t \to \infty$. Given an initial distribution $\mu$, the distribution of the chain after $t$ steps is given by $\mu P^t$, and for an ergodic chain, we have $\mu P^t \to \pi$ as $t \to \infty$.

The \emph{mixing time} of a Markov chain is the number of steps required for the chain to become $\varepsilon$-close to its stationary distribution. Given two distributions $\mu$ and $\nu$ on $\Omega$, the \emph{total variation distance} $\Delta(\mu,\nu)$ is defined as:
$$
\Delta(\mu,\nu)= \frac{1}{2}\sum_{x\in \Omega} |\mu(x) - \nu(x)|
$$

Starting from a state $x \in \Omega$, let $\mu_x$ denote the probability distribution where $\mu_x(x) = 1$ and $\mu_x(y) = 0$ for all $y \in \Omega \setminus {x}$. For $\varepsilon \in (0,1)$, the mixing time $\tau_x(\varepsilon)$ is the smallest $t$ such that
$$
\Delta(\mu_x P^t, \pi) \leqslant \varepsilon
$$
The mixing time is closely linked to the spectral properties of the transition matrix. By standard linear algebra, whenever $\mathcal{M}$ is ergodic, $P$ has $N:=|\Omega|$ real eigenvalues satisfying $1=\lambda_0 \geqslant \lambda_1 \geqslant ... \geqslant \lambda_{N-1} \geqslant -1$. Let $\lambda_{\max}(\mathcal{M}) = \max(\lambda_1, |\lambda_{N-1}|)$.

\begin{proposition}[\cite{sinclair1992improved}]\label{prop:BoundMixingTime}
Let $\varepsilon \in (0,1)$. The mixing time satisfies the following bounds:
\begin{enumerate}
    \item For any state $x \in \Omega$, $\tau_x(\varepsilon) \leqslant (1-\lambda_{\max})^{-1}\left( \ln\left( \frac{1}{\pi(x)}\right) +\ln\left( \frac{1}{\varepsilon}\right)\right)$
    \item $\max_{x\in \Omega} \tau_{x}(\varepsilon) \geqslant \frac{1}{2} \lambda_{\max} (1-\lambda_{\max})^{-1} \ln\left(\frac{1}{2\varepsilon}\right)$
\end{enumerate}
\end{proposition}

In the following, we assume that $\lambda_{\max} = \lambda_1$. While this is not always true, it holds in particular for Glauber dynamics and, more generally, for any heat-bath Markov chain~\cite{dyer2014structure}.

\paragraph*{Conductance}

In combinatorics, it has long been known that the second-largest eigenvalue of the adjacency matrix of a graph is closely related to its \emph{expansion}, a structural property of the graph. The conductance of $\mathcal{M}$ is defined as the edge expansion of the underlying transition graph:
\begin{equation}\label{eq:DefConductanceMarkov}
\Phi(\mathcal{M}) = \min_{\substack{S\subseteq \Omega \ 0\leqslant \pi(S)\leqslant 1/2}} \frac{Q(S,\overline{S})}{\pi(S)},
\end{equation}
where $\pi(S) = \sum_{x\in \Omega} \pi(x)$ and $Q(S,\overline{S}) = \sum_{x\in S, y\notin S} \pi(x)P(x,y)$. Note that $Q(S,\overline{S}) = Q(\overline{S},S)$ since for any $(x,y) \in \Omega^2$, we have $\pi(x)P(x,y) = \pi(y)P(y,x)$.

\begin{theorem}[\cite{sinclair1992improved}]\label{thm:ConductanceSpectrum}
Given an ergodic Markov chain $\mathcal{M}$ with second eigenvalue $\lambda_1$ and conductance $\Phi$, the following inequality holds :
$$
1-2\Phi \leqslant \lambda_1 \leqslant 1-\frac{\Phi^2}{2}
$$
\end{theorem}

The conductance is the main tool to prove lower bound on the mixing time of a Markov chain. One of the simplest methods to bound the conductance, introduced by Randall~\cite{randall2006slow}, involves partitioning the state space $\Omega$ into three subsets $(\Omega_S, \Omega_1, \Omega_2)$ such that $\Omega_S$ \emph{separates} $\Omega_1$ and $\Omega_2$. This means that for any pair of states $(x, y) \in \Omega_1 \times \Omega_2$ and any path $\gamma_{x,y} = (x = z_0, z_1, \ldots, z_\ell = y)$ satisfying $P(z_i, z_{i+1}) > 0$ for all $i$, there exists at least one intermediate state $z_i$ such that $z_i \in \Omega_S$. For the sake of completeness, we now formally state and prove the following theorem.

\begin{theorem}
Let $\mathcal{M}$ be an ergodic Markov chain such that $\lambda_{\max}(\mathcal{M})=\lambda_1(\mathcal{M})$, and let $(\Omega_S, \Omega_1,\Omega_2)$ be a partition of the state space $\Omega$ of $\mathcal{M}$ such that $\Omega_S$ separates $\Omega_1$ and $\Omega_2$. Thus, for any $\varepsilon\in (0,1)$, 
$$
\max_{x\in \Omega}\tau_x(\varepsilon) \geqslant \frac{1}{4}\left(\frac{\pi(\Omega_1)}{\pi(\Omega_S)}-2\right)\ln\left(\frac{1}{2\varepsilon}\right)
$$
\end{theorem}
\begin{proof}
Without loss of generality, we assume that $\pi(\Omega_1)\leqslant \pi(\Omega_2)$, and thus $\pi(\Omega_1)\leqslant 1/2$. By Equation~\ref{eq:DefConductanceMarkov} with $S = \Omega_1$ or $S=\Omega_2$ such that $\pi(S)$ is minimum,  we obtain that 
    $$
    \Phi \leqslant \frac{Q(\Omega_1, \Omega_S\cup \Omega_2)}{\pi(\Omega_1)} = \frac{Q(\Omega_1,\Omega_S)}{\pi(\Omega_1)}
    $$
    where the last equality holds since for any $(x,y)\in \Omega_1\times \Omega_2$, $P(x,y)=0$. Finally, we have 
    $$
    Q(\Omega_S,\Omega_1) =\sum_{(x,y)\in \Omega_S\times \Omega_1} \pi(x) P(x,y) = \sum_{x\in \Omega_S} \pi(x) \underbrace{\left( \sum_{y\in \Omega_1}P(x,y)\right)}_{\leqslant 1} \leqslant \pi(\Omega_S)
    $$
    It follows that $\Phi \leqslant \frac{\pi(\Omega_S)}{\pi(\Omega_1)}$. By Theorem~\ref{thm:ConductanceSpectrum}, we have 
    $$
    \lambda_1 \geqslant 1-2\Phi \geqslant 1-2 \frac{\pi(\Omega_S)}{\pi(\Omega_1)}
    $$
    Using Proposition~\ref{prop:BoundMixingTime}, we obtain 
    $$
        \max_{x\in \Omega}\tau_x(\varepsilon) \geqslant \frac{1}{2}\frac{\lambda_1}{1-\lambda_1}\ln\left(\frac{1}{2\varepsilon}\right)
        \geqslant \frac{1}{4}\left(\frac{\pi(\Omega_1)}{\pi(\Omega_S)}-2\right)\ln\left(\frac{1}{2\varepsilon}\right)
    $$
\end{proof}
\paragraph*{Canonical paths}

The \emph{canonical paths} technique provides a powerful method for upper bounding the mixing time. For each pair of states $x, y \in \Omega$, fix a specific path $\gamma_{x,y} = (x = z_0, z_1, \ldots, z_\ell = y)$ such that $(z_i, z_{i+1})$ are adjacent states, i.e., $P(z_i, z_{i+1}) > 0$. The path $\gamma_{x,y}$ is called the canonical path from $x$ to $y$. Let $\Gamma := \{\gamma_{x,y} \mid x, y \in \Omega\}$ be the set of all fixed canonical paths. The \emph{congestion} through a transition $e = (u, v)$, where $P(u, v) > 0$, is defined as
\begin{center}
\begin{equation}\label{CongestionMarkov}
\rho(\Gamma, e) := \frac{1}{\pi(u)P(u, v)} \sum_{\substack{x, y \in \Omega \\ \gamma_{x,y} \text{ uses } e}} \pi(x) \pi(y) |\gamma_{x,y}|
\end{equation}
\end{center}
where $|\gamma_{x,y}|$ is the length of the path $\gamma_{x,y}$. The overall congestion of the paths $\Gamma$ is then
$$
\rho(\Gamma) := \max_{e = (u,v) : P(u,v) > 0} \rho(\Gamma, e).
$$
The heart of this method is the following, 
\begin{theorem}[\cite{sinclair1992improved}]\label{thm:BoundSpectrumPaths}
Given an ergodic Markov chain $\mathcal{M}$ with second eigenvalue $\lambda_1$ and any choice of canonical paths $\Gamma$, the following inequality holds :
$$
\lambda_1 \leqslant 1-\frac{1}{\rho(\Gamma)}
$$
\end{theorem}

Combining Proposition~\ref{prop:BoundMixingTime} and Theorem~\ref{thm:BoundSpectrumPaths}, we obtain directly the following.

\begin{theorem}
Let $\mathcal{M}$ be an ergodic Markov chain such that $\lambda_{\max}(\mathcal{M})=\lambda_1(\mathcal{M})$, and let $\Gamma$ be a set of canonical paths. For any $\varepsilon \in (0,1)$ and $x\in \Omega$, 
$$
\tau_x(\varepsilon) \leqslant \rho(\Gamma) \left(\ln\left(\frac{1}{\pi(x)}\right) + \ln\left(\frac{1}{\varepsilon}\right)\right)
$$
\end{theorem}













