\section{Main Results and Stability Analysis}\label{MR}


Consider the dynamics of the multiagent network given in (\ref{node_dynamics}) and (\ref{control_signal}).
One can write (\ref{node_dynamics}) as
\vspace{0cm}
\begin{eqnarray}
\dot{x}_i(t)\hspace{-0.3cm}&=&\hspace{-0.3cm}-\sum_{j\in \mathcal{N}_i} a_{ij}(t)\bigg((x_i(t)-x_j(t)) + k_i (x_i(t)-c(t))\bigg) \nonumber \\ && \hspace{-0.3cm}-\sum_{j\in \mathcal{N}_i} a_{ij}(t)\bigg((x_{\rom{s}i}\hspace{-0.01cm}(t) -x_i(t)) - (x_{\rom{s}j}\hspace{-0.01cm}(t)-x_j(t))\bigg) \nonumber \\ && \hspace{-0.3cm}-k_i \sum_{j\in \mathcal{N}_i} a_{ij}(t)\left(x_{\rom{s}i}\hspace{-0.01cm}(t)-x_i(t)\right), \ x_{i}(0)=x_{i0}.
\label{state_dynamics_with_control_signal}   
\end{eqnarray}
Now, we define the error 
\begin{eqnarray}
    e_i(t) \triangleq x_i(t)-c(t), \quad \forall  i\in \left\{1,\ldots,n\right\}.
    \label{error_definition}
\end{eqnarray}
The time derivative of the error can be given by 
\vspace{0cm}
\begin{eqnarray}
\dot{e}_i(t)\hspace{-0.2cm}&=&\hspace{-0.2cm}-\sum_{j\in \mathcal{N}_i} a_{ij}(t)\bigg(e_i(t)-e_j(t) + k_i e_i(t)\bigg) \nonumber \\ && \hspace{-0.2cm}+\sum_{j\in \mathcal{N}_i} a_{ij}(t)\bigg(\tilde{x}_i(t) - \tilde{x}_j(t)+k_i\tilde{x}_i(t)\bigg) \nonumber \\ && \hspace{-0.2cm}-\dot{c}(t), \quad e_i(0)=e_{i0},
\label{node_base_error_dynamics}   
\end{eqnarray}
where $\tilde{x}_i(t)\triangleq (x_i(t)-x_{\rom{s}i}\hspace{-0.01cm}(t))$.
Then, one can compactly write (\ref{node_base_error_dynamics}) as
\begin{eqnarray}
    \dot{e}(t)\hspace{-0.2cm} &=&\hspace{-0.2cm} -F(\mathcal{G}(t))e(t)+F(\mathcal{G}(t))\tilde{x}(t)-\textbf{1}_n\dot{c}(t), \nonumber \\  && \hspace{4cm} e(0)=e_0.
    \label{error_dynamics}
\end{eqnarray}
Here, $F(\mathcal{G}(t)) \hspace{-0.06cm} \triangleq \hspace{-0.06cm}  \mathcal{L}(t)+K\mathcal{D}(t)$, where $K\hspace{-0.02cm}\triangleq\hspace{-0.02cm}\text{diag}(k_1\hspace{-0.01cm},\ldots,\hspace{-0.01cm}k_n)$.
Also, $e(t) \hspace{-0.1cm} \triangleq \hspace{-0.1cm} [e_1\hspace{-0.03cm}(t),\ldots,e_n\hspace{-0.03cm}(t)]\mT$ and $\tilde{x}(t) \hspace{-0.1cm}\triangleq \hspace{-0.1cm}  [\tilde{x}_1\hspace{-0.03cm}(t),\ldots,\tilde{x}_n\hspace{-0.03cm}(t)]\mT$\hspace{-0.07cm}.


