\begin{abstract}
	We show that the big Ramsey degree of the Boolean algebra with 3 atoms within the countable atomless Boolean algebra is infinite.
\end{abstract}

\maketitle

\section{Introduction}
In this note we prove:
\begin{theorem}
	\label{thm:main}
	Let $\str{B}$ be the countable atomless Boolean algebra. Then there exists a coloring of the 3-atom subalgebras of $\str{B}$ with infinitely many colors such that
	every countable atomless subalgebra of $\str{B}$ contains a 3-atom subalgebra of every color.
\end{theorem}
This 
is motivated by the following problem formulated by Kechris, Pestov and Todorcevic in their seminal paper connecting structural Ramsey theory and topological dynamics~\cite{Kechris2005} (and is also explicitely asked by Ma\v{s}ulovi\'c in \cite{Masulovic2023}).
\begin{problem}[Kechris--Pestov--Todorcevic 2005~\cite{Kechris2005}, Problem 11.2]
	\label{prob:1}
	In each of the following cases find the topological dynamics analog of a corresponding infinite Ramsey-theoretic result.
	\begin{enumerate}[label=(\roman*)]
	  \item \label{p1} The rationals with the usual ordering.
	  \item \label{p2} The random ordered graph.
	  \item \label{p3} The random $\str{K}_n$-free ordered graph, ($n=3,4, \ldots$).
	  \item \label{p4} The random $\mathcal{A}$-free ordered hypergraph of type $L_0$, for any set $\mathcal A$ of irreducible finite hypergraphs of type $L_0$.
	  \item \label{p5} The ordered rational Urysohn space.
	  \item \label{p6} The $\aleph_0$-dimensional vector space over a finite field with the canonical ordering.
	  \item \label{p7} The countable atomless Boolean algebra with the canonical ordering
	\end{enumerate}
\end{problem}
At the time~\cite{Kechris2005} was published, even the corresponding infinite Ramsey-theoretic results (let alone the topological dynamics analogs) were only fully understood for~\ref{p1} and~\ref{p6}. A Ramsey theorem for \ref{p6} was given by Carlson~\cite{carlson1987infinitary} (see~\cite[Chapter 5.7]{todorcevic2010introduction}), and we will discuss case~\ref{p1} below, after introducing some notions of structural Ramsey theory.

Given structures $\str{A}$ and $\str{B}$, we denote by $\Emb(\str A,\str B)$ the set of
all embeddings from $\str{A}$ to $\str{B}$.
If $r< t\in \mathbb{N}$, we write $\str{B}\longrightarrow (\str{B})^\str{A}_{r,t}$ as a shortcut for the following statement:
\begin{quote}
	For every $r$-colouring $\chi\colon\Emb(\str{A},\str{B})\to r$, there exists an embedding
	$f\in \Emb(\str{B},\str{B})$ such that $|\{\chi(f\circ e):e\in \Emb(\str{A},\str{B})\}|\leq t$.
\end{quote}
For a countably infinite structure $\str{B}$ and its finite substructure
$\str{A}$, the \emph{big Ramsey degree} of $\str{A}$ in $\str{B}$ is the least
number $\ell\in \mathbb N$, if it exists, such that $\str{B}\longrightarrow
(\str{B})^\str{A}_{r,\ell}$ for every $r\in \mathbb N$.
We say that \emph{the big
Ramsey degrees of $\str{B}$ are finite} if for every finite substructure
$\str{A}$ of $\str{B}$ the big Ramsey degree of $\str{A}$ in $\str{B}$ exists. 

We note the following two ways that the big Ramsey degree of $\str{A}$ in $\str{B}$ can fail to exist. Call a coloring $\chi$ of $\Emb(\str{A}, \str{B})$ \emph{unavoidable} if for every $f\in \Emb(\str{B}, \str{B})$, we have $\{\chi(f\circ e): e\in \Emb(\str{A}, \str{B})\} = \mathrm{Im}(\chi)$.
\begin{enumerate}
    \item 
    For every $r\in \mathbb{N}$, there is an unavoidable coloring $\chi\colon \Emb(\str{A}, \str{B})\to r$.
    \item 
    There is an unavoidable coloring $\chi\colon \Emb(\str{A}, \str{B})\to \mathbb{N}$.
\end{enumerate}
Clearly $(2)$ implies $(1)$. We do not know of any examples where $(1)$ holds and $(2)$ fails. Indeed, letting $\str{B}_3$ and $\str{B}$ be the $3$-atom and countable atomless Boolean algebras, respectively, then Theorem~\ref{thm:main} can be restated as asserting that there is an unavoidable coloring $\chi: \Emb(\str{B}_3, \str{B})\to \mathbb{N}$. 

Refining an unpublished upper-bound theorem of Laver, Devlin gave the following precise infinite Ramsey-theoretic result
for the order of rationals.
\begin{theorem}[Devlin, 1979~\cite{devlin1979}]
	\label{thm:devlin}
	Denote the order of rationals by $(\mathbb Q,<)$.
	For every finite linear order $\str{A}$, the big Ramsey degree of $\str{A}$ in $(\mathbb Q,<)$ is 
	precisely the $|A|$-th \emph{odd tangent number}: the $(2|A|-1)$-th derivative of $\tan(z)$ evaluated at $0$.
\end{theorem}
Problem~\ref{prob:1}, in particular for the unordered versions of each class therein, motivated research on similar characterisations of big
Ramsey degrees of various structures.  For a given countably infinite structure $\str{K}$, the problem can be attacked in three steps.
\begin{enumerate}
	\item Prove a structural Ramsey theorem giving upper bounds on big Ramsey degrees of finite substructures of $\str{K}$.
	\item Fully characterise the big Ramsey degrees of $\str{K}$ by proving a lower bound theorem 
		and refining the upper bound theorem so that they match.
	\item Give an interpretation of these results in the context of topological dynamics.
\end{enumerate}

Devlin's theorem thus completes the first two steps for the order of rationals, case~\ref{p1}. Analogous results for case~\ref{p2}
appeared shortly after publication of~\cite{Kechris2005}.
The upper bound on big Ramsey degrees of the countable random (or Rado) graph can be
given by a natural adaptation of Laver's proof, which is today stated as an application of the Milliken tree theorem, see~\cite[Chapter 6]{todorcevic2010introduction} and~\cite{Sauer2006}.
A precise characterisation of big Ramsey degrees of the random graph was given in 2006 by Laflamme, Sauer, and Vuksanovic~\cite{Laflamme2006}.

%Motivated by the above results, which solve the first two steps for the order of
%rationals and the random graph,
Zucker~\cite{zucker2017} introduced
the notion of a \emph{big Ramsey structure}, a strengthening of having finite big Ramsey degrees which gives rise to a dynamical object called the \emph{universal completion flow}, giving
a solution to the last step of the attack on Problem~\ref{prob:1} above for the first three cases; see also the recent survey~\cite{hubicka2024survey}. However, it remains unclear what the correct analog of big Ramsey structure should be when big Ramsey degrees are infinite, and if the universal completion flow exists for every topological group.

For over a decade, further progress on Problem~\ref{prob:1} has been blocked by a lack of techniques for giving upper bounds on big Ramsey degrees
for structures with non-trivial forbidden configurations.
Recent rapid progress started by upper bounds on big Ramsey degrees of
the ``random'' (i.e. universal and homogeneous) triangle-free graph given
by Dobrinen~\cite{dobrinen2017universal}, see also~\cite{Hubicka2020CS} for a shorter proof.
Dobrinen subsequently extended the method to $\str{K}_k$-free
graphs~\cite{dobrinen2019ramsey}. Zucker further generalized and simplified the
proof for finitely constrained free amalgamation classes in finite binary
languages~\cite{zucker2020}. (We remark that the assumption about finiteness of language is necessary~\cite{Omegalabelled2025} and there are known examples of infinitely constrained caes without finite big Ramsey degrees~\cite{sauer2003canonical}.) The precise characterisation of big Ramsey degrees of structures covered by Zucker's result was given by Balko, Chodounsk\' y,
Dobrinen, Hubi\v cka, Kone\v cn\'y, Vena and Zucker~\cite{Balko2021exact}, yielding big Ramsey structures for case~\ref{p3} (see also~\cite{Vodsedalek2025}).  These results are based on the new technique of coding trees with an upper bound theorem proved using the language of set-theoretic forcing, see Dobrinen's ICM survey~\cite{dobrinen2020forcing}.
More recently, a new method extending the Carlson--Simpson theorem has been introduced~\cite{Hubicka2020CS,Balko2023Sucessor} which generalizes to
additional structures including partial orders and metric spaces.

Work on big Ramsey degrees of structures in languages with relations of arity 3 or more, considered in case \ref{p4}, introduces new challenges.
An upper bound theorem for the random 3-uniform hypergraph (i.e.\ the case when $\mathcal A=\emptyset$)
was proved by Balko, Chodounsk{\' y}, Hubi{\v c}ka, Kone{\v c}n{\' y} and Vena~\cite{Hubickabigramsey}, and 
this construction was subsequently generalized to structures in arbitrary relational languages and certain, very simple, forbidden configurations by Braunfeld, Chodounsk{\'y}, de Rancourt, Hubi{\v{c}}ka, Kawach and Kone{\v{c}}n{\'y}~\cite{braunfeld2023big}.
So far, big Ramsey degrees and big Ramsey structures have not been fully described for case~\ref{p4}.

Case~\ref{p5} of Problem~\ref{prob:1} presents a different complication.
It is easy to show that the rational Urysohn space has infinite big Ramsey degrees of vertices~\cite{hubicka2024survey}. However, an approximate (metric) form of a
vertex coloring theorem, known as the \emph{oscillation stability}, can be formulated and was proved for the Urysohn sphere. A combinatorial strategy of the proof
was given by Lopez-Abad and Nguyen Van Th{\'e}~\cite{lopez2008oscillation}, reducing the problem to a vertex coloring big Ramsey problem for Urysohn spheres with finitely
many distances, which was proved by Sauer and Nguyen Van Th{\'e}~\cite{NVT2009b} (see also a recent easier proof~\cite{bice2025oscillation}).
Work on generalizing big Ramsey degrees to the metric setting is currently in progress, see announcement~\cite{Bice2023}.


\medskip

Individual cases of Problem~\ref{prob:1} are motivated by the corresponding finitary
Ramsey-theoretic results. Case~\ref{p1} corresponds to the Ramsey theorem.
Case \ref{p2} to the unrestricted form of Ne\v set\v ril--R\"odl theorem~\cite{Nevsetvril1977}
(also independently proved by Abramson--Harrington~\cite{Abramson1978}). Cases~\ref{p3} and~\ref{p4}
correspond to the full strength of the Ne\v set\v ril--R\"odl theorem, and case~\ref{p5} to a result
of Ne\v set\v ril showing that ordered metric spaces form a Ramsey class~\cite{Nevsetvril2007}.
Case~\ref{p6} corresponds to a special case of the Graham--Leeb--Rothschild theorem~\cite{Graham1972},
and finally case~\ref{p7} corresponds to the dual Ramsey theorem (a special case of the Graham--Rothschild theorem~\cite{Graham1971}). See e.g.~\cite{hubicka2025twenty} for a discussion
of finite structural Ramsey theory. 

In this setting, it is natural to ask about big Ramsey degrees of the countable atomless Boolean algebra
and expect a ``dual form'' of Theorem~\ref{thm:devlin}.
It thus may come as a surprise that by Theorem~\ref{thm:main} the big Ramsey degree of the
3-atom Boolean algebra is infinite.
This means, that the case \ref{p7} differs significantly from cases~\ref{p1},
\ref{p2}, \ref{p3} as well as the existing partial results on  case \ref{p4}
(it is possible that in case \ref{p4} 
 big Ramsey degrees are not finite for many choices of $\mathcal A$~\cite{sauer2003canonical,typeamalg}). 
There are also significant differences to case~\ref{p5}.
Metric big Ramsey degrees of the Urysohn sphere can be seen as a limit of
approximations by Urysohn spheres with finitely many distances 
each having finite big Ramsey degrees~\cite{Hubicka2020CS,balko2021big}.
This is in contrast with countable atomless Boolean algebra, which has
no natural approximations.
Finally, it is rather curious that while the finitary Ramsey-theoretic variants of cases~\ref{p6} and~\ref{p7} are closely connected (they follow by basically the same proof), this is completely different in the infinite setting where the Ramsey theorem for case~\ref{p6} has been proved by Carlson~\cite{carlson1987infinitary} (see~\cite[Chapter 5.7]{todorcevic2010introduction}) and it says that the big Ramsey degrees of finite-dimensional subspaces are finite, which is in contrast with Theorem~\ref{thm:main}.

Consequently, we believe that solving case~\ref{p7} will need
development of novel tools.  We expect that the problem can still be addressed in
the following three steps.
\begin{problem}
	Determine the big Ramsey degree of the 2-atom Boolean algebra in the countable atomless Boolean algebra.
\end{problem}
\begin{problem}
	\label{probopt}
	Prove the corresponding infinite Ramsey-theoretic result for the countable atomless Boolean algebra and
	show its optimality even in the case where the big Ramsey degrees are infinite.
\end{problem}
\begin{problem}
	Generalize the notion of big Ramsey structure to this new setting where big Ramsey degrees are infinite
	and find its topological dynamics analogue.
\end{problem}
We remark that the solution to Problem~\ref{probopt} may take some inspiration from~\cite{Evans2}.

\section{An explicit representation of the countable atomless Boolean algebra}

We use the standard set-theoretic notation. In particular, we identify a non-negative integer $n$ with the set $\{0,..., n-1\}$ and $\omega$ with the set of non-negative integers.

Put $X = [0, 1)\cap \mathbb{Q}$, and let $\prec$ denote the usual linear order on $X$. The \emph{interval algebra} of $X$ is the Boolean subalgebra of $\mathcal{P}(X)$ consisting of finite unions of half-open intervals, see \cite{BAHandbook}. More precisely, let us call $a\subseteq X$ \emph{good} if there exists $n< \omega$ and an increasing function $\seq_a\colon 2n\to X\cup \{1\}$ such that given $x\in X$, we have $x\in a$ if and only if for some $i< n$, we have $\seq_a(2i)\preceq x\prec \seq_a(2i+1)$. Note in particular that $\min(a) = \seq_a(0)$ for good $a\subseteq X$.
Denote by $\str{B}$ set of all good subsets of $X$ viewed as a Boolean subalgebra of $\mathcal{P}(X)$.
\iffalse
$=(\ell_0,\allowbreak u_0,\allowbreak \ell_1,\allowbreak u_1,\allowbreak \ell_2,\allowbreak u_2,\allowbreak \ldots\allowbreak,  \ell_{n-1},\allowbreak u_{n-1})$ from $X\cup \{1\}$ with
$\ell_0\prec u_0\prec \ell_1\prec u_1\prec \ell_2\prec u_2\prec \cdots\prec \ell_{n-1}\prec u_{n-1}$ such that given $x\in X$, we have $x\in a$ if and only if there exists $i<n$ satisfying $\ell_i\preceq x\prec u_i$. 
\fi
\begin{observation}
	$\str B$ is a countable atomless Boolean algebra.
\end{observation}
\begin{proof}
    The set $\str B$ is closed under unions and intersections, the complement of every good set is good, and both $\emptyset$ and $X$ are good. So $\str B$ is a sub-algebra of $\mathcal{P}(X)$.

    Since good subsets correspond to finite sequences of rationals, $\str B$ is countable. 
    For every $a\in \str B$ there is a nonempty good set $b \subsetneq a$, thus $\str B$ is the up-to-isomorphism unique countable atomless Boolean algebra. 
