\end{proof}



\section{Oscillation}

Given the representation $\str B$ of the countable atomless Boolean algebra, we are now ready to
introduce the coloring function which features in Theorem~\ref{thm:main}. 
We will first assign a finite set of natural numbers $\int(a)$ to each element $a$ of $\str B$, 
and the coloring function will be defined on pairs $(a, b)$ of elements of $\str B$ as the so-called oscillation
of their sequences $\int(a)$ and $\int(b)$. 
To color the 3-atom subalgebras of $\str B$ we will use the oscillation coloring applied to their atoms. 
The idea of utilizing the oscillation coloring is inspired by a similar result 
on infinite big Ramsey degrees of the pseudotree 
(the universal countable homogeneous meet-tree) 
by Chodounský, Eskew, and Weinert~\cite{ChEW_pseudotree}, 
which was in turn inspired by a certain argument about the product of Mathias posets, see~\cite[Observation~7]{BrendleLuz}.
The concept of oscillations originates in the work of Todorcevic~\cite{Todorcevic_Roscillate}.


Fix a finite-to-1 function $e\colon X\cup \{1\}\to \omega$. 
%\subsection{Yesterday's (shorter) proof}
%Assume that $\min X$ and $\max X$ are the only elements of $X$ satisfying $e(\min X)=e(\max X)=0$.
Given $a\in \str{B}$, let
\[\int(a)=\{e(u):u\in \mathrm{Im}(\seq_a)\}.\]
 be the set of ``interesting'' numbers associated with $a$.
\begin{definition}
	Given $a_0,a_1\in \str{B}$ and $i < \omega$ we say that $a_0$ and $a_1$ \emph{oscillate} at $i$ if there exists $k\in \{0,1\}$ such that:
    \begin{itemize}
        \item 
        $i\in \int(a_k)\setminus\int(a_{1-k})$,
        \item 
        if $i\cap (\int(a_k)\mathop{\Delta} \int(a_{1-k})) \neq \emptyset$ ($\Delta$ here denotes symmetric difference) and $j = \max\{i\cap (\int(a_k)\mathop{\Delta} \int(a_{1-1}))\}$, then $j\in \int(a_{1-k})\setminus \int(a_k)$. 
    \end{itemize}
	We let

    \iffalse
    and for every $j\in \int(a_k)\setminus\int(a_{1-k})$ satisfying $j<i$ there exists $j'\in \int(a_{1-k})\setminus \int(a_k)$ such that $j<j'<i$.
    \fi
	\[\osc(a_0,a_1) = \left|\left\{i \in \omega : \text{$a_0$ and $a_1$ oscillate at $i$} \right\}\right|.\]
	%We let \[O(a,b) = \left\{i \in \omega : \text{$a$ and $b$ oscillate at index $i$} \right\}\]
        %and 
            %\[\osc(a,b)=\left|O(a,b)\right|.\]
\end{definition}
Notice that the function is symmetric, i.e.\ $\osc(a, b) = \osc(b, a)$ for all $a,b \in \str{B}$.
We prove Theorem~\ref{thm:main} in the following more technical form.
\begin{theorem}
	\label{thm:osc}
	For every countable atomless subalgebra $\str{C}$ of $\str{B}$ and every $n>0$ there exist $a,b\in \str{C}$ such that $a\cap b = \emptyset$, $0 \notin a \cup b$, and $\osc(a,b) = n$.
	%there exists $n_0$ such that for every $n>n_0$ there exists $a,b\in C$ satisfying $\osc(a,b)=n$.
\end{theorem}


\begin{proof}[Proof of Theorem~\ref{thm:main} using Theorem~\ref{thm:osc}]
    Let $\str A$ be the Boolean algebra with 3 atoms. 
    Define a coloring $\chi\colon \Emb(\str A, \str B) \to \omega$ as follows: 
    Given $f \in \Emb(\str A, \str B)$, let $a, b, c \in \str B$ be the images of the three atoms of $\str A$ under $f$ such that $\min(a) \prec \min(b) \prec \min(c)$, and put $\chi(f) = \osc(b,c)$.

    We claim that every countable atomless subalgebra $\str C$ of $\str{B}$ touches every color. 
    Indeed, fix  any $n \in \omega$ and use Theorem~\ref{thm:osc} to obtain $b,c\in \str{C}$ such that $b\cap c=\emptyset$, $\min X\notin b\cup c$ and $\osc(b,c) =n$. Let $\str D$ be the subalgebra of $\str C$ generated by $b$ and $c$. It is easy to see that $\str D$ has three atoms and that for every isomorphism $f\colon\str A\to \str D$ we have that $\chi(f) = n$.
\end{proof}
We now turn to the proof of Theorem~\ref{thm:osc}.
\begin{lemma}
	\label{lem:oscN}
	Let $\str{C}$ be a countable atomless Boolean subalgebra of $\str{B}$. Then for every non-empty $a\in \str{C}$ and $n\in \omega$ there exists $b\in \str{C}$ such that $b\subseteq a$ and $\min(\int(b))>n$.
\end{lemma}
\begin{proof}
	Fix $\str{C}$, $a$ and $n$.
	Put $L=\{x\in X:e(x)\leq n\}$.
	Because $\str{C}$ is atomless and $L$ finite, one can choose a set $A$ of $2|L|+1$ pairwise disjoint elements of $\str{C}$ such that every $a'\in A$ satisfies $a'\subseteq a$.
	Given $x\in L$ and $a'\in A$ we say that $x$ \emph{blocks} $a'$ if $x\in \mathrm{Im}(\seq_{a'})$.
	Notice that every $x\in L$ blocks at most two elements of $A$.
	Consequently, there exists $b\in A$ such that $\mathrm{Im}(\seq_b)\cap L=\emptyset$ and therefore $\min(\int(b))>n$.
\end{proof}
\begin{lemma}
	\label{lem:oscP1}
	Let $\str{C}$ be a countable atomless Boolean subalgebra of $\str{B}$.
	For every non-empty $a,b\in \str{C}$ there exsists $a',b'\in \str{C}$ such that $a'\subseteq a$, $b'\subseteq b$ and $\osc(a',b')=\osc(a,b)+1$.
\end{lemma}
\begin{proof}
	Fix $\str{C}$, $a$ and $b$.  Apply Lemma \ref{lem:oscN} to obtain $c\in \str{C}$ satisfying $c\subseteq a$ and $\min(\int(c))>\max(\int(b)\cup \int(a))$.
	Put $a'=a\setminus c$. Since $\int(a)\cup \int(c)= \int(a')$ we have either $\osc(a',b)=\osc(a,b)$ or $\osc(a',b)=\osc(a,b)+1$. In the second
	case we are done.

	If $\osc(a',b)=\osc(a,b)$ then apply Lemma \ref{lem:oscN} to obtain $d\in \str{C}$ satisfying $d\subseteq b$ and $\min(\int(d))>\max(\int(a'))$. Put $b' = b\setminus d$.
	We have $\osc(a',b')=osc(a',b)+1=\osc(a,b)+1$.
\end{proof}
\begin{proof}[Proof of Theorem~\ref{thm:osc}]
	Fix an arbitrary countable atomless subalgebra $\str{C}$ of $\str{B}$.
	Let $a$ and $b$ be arbitrary disjoint elements of $\str{C}$ such that $0\notin a\cup b$.
	By Lemma~\ref{lem:oscN}, obtain $b'\in \str{C}$ such that $b'\subseteq b$ and $\min(\int(b'))>\max(\int(a))$.
	We have $\osc(a,b')=1$.
	%By application of Lemma~\ref{lem:osc0} and $\ref{lem:oscP1}$ we obtain $a,b\in \str{C}$ disjoint and non-empty such that $\osc(a,b)=1$.
	By a repeated application of Lemma~\ref{lem:oscP1}, we can then obtain a pair of disjoint elements of $\str{C}$ with any given oscillation.
\end{proof}


