\begin{theorem}[Powers, Reznick, from Fekete, \cite{powers2000polynomials}] 
\label{thm:fekete}
Let $p \in \mathbb{P}_{D,d}$ be a polynomial of degree $d$ positive on $[-1,1]$. Then,
\begin{equation}
	p(x) = (f(x))^2 + (1-x^2) \, (g(x))^2
\end{equation}
for some polynomials $f(x)$ and $g(x)$ of degree at most $d$ and $d-1$ respectively.\\
\end{theorem}

\begin{theorem}[Riesz extension theorem, \cite{}] 
\label{thm:rieszextension}
Let $E$ be a real vector space, $F\subset E$ be a subspace and $K \subset E$ a convex cone. Assume further that: $E = K+F$. Let $\phi : F \rightarrow \mathbb{R}$ be a linear functional over $F$ that is positive over $K \cap F$, i.e., $\phi(y) \geq 0 \;\; \forall \;\; y \in K \cap F$  Then, there exists a linear functional,
 $$\psi : E \rightarrow \mathbb{R}$$
such that,
\begin{align}
	\psi(x) &= \phi(x) \;\; \forall \;\; x \in F \\
	\psi(y) &\geq 0 \;\; \forall \;\; y \in K
\end{align}	
\end{theorem}

\begin{theorem}[\bf Riesz-Markov\footnote{The statement is adapted from \cite{reed1980functional}, Theorem IV.14, and the preceding remarks on the one-to-one correspondence of Baire measures and regular Borel measures.},\cite{reed1980functional}] 
\label{thm:rieszmarkov}
Let $X$ be a compact Hausdorff space and assume that $\psi : C (X) \rightarrow \mathbb{R}$  is a continuous linear functional over $C(X)$, the space of functions continuous on $X$. Assume further that $\psi(\cdot)$ is positive over $C(X)$, i.e., 
\begin{equation}
	\psi(f) \geq 0 \;\;  \forall \;\; f \in C(X) \, : \, f(x) \geq 0 \;\;\forall \;\; x \in X
\end{equation}		
Then, there exists a unique regular Borel measure $\mu (\cdot)$ such that,
\begin{equation}
	\psi(f) = \int_X f(x) \, \mathrm{d} \mu(x) 
\end{equation}
\end{theorem}

\begin{theorem}[\bf B.L.T., \cite{reed1980functional}] 
\label{thm:BLT}
Suppose $T:V_1 \rightarrow V_2$ is a bounded linear transformation from a normed linear space $\langle V_1, ||\cdot||_1\rangle$ to a complete normed linear space $\langle V_2, ||\cdot||_2\rangle$. Then, $T$ can be uniquely extended to a bounded linear transformation (with the same bound), $\tilde{T}$, from the completion of $V_1$ to $\langle V_2, ||\cdot||_2\rangle$. 
\end{theorem}

\begin{proposition}
[\bf Stone-Weierstrass (consequence), \cite{reed1980functional}] 
\label{thm:stoneweierstrass}
The polynomials are dense in $C[a,b]$, the space of real-valued functions continuous over the interval $[a,b]$, for any finite real number $a < b$.
\end{proposition}

\measureextension*
\begin{proof}
Let $F := \mathbb{P}_{1,d} $ be the vector space of 1D polynomials of degree at most $d$, $E = \mathbb{P}_{1,\infty}:= \mathbb{R}[x]$, the space of 1D polynomials with real coefficients of any finite degree and,
\begin{equation}
	K := \left \{ p \in  \mathbb{P}_{1,\infty} \, : \, p(x) \geq 0 \;\; \forall \;\; x \in [-1,1]  \right \}
\end{equation}	
be the cone of 1D polynomials of any finite degree positive on $[-1,1]$. We first demonstrate that,
$$ E = K+F$$
Indeed, given $p \in E$, let $h(x) \equiv \min_{x \in [-1,1]} p(x) > -\infty$. This constant polynomial is well-defined since continuous functions reach their extrema over compact sets. Further, $h \in F$ since $F$ contains the constant polynomials by definition. Finally, the function,
\begin{equation}
	p(x) - h(x) = p(x) - \min_{x \in [-1,1]} p(x) \geq 0 \;\; \forall \;\; x \in [-1,1]
\end{equation}
by construction, which implies that $p-h \in K$. Since this holds for every element $p$ of $E$, this demonstrates the claim.

Now, consider the following family of linear functionals over $F$: for every $i=1,..., D$ and $q = \sum_{k=0}^d q_k \,x^k \in F$ define,
\begin{equation}
	\phi_i (q(x_i)) :=  \sum_{n_i=0}^d   q_{n_i}  \, \mu_{i,n_i}.
\end{equation}
Note in particular that: $ \phi_i (x_i^{n_i}) = \mu_{i,n_i}$. We claim that each functional is positive on $F \cap K$. Indeed, assume $q$ is also positive, i.e., $q \in F \cap K$. Then, by Theorem \ref{thm:fekete}, there exists polynomials $f \in \mathbb{P}_{D,d}$ and $g \in \mathbb{P}_{D,d-1}$ such that,
\begin{align}
	\phi_i (q(x_i)) &= \phi_i \left (f^2(x_i) + (1-x_i^2) \, g^2(x_i) \right )\\
     &= \sum_{m_i=0, n_i=0}^d f_{m_i} f_{n_i} \, \phi_i(x^{m_i+n_i}) + \sum_{m_i=0, n_i=0}^{d-1} g_{m_i} g_{n_i} \, \phi_i( (1-x_i^2) \, x^{m_i+n_i}) \\
     &= \sum_{m_i=0, n_i=0}^d f_{m_i} f_{n_i} \, \mu_{i,m_i+n_i} + \sum_{m_i=0, n_i=0}^{d-1} g_{m_i} g_{n_i} \, \left  (\mu_{i,m_i+n_i} - \mu_{i,m_i+n_i+2} \right ) \\
	 &= f^T \, \mathcal{M}_d ( \mu_i ) \, f + g^T \,  \mathcal{M}_{d-1} ( \mu_i;(1-x_i^2) )   \, g \\
	 & \geq 0
\end{align}
where the last inequality follows by assumption since $\mathcal{M}_d ( \mu_i ) \succeq 0$ and $\mathcal{M}_{d-1} ( \mu_i; \, 1-x_i^2 )$ for every $i$. Therefore, $\phi_i()$ are positive functionals on $F \cap K$ and thus satisfies the hypothesis of the Riesz extension theorem (Theorem \ref{thm:rieszextension}). This implies that for each $\phi_i(\cdot)$ there exists an extension $\psi_i : E \rightarrow \mathbb{R} $ that is positive on $K$. 

Now, recall that $E$ corresponds to $\mathbb{P}_{1,\infty}$ which is a dense subspace of the space $C[-1,1]$ of functions continuous on $[-1,1]$ by Theorem \ref{thm:stoneweierstrass} (Stone-Weierstrass). For each $i$, we can therefore invoke the B.L.T. theorem (Theorem \ref{thm:BLT}) with $\psi_i(\cdot)$ a linear transformation from the normed space $\langle \mathbb{P}_{1,\infty}, \lvert \lvert \cdot \rvert \rvert_\infty \rangle$ to the normed space $\langle \mathbb{R}, \lvert \cdot \rvert \rangle$. In this way, we can assume w.l.o.g. that,
$$\psi_i : C([-1,1]) \rightarrow \mathbb{R}$$
is a continuous linear functional defined over the entire space $C([-1,1])$ and positive over the cone of continuous functions positive on $[-1,1]$. 

Under these conditions, the Riesz-Markov theorem (Theorem \ref{thm:rieszmarkov}) implies the existence of unique regular Borel measures $\{\mu_i (\cdot)\}$ supported on $[-1,1]$ such that,
\begin{equation}
	 \mu_{i,n_i} = \phi_i (x_i^{n_i}) = \int_{[-1,1]} x_i^{n_i} \, \mathrm{d} \mu_i (x_i)
\end{equation} 
where $\mu_{i,0}  =1$. 

Finally, it follows as a consequence of Caratheodory theorem (see, e.g., \cite{}, Theorem 5.1.3) that there exists a unique regular product measure,
$$\mu(\cdot) = \prod_{i=1}^D \mu_i(\cdot)$$
with moments, 
\begin{equation}
	 \mu_n  =  \int_{[-1,1]^D} x^n \, \mathrm{d} \mu(x)   =  \prod_{i=1}^D \, \int_{[-1,1]} x_i^{n_i} \, \mathrm{d} \mu_i (x_i) = \prod_{i=1}^D \mu_{i,n_i}, \; 0 \leq n_i \leq d,
\end{equation} 
and the constraints $\mu_{i,0} = 1 \, \forall \, i$ further imply that
\begin{equation}
    \mu_n([-1,1]^D) = \prod_{i=1}^D \mu_{i}([-1,1]) = \prod_{i=1}^D \mu_{i,0} = 1 
\end{equation}
which proves the desired result. \\
\end{proof}

We now introduce some quantities that will prove important for the remainder of the proof. For $0 < L \in \mathbb{N}$, define 
% $\mathcal{C}_L$ to be the convex polytope,
%     \begin{equation}
%         \mathcal{C}_L := \left \{ \alpha \in \mathbb{R}^L \; : \; \sum_{l=1}^L \alpha_l = 1,\, 0 \leq \alpha_l \leq 1  \; \forall \; l \right \}
%     \end{equation}
and $\mathcal{F}_L$ and $\mathcal{S}_L$ to be,
\begin{align}
     \mathcal{F}_L &:= \left \{ \mu_n:= \sum_{l=1}^L \prod_{i=1}^D \mu_{i, n_i}^{(l)}   \, : \, \{\mu_i^{(l)} \}_{i,l=1}^{D,L} \in \mathbb{R}^{D \times (d+1) \times L},\,   \lvert n \rvert \leq d, \, \mathcal{M}_d(\mu^{(l)}_i), \, \mathcal{M}_{d-1}(\mu^{(l)}_i ; (1-x_i^2)) \succeq 0 \; \forall \, i,l, \, \mu_{0} = 1 \right  \} \\
     \mathcal{S}_L &:= \left \{ \mu(\cdot) := \sum_{l=1}^L \prod_{i=1}^D  \mu_i^{(l)} (\cdot)  \, :  \,  \mu^{(l)}_i (\cdot) \in \mathbb{B}_1  \; \forall \; i,l, \, \mu\left( [-1,1]^D \right ) = 1\right \} 
\end{align}
