\begin{corollary}
    \label{cor:equivproblem}
    Consider the problems,
    \begin{equation}
    \label{eq:problemmoments}
        \min_{ \mu \in \mathcal{F}_L }   \sum_{ n \in \mathrm{supp}(p)} \, p_n \left ( \sum_{l=1}^L  \prod_{i=1}^D \mu^{(l)}_{i,n_i} \right ) 
    \end{equation}
    and,
    \begin{equation}
        \label{eq:problemmeasure}
        \min_{ \mu(\cdot) \in \mathcal{S}_L } \; \int p(x) \, \mathrm{d} \left (  \sum_{l=1}^L  \prod_{i=1}^D \mu^{(l)}_i (x_i) \right ).  
    \end{equation}
    Then, the following holds:
    \begin{enumerate}
        \item Both problem share the same global minimum value. 
        \item $ \mu(\cdot) \in \mathcal{S}_L$ corresponds to a global minimum of Problem \ref{eq:problemmeasure} if and only if $ \zeta(\mu(\cdot)) \in \mathcal{F}_L$ corresponds to a global minimum of Problem \ref{eq:problemmoments}.
        \item If $ \mu \in \mathcal{F}_L$ corresponds to a local minimum of Problem \ref{eq:problemmoments}, then any element of the non-empty set $\zeta^{-1}(\mu) \in \mathcal{S}_L$ consists of local minima of Problem \ref{eq:problemmeasure}.
    \end{enumerate}
\end{corollary}

\begin{proof} 
First, note that the objective functionals satisfies,
\begin{align}
    \label{eq:invfunc}
    \int p(x) \, \mathrm{d} \left(\sum_{l=1}^L  \prod_{i=1}^D \mu_i(x_i) \right ) &=  \sum_{n \in \mathrm{supp}(p)} \, p_n \left (  \left [  \zeta \left(\sum_{l=1}^L  \prod_{i=1}^D \mu_i(\cdot) \right )  \right ]_{n} \right ) 
     % \sum_{n \in \mathrm{supp}(p)} \, p_n \left ( \sum_{l=1}^L  \prod_{i=1}^D \mu^{(l)}_{i,n_i} \right ) \\
\end{align}
by definition. This implies that $ \mu^*(\cdot) \in \mathcal{S}_L$ is a global minimum of Problem \ref{eq:problemmeasure} if and only if $\mu^* := \zeta(\mu^*(\cdot))$ is be a global minimum of Problem \ref{eq:problemmoments}. Indeed, if a point in $\mathcal{F}_L$ achieves a strictly lower value, than any point belonging to the pre-image of that point under $\zeta(\cdot)$  (which is non-empty by surjectivity. See Proposition \ref{prop:eqsets}) then a lower value is achievable and vice-versa. This is a contradiction and demonstrates the first two points.

For the third point, consider a local minimum $\mu \in \mathcal{F}_L $. Let $\mu(\cdot)\in \mathcal{S}_L $ be any element of the pre-image of this local minimum under $\zeta(\cdot)$, i.e., $\mu(\cdot) \in    \zeta^{-1} \left (  \mu \right )  $ which is non-empty thanks to surjectivity. Since $\mu$ is a local minimum, there exists an open neighborhood $\mathcal{N}$ of $\mu$ in $\mathcal{F}_L$ where the functional may only achieve values that are either greater than or equal to the current value. Consider the set,
\begin{equation}
     \zeta^{-1} (\mathcal{N}) \subset \mathcal{S}_L
\end{equation}
which is open and constains $\zeta^{-1} \left (  \mu \right )$ since $\zeta(\cdot)$ is continuous and surjective. From the invariance of the functional value (Eq.\eqref{eq:invfunc}), it follows that every element of this set must lead to a value in Problem \ref{eq:problemmeasure} that is either greater than or equal to the current value, i.e., the set $\zeta^{-1} (\mu ) $  must consist of local mimina of Problem \ref{eq:problemmeasure}. This proves the third claim.
\end{proof}

\equivalence*
\begin{proof}
First, note that $\mathcal{F}_L$ is in a trivial bijective correspondence with feasible set of Problem \ref{eq:reformulationcontinuous}. Then, following Corollary \ref{cor:equivproblem}, it suffices to consider the problem,
\begin{align}
    \min_{\mu(\cdot) \in \mathcal{S}_L}\; \int_{[-1,1]^D} p(x) \, \mathrm{d} \left(\sum_{l=1}^L \, \prod_{i=1}^D \mu_i(x_i) \right )
\end{align}
We claim that the optimal value $\pi^*$ of this problem (and thus that of Problem Problem \ref{eq:reformulationcontinuous}) equals,
\begin{equation}
    \min_{x \in [-1,1]^D} \, p(x)
\end{equation}
To see why, let $x^* \in [-1,1]^D$ be an optimal location (which exists since $p(x)$ is continuous and $[-1,1]^D$ is compact) and note that,
\begin{equation}
    \prod_{i=1}^D \delta(\cdot - x_i^*)
\end{equation}
where $\delta(\cdot)$ is a point (delta) measure centered at the origin, belongs to $\mathcal{S}_L$. Therefore, we find that,
\begin{equation}
    \pi^* \leq \int_{[-1,1]^D} p(x) \, \prod_{i=1}^D \delta(x_i - x_i^*)  \, \mathrm{d} x = p(x^*) =  \min_{x \in [-1,1]^D} \, p(x)
\end{equation}
Then, consider the fact that,
\begin{align}
    \label{eq:equivmin_upperbound}
    \int_{[-1,1]^D} &p(x) \, \mathrm{d} \left(\sum_{l=1}^L \prod_{i=1}^D \mu_i(x_i) \right ) \\
    &\geq \left ( \min_{x \in [-1,1]^D} \, p(x)  \right ) \, \int_{[-1,1]^D} \mathrm{d} \left ( \sum_{l=1}^L \prod_{i=1}^D \mu^{(l)}_{i}(x_i) \right )  = \min_{x \in [-1,1]^D} \, p(x)
\end{align}
for every element of $\mathcal{S}_L$. Taking the infimum over $\mathcal{S}_L$ on both sides imply that,
\begin{equation}
    \pi^* \geq \min_{x \in [-1,1]^D} \, p(x)
\end{equation}
which together with Eq.\eqref{eq:equivmin_upperbound} imply that,
\begin{equation}
    \pi^* = \min_{x \in [-1,1]^D} \, p(x)
\end{equation}
as claimed.
\end{proof}

\begin{proposition}
    \label{prop:descentmeasure}
    % Consider the set $\mathcal{S}_2$ which may be written as,
    % \begin{align}
    % 	 \left \{ \left ( \{ (\mu^{(0)}_i(\cdot),\mu^{(1)}_i(\cdot)) \}_{i=1}^D, \, (\alpha, 1-\alpha) \right )   : \; \mu^{(0)}_i(\cdot), \mu^{(1)}_i(\cdot) \in \mathbb{B}_1\; \forall \; i, \, 0 \leq \alpha \leq 1 \right \}.
    % \end{align}
    % %     where $\mathbb{B}([-1,1])$ is the set of 1D Borel measures with support contained within $[-1,1]$. 
    % Let $p \in \mathbb{P}_{D,\infty}$. 
    % If an element of $\mathcal{S}_2$ is not a
    Consider an element of $\mathcal{S}_2$ of the form,
        \begin{equation}
           \mu^{(0)}(\cdot)  +  \mu^{(1)}(\cdot ) :=  \prod_{i=1}^D \mu_i^{(0)}(x_i)  +  \prod_{i=1}^D \mu_i^{(1)}(x_i)
        \end{equation}
    Assume such element is not a global minimum of the problem,
    \begin{equation}
            \min_{ \mu(\cdot) \in \mathcal{S}_2}\; \int p(x) \, \mathrm{d} \left( \prod_{i=1}^D \mu_i^{(0)}(x_i)  + \prod_{i=1}^D \mu_i^{(1)}(x_i) \right ).
    \end{equation}
    Then, if either 1) $\mu^{(0)}\left (  [-1,1]^D \right )  \in \{0,1\}$, or 2) $\mu^{(0)}\left (  [-1,1]^D \right ) \in (0,1)$ and,
    \begin{equation}
       \frac{1}{\mu^{(0)}([-1,1]^D) } \, \int p(x) \, \mathrm{d}  \mu^{(0)}(x) \not =  \frac{1}{\mu^{(1)}([-1,1]^D) } \, \int p(x) \, \mathrm{d}  \mu^{(1)}(x),
    \end{equation}
    there exists a path $\pi(t)$, $t \in [0,1]$ lying entirely in $\mathcal{S}_2$ and originating from this point along which $\int p(x) \, \mathrm{d} \pi(t)(x)$ monotonically decreases.
\end{proposition}
\begin{proof}
Consider a sub-optimal element $\mu(\cdot)$ of $\mathcal{S}_2$ of the form,
\begin{equation}
    \mu(\cdot) =  \mu^{(0)}(\cdot) +  \mu^{(1)}(\cdot) = \prod_{i=1}^D \mu^{(0)}_i(\cdot) +   \prod_{i=1}^D \mu^{(1)}_i(\cdot).
\end{equation}
From Theorem \ref{thm:equivalence}, we know that the optimal value is given by,
\begin{equation}
     \min_{x \in [-1,1]^D} p(x) = p(x^*)
\end{equation}
for some $x^* \in [-1,1]^D$. Therefore, sub-optimality implies that,
\begin{equation}
    \int p(x) \, \mathrm{d} \mu(x) > p(x^*)
\end{equation}
We consider two cases: 1) the case where $\mu^{(0)}\left (  [-1,1]^D \right ) \in \{0,1\}$ and 2) the case where $\mu^{(0)}\left (  [-1,1]^D \right ) \in (0,1)$.\\


\noindent
{\bf Case 1:} $\mu^{(0)}\left (  [-1,1]^D \right ) \in \{0,1\}$\\
Assume w.l.o.g. that $\mu^{(0)}\left (  [-1,1]^D \right ) = 1$, so that $\mu(\cdot) = \prod_{i=1}^D \mu^{(0)}_i(\cdot)$.  Consider the measure,
\begin{equation}
    \delta(\cdot - x^*) = \prod_{i=1}^D \delta(\cdot - x_i^*) .
\end{equation}
where $\delta(\cdot)$ is a point (delta) measure supported at the origin. Now, consider the parametrized path,
\begin{equation}
    \pi(t) := \prod_{i=1}^D \pi^{(0)}_{i} (t) + \prod_{i=1}^D \pi^{(1)}_{i} (t) 
\end{equation}
where,
\begin{align}
	\pi^{(0)}_{i} (t) &:= (1-t)^{1/D}  \,  \mu^{(0)}_{i}(\cdot) \\
 	\pi^{(1)}_{i} (t) &:= t^{1/D}\, \delta (\cdot - x_i^*) \\
\end{align}
for $t \in [0,1]$. In particular, note that this path starts at $ \pi(0) = \mu^{(0)}(\cdot) = \mu(\cdot)$. We further claim that this path lies entirely in $\mathcal{S}_2$ and that the objective monotonically decreases along it. To see why this is so, first note that $\delta(\cdot - x_i^*) \in \mathbb{B}_1$ for all $i$ by construction, and $\mu_i^{(0)}(\cdot) \in \mathbb{B}_1$ for all $i$ by assumption. Then, substitute to get,
\begin{align}
    \pi(t) =   (1-t) \, \prod_{i=1}^D \mu_i^{(0)}(\cdot) + t \prod_{i=1}^D \delta(\cdot - x_i^*)  
\end{align}
and note that,
\begin{align}
	& \pi(t)([-1,1]^D) = \left ( \prod_{i=1}^D \pi^{(0)}_{i} (t) + \prod_{i=1}^D \pi^{(1)}_{i} (t) \right ) ([-1,1]^D) =  (1-t) + t = 1,
\end{align}
for all $t \in [0,1]$, which implies that $\pi(t)$ belongs to $\mathcal{S}_2$ as claimed. For the second part of the claim, consider the functional value along the path, namely,
\begin{align}
  \int p(x) \; \mathrm{d}\pi(t)(x) &=  (1-t)\,  \int p(x) \, \mathrm{d} \mu^{(0)}(x) + t\,  \int p(x)\, \delta(x - x^*) \, \mathrm{d}x \\
 &= \int p(x) \, \mathrm{d} \mu^{(0)}(x) + t\, \left ( \int p(x) \, \delta(x - x^*) \, \mathrm{d}x  - \int p(x) \, \mathrm{d} \mu^{(0)}(x) \right )
\end{align}
This implies that,
\begin{equation}
    \frac{d}{d\, t} \, \int p(x) \; \mathrm{d}\pi(t)(x) =  p(x^*) -  \int p(x) \, \mathrm{d} \mu^{(0)}(x) < 0
\end{equation}
since $\int p(x) \, \mathrm{d} \mu^{(0)}(x) > p(x^*)  $ by assumption of sub-optimality. This demonstrates monotonic decrease of the functional along the path as claimed.\\


\noindent
{\bf Case 2:} $\mu^{(0)}\left (  [-1,1]^D \right ) \in (0,1)$. 

Let,
\begin{equation}
    \alpha := \mu^{(0)}\left (  [-1,1]^D \right ).
\end{equation}
Under our hypothesis, one can assume w.l.o.g. that,
\begin{equation}
    \label{eq:descent_case2}
  \frac{1}{1-\alpha} \, \int p(x) \, \mathrm{d} \mu^{(1)}(x) < \frac{1}{\alpha} \, \int p(x) \, \mathrm{d} \mu^{(0)}(x) .
\end{equation}
Again, consider a parametrized path $\pi(t)$, $t\in[0,1]$ such that,
\begin{align}
	   \pi(t) :=   \prod_{i=1}^D \pi^{(0)}_{i} (t) +  \prod_{i=1}^D \pi^{(1)}_{i} (t) 
\end{align}
where,
\begin{align}
	\pi^{(0)}_{i} (t) & =  \left ( 1 - t \right )^{1/D} \, \mu_{i}^{(0)}(\cdot) \\
	\pi^{(1)}_{i} (t) &= \left( 1 + t \, \frac{\alpha}{1-\alpha} \right )^{1/D} \, \mu_{i}^{(1)} (\cdot)
\end{align}
for $t \in [0,1]$, which begins at $ \pi(0) = \alpha \,\mu^{(0)}(\cdot) + (1-\alpha) \, \mu^{(1)}(\cdot) =  \mu(\cdot)$. We claim that this path lies entirely in $\mathcal{S}_2$ and that the objective monotically decreases along it. Indeed, $\mu_{i}^{(0)}(\cdot), \, \mu_{i}^{(1)}(\cdot) \in \mathbb{B}_1$ for every $i$ by assumption. In addition,
\begin{align}
    \pi(t) =   (1-t) \, \prod_{i=1}^D \mu^{(0)}_i (\cdot) +   \left (1 + t \, \frac{\alpha}{1-\alpha} \right )  \, \prod_{i=1}^D \mu_i^{(1)} (\cdot)
\end{align}
which implies that
 \begin{align}
	\pi(t)([-1,1]^D) &=  (1-t) \, \alpha  +  \left (1 + t\, \frac{\alpha}{1-\alpha} \right ) \, (1-\alpha)\\
	 &= \alpha +  (1-\alpha)  - t\, \alpha + t \alpha \\
    &= 1
 \end{align}
for all $t \in [0,1]$. This shows that $\pi(t)$ belongs to $\mathcal{S}_2$ as claimed. Finally, we have that the functional value along the path is,
\begin{align}
	  \int p(x) \, \mathrm{d} \pi (x)  &=  \int p(x) \, \mathrm{d} \left ( (1-t) \, \mu^{(0)}(x) +  \left(1+    t \,  \frac{\alpha}{1-\alpha} \right)\,  \mu^{(1)}(x) \right )\\
	  &=   \int p(x) \, \mathrm{d}  \mu^{(0)} (x) +   \int p(x) \, \mathrm{d} \mu^{(1)}  (x)  \\
   &+ t\, \alpha \, \left ( \frac{1}{1-\alpha} \, \int_{\mathbb{R}^D } p(x) \, \mathrm{d}  \mu^{(1)}  (x) - \frac{1}{\alpha} \, \int_{\mathbb{R}^D } p(x) \, \mathrm{d}\mu^{(0)}(x)  \right )
\end{align}
which has derivative,
\begin{equation}
   \frac{d}{dt} \int p (x)\, \mathrm{d} \pi(t)(x)  = \alpha \, \left (  \frac{1}{1-\alpha} \, \int_{\mathbb{R}^D } p(x) \, \mathrm{d} \mu^{(1)}(x) -  \frac{1}{\alpha} \, \int_{\mathbb{R}^D } p(x) \, \mathrm{d} \mu^{(0)}(x) \right ) < 0
\end{equation}
since $0 < \alpha < 1 $ and by assumption (Eq.\eqref{eq:descent_case2}). This proves the statement in the second case.
\end{proof}

\begin{corollary}
    \label{cor:descentmeasure}
    Under the hypotheses of Proposition \ref{prop:descentmeasure}, an element of $\mathcal{S}_2$ of the form,
    \begin{equation}
      \mu^{(0)}(\cdot) +   \mu^{(1)}(\cdot)  :=  \prod_{i=1}^D \mu^{(0)}_i(\cdot) +  \prod_{i=1}^D \mu^{(1)}_i(\cdot) 
    \end{equation} 
    is a global minimum of,
    \begin{equation}
        \min_{ \mu(\cdot) \in \mathcal{S}_2 }\, \int p(x) \, \mathrm{d} \left (    \prod_{i=1}^D \mu_i^{(0)}(\cdot) +  \prod_{i=1}^D \mu^{(1)}_i(\cdot)   \right ) 
    \end{equation} 
    if and only if either of $\frac{1}{\alpha^{(0)}} \, \prod_{i=1}^D \mu^{(0)}_i(\cdot)$ or $\frac{1}{\alpha^{(1)}} \, \prod_{i=1}^D \mu^{(1)}_i(\cdot)$ is itself a local minimum, where $\alpha^{(j)} := \prod_{i=1}^D \mu^{(j)}_i([-1,1])$.
\end{corollary}

\begin{proof}
    First, note that if either of $\mu^{(0)} (\cdot) := \prod_{i=1}^D \mu^{(0)}_i(\cdot)$ or $\mu^{(1)} (\cdot) := \prod_{i=1}^D \mu^{(1)}_i(\cdot)$ achieve the value of a local minimum, then we can invoke Case 1) of Proposition \ref{prop:descentmeasure} (i.e., $\mu^{(0)} \left( [-1,1]^D \right ) \in \{0,1\}$) which implies that there exists a descent path from that point or that the measure is a global minimum. Since it is a local minimum by assumption, there cannot be a feasible descent path originating from that point and it is therefore a global minimum.

    Next, assume the measure is a global minimum with global minimum value $p^*$. If $\mu^{(0)} \left( [-1,1]^D \right ) \in \{0,1\}$ the non-trivial summand must be a local minimum. Otherwise, $\mu^{(0)} \left( [-1,1]^D \right ) \in (0,1)$ and Proposition \ref{prop:descentmeasure} implies that,
    \begin{equation}
        \label{eq:measure_equal_val}
        \frac{1}{\alpha^{(0)}} \, \int p(x) \, \mathrm{d} \prod_{i=1}^D \mu^{(0)}_i(x) =  \frac{1}{\alpha^{(1)}} \,\int p(x) \, \mathrm{d} \prod_{i=1}^D \mu^{(1)}_i(x) 
    \end{equation}
    for without an equality, this corresponds to Case 2) of Proposition \ref{prop:descentmeasure} and there must exists a descent path, which is a contradiction to local optimality. Eq.\eqref{eq:measure_equal_val} then implies that,
    \begin{align}
        p^* &= \int p(x) \, \mathrm{d} \left (  \prod_{i=1}^D \mu^{(0)}_i(x)  +   \prod_{i=1}^D \mu^{(1)}_i(x)\right )  \, \mathrm{d} x\\
        &= \frac{1}{\alpha^{(0)}} \, \int p(x) \, \mathrm{d} \prod_{i=1}^D \mu^{(0)}_i(x) 
    \end{align}
    and similarly for $\prod_{i=1}^D \mu^{(1)}_i(x) $. Thus, we find that both product measures achieve the optimal value and must be themselves global (and therefore local) minima, which proves the claim.
\end{proof}

