\subsubsection{Tree decompositions}
Tree decompositions are closely related to minor theory and can often be used for algorithm design.
        \begin{definition}[{Tree decomposition}\cite{ROBERTSON1986309}]
            A tree decomposition $(T,\beta)$ of a graph $G=(V,E)$ consists of a tree $T$ and a mapping $\beta:V(T)\to2^{V(G)}$ that maps every node in $T$ to a subset of $V(G)$ such that:
            \begin{itemize}
                \item $\bigcup_{t\in T}\beta(t)=V(G)$
                \item $\forall uv\in E, \exists t\in T$ such that $u,v\in \beta(t)$
                \item $\forall v\in V$, $\{t\in T|v\in \beta(t)\}$ induces a subtree in $T$.
            \end{itemize}
            \label{deftw}
        \end{definition}
        The \textit{width} of a tree decomposition $(T,\beta)$ is $\max_{t\in T} |\beta(t)|-1$, and the \textit{treewidth} of a graph $G=(V,E)$, denoted as $\textsf{tw}(G)$, is the minimum width over all possible tree decompositions of $G$. For each $k\in \mathbb{N}^+$, the graph class of all graphs with treewidth no greater than $k$ is defined to be $\mathcal{TW}_k=\{G|\textsf{tw}(G)\le k\}$. For $t\in T$, the \textit{torso} of $G$ at $t$ is $G_t=(\beta(t),E_t)$, where $E_t=\{uv\in E|u,v\in \beta(t)\}\cup \{uv|u,v\in \beta(t), \exists dt\in T, u,v\in \beta(d)\}$.

        A tree decomposition is called a \textit{normal tree decomposition} if for each $dt\in T$, neither $\beta(t)\subseteq \beta(d)$ nor $\beta(d)\subseteq \beta(t)$ holds.

        \begin{lemma}
        A normal tree decomposition can be obtained from an arbitrary tree composition $(T,\beta)$ in $O(|T|^2|G|)$ time.
        %If $s,t\in T$ and $\beta(s)=\beta(t)$, then for $d\in T$ on the path between $s,t$, $\beta(t)\subseteq \beta(d)$ by the third property in the definition. Furthermore, i
            \label{lemnormaltree}
        \end{lemma}

        \begin{proof}
            If $dt\in T$ and $\beta(t)\subseteq \beta(d)$, by contracting $dt$ to $w$ we get another tree $T'$ . We also define a mapping $\beta':V(T')\to 2^{V(G)}$ such that $\beta'(w)=\beta(d)$ and $\beta'(s)=\beta(s)$ when $s\neq w$. It can be verified that $(T',\beta')$ also forms a tree decomposition. Deciding whether there exists such $dt$ requires $O(|T||G|)$ time while contracting $dt$ requires $O(1)$ time. Since the number of edges in the tree is bounded by $|T|$, we can obtain a normal tree decomposition in $O(|T|^2|G|)$ time by recursions. 
        \end{proof}

        The size of a normal tree decomposition is bounded:

        \begin{lemma}
        For a normal tree decomposition $(T,\beta)$ of $G$, $|T|\le |G|$. 
            \label{lemsizebound}
        \end{lemma}
        \begin{proof}
            For a leaf $l\in T$, there is an edge $lt\in T$. Since $(T,\beta)$ is a normal tree decomposition, $\beta(l)\nsubseteq \beta(t)$ and there is at least one vertex $v_l\in \beta(l)$ such that for each $d\in T-l$, $v_l\notin \beta(d)$. After deleting $l$ from $T$, $(T-l,\beta)$ is also a normal tree decomposition of $G'\subseteq G$ satisfying $V(G')\subseteq V(G)-v_l$. This procedure can be done recursively with at least one vertex in $G$ deleted in each round, which yields $|T|\le |G|$.
        \end{proof}
