   \begin{lemma}
       For all $i\in\{g,-\},j\in\{a,-\},k\in\{3,+\}$,
       $$\textsf{p}_{ij+}\le \textsf{p}_{ij3},\textsf{p}_{iak}\le \textsf{p}_{i-k},\textsf{p}_{gjk}\le \textsf{p}_{-jk}$$
       \label{lattice}
   \end{lemma}
   A number of significant theorems and algorithms pertaining to these parameters have also been identified:
   \begin{theorem}[\cite{thilikos2022killing}]
       $\textsf{svg} \preceq \textsf{p}_{ga+},\textsf{p}_{ga3}\preceq \textsf{svg}$.
       \label{thmmtotw}
   \end{theorem}
   By combining Lemma \ref{lattice} with Theorem \ref{thmmtotw}, we obtain the following corollary:
   \begin{corollary}
       $\textsf{svg} \sim \textsf{p}_{ga+}\sim \textsf{p}_{ga3}$.
   \end{corollary}
   Furthermore, for a graph $G$, if $\textsf{svg}(G)$ is given, then the corresponding tree decomposition with bounded $ga3$-width can be constructed in polynomial time:
   \begin{theorem}[\cite{thilikos2022killing}]
       For a graph $H$ which is a minor of $H_k$ and a graph $G$, in $O(f(k)\cdot|G|^3)$ time where $f(k)$ is some computable function, we can find either the fact that $H$ is a minor of $G$, or alternatively a tree decomposition $(T,\beta)$ of $G$ whose $ga3$-width is less than $c(k)$, where $c(k)$ is some computable function that depends only on $k$. 
    \label{K7trde}
   \end{theorem}
     A \textit{single crossing graph} is defined as a graph that can be embedded on the plane with at most one crossing. Such graphs exhibit the following property:
     \begin{theorem}[\cite{curticapean2014counting}]
   For a single crossing graph $H$,  there exists a constant $c$ such that for all graphs $G\in fb(\{H\})$, $\textsf{p}_{--3}(G)\le c$. Furthermore, a tree decomposition with $--3$-width less than $c$ can be found in $O(|G|^4)$. 
   \label{K5trde}
       %For a graph $H$ that can be embedded on the plane with at most one crossing, which can be referred to as a single crossing graph, there exists a constant $c$ such that for all graphs $G\in fb(\{H\})$, $\textsf{p}_{--3}(G)\le c$. 
   \end{theorem}




\subsection{Counting problems}\label{preCSP}
    %This article studies counting problems over a Boolean domain, where variables can only take values in $\{0,1\}$. 
      For a string $\alpha=\alpha_1\dots\alpha_k \in \{0,1\}^k$, the \textit{Hamming weight} of $\alpha$ is the number of $1$s in $\alpha$, denoted as $HW(\alpha)$. We use $\overline{\alpha}$ to denote the string that differs from $\alpha$ at every bit, which means $\alpha_i+\overline{\alpha}_i=1$ for each $1\le i\le k$. A \textit{signature}, or a \textit{constraint function}, is a function $f:\{0,1\}^k \to\mathbb{C}$, where $k$ is the \textit{arity} of $f$.  A signature $f$ is said to be \textit{symmetric} if the value of $f$ depends only on the Hamming weight of the input string. A symmetric signature $f$ of arity $k$ can be denoted as $[f_0,f_1,...,f_k]_k$, or simply $[f_0,f_1,...,f_k]$ when $k$ is clear from the context. Here, for $0\le i\le k$, $f_i$ is the value of $f$ when the Hamming weight of the input string is $i$. For $c\in \mathbb{C}$, we also use the notation $c[f_0,f_1,...,f_k]$ to denote the signature $[cf_0,cf_1,...,cf_k]$. We use $\leq_T$ and $\equiv_T$ to respectively denote polynomial-time Turing reduction and equivalence. 

     We denote by $f^{x_i=c}$ the signature that pins the $i$th variable to $c\in\{0,1\}$:

     $$f^{x_i=c}(x_1,...,x_{i-1},x_{i+1},...,x_{k})=f(x_1,...,x_{i-1},c,x_{i+1},...,x_{k})$$

     For a string $\alpha\in \{0,1\}^q, q\le k$, we also define $f^\alpha=f^{x_1=\alpha_1,x_2=\alpha_2,...,x_q=\alpha_q}$, where $\alpha_i$ is the $i$th bit of $\alpha$ for $1\le i\le q$. That is, $f^\alpha$ is obtained from $f$ by pinning the first $q$ bits of $f$ to $\alpha_1,...,\alpha_q$. Equivalently speaking, $\alpha$ can be seen as an assignment to the $q$ variables $\alpha:\{1,\dots,q\}\to \{0,1\}$. In the case of a slight overuse, the notation $f^\alpha$ is sometimes employed to indicate the signature by pinning specific $q$ bits of $f$ to $\alpha_1,...,\alpha_q$ when the $q$ bits are clear from the context. 

     In this article, we mainly focus on two frameworks of counting problems: the counting constraint satisfaction problem and the Holant problem.

     \subsubsection{\#CSP problems}
       A \textit{counting constraint satisfaction problem} $\text{\#CSP}(\mathcal{F})$ \cite{creignou2001complexity} requires the value of an instance, which is the sum of the values over all configurations. Here, $\mathcal{F}$ is a fixed and finite set of signatures. An instance of $\text{\#CSP}(\mathcal{F})$ is specified as follows:

      \begin{definition}
            An \textit{instance $I$ of $\text{\#CSP}(\mathcal{F})$} has $n$ variables and $m$ signatures from $\mathcal{F}$ depending on these variables. The value of the instance then can be written as

        $$Z(I)=\sum_{(x_1,...,x_n)\in \{0,1\}^n}\prod_{1\le i\le m} f_i(x_{i_1},...,x_{i_k})$$
        where $f_1,\dots,f_m$ are signatures in $I$ and $f_i$ depends on $x_{i_1},...,x_{i_k}$ for each $1\le i\le m$.
          \label{defCSP}
      \end{definition}
       %A \textit{configuration} of $I$ is an assignment of the values of all the variables. \textit{The value of a configuration} is the product of the values of all the signatures in the instance under the assignment.
        The \textit{underlying graph} of a $\text{\#CSP}(\mathcal{F})$ instance $I$ is a bipartite graph $G=(U,V,E)$, where for every constraint $f$ there is a $u_f\in U$, for every variable $x$ there is a $v_x\in V$, and $(u_f,v_x)\in E$ if and only if $f$ depends on $x$. We remark that the treewidth of $G$ is also denoted as the  incidence treewidth of $I$, and in this article when we refer to treewidth, we always mean incidence treewidth\footnote{In contrast,  a graph $G'=(V,E)$  can also be obtained from a $\text{\#CSP}(\mathcal{F})$ instance $I$, where for every variable $x$ there is a $v_x\in V$, and $(v_x,v_y)\in E$ if and only if they appear together in the scope of a constraint. The treewidth of such $G'$ is denoted as the primal treewidth of $I$, which is of independent interest and will not be used in this article.}. Sometimes we also denote the value $Z(I)$ as $Z(G)$ for convenience. If each constraint function in $\mathcal{F}$ is restricted to be symmetric, we denote this kind of problem as symmetric \#CSP, or sym-\#CSP for short. 

        If we restrict the maximum degree of the vertices in $U\cup V$ to be no more than a constant $k$, we denote this kind of problem as \textit{bounded degree} \#CSP, or \textit{maximum degree} $k$ \#CSP.  If we restrict the maximum degree of the vertices in $V$ to be no more than a constant $D$, this kind of problem is denoted as $\#R_D$-CSP in \cite{cai2014complexity}.
        As $\mathcal{F}$ is finite, the maximum arity of signatures in $\mathcal{F}$ is also finite, and we denote this integer as $k$. Consequently, the maximum degree of the vertices in $U$ is no more than $k$ as well. As result, by these definitions we have the following lemma.
        \begin{lemma}
        Suppose the maximum arity of signatures in $\mathcal{F}$ is $k$. For each integer $D\ge1$,

        $$\text{maximum degree } D \text{ \#CSP}(\mathcal{F})\le_T \#R_D\text{-CSP}(\mathcal{F})$$
        $$\#R_D\text{-CSP}(\mathcal{F}) \le_T \text{maximum degree } \max{(k,D)} \text{ \#CSP}(\mathcal{F})$$
            \label{RD=bounded}
        \end{lemma}

        \subsubsection{Holant problems}
        A \textit{Holant problem} $\text{Holant}(\mathcal{F})$ can be seen as a $\text{\#CSP}(\mathcal{F})$ problem with the restriction that all the variables must appear exactly twice. 

        \begin{definition}
        An instance of $\text{Holant}(\mathcal{F})$ has an underlying graph $G=(V,E)$. Each vertex $v\in V$ is assigned a signature from $\mathcal{F}$ and each edge in $E$ represents a variable.  Here, $\mathcal{F}$ is a fixed set of signatures and usually finite. The signature assigned to the vertex $v$ is denoted as $f_v$. An assignment of $E$ is a mapping $\sigma:E\to \{0,1\}$, which can also be expressed as an assignment string $\sigma\in \{0,1\}^{|E|}$, and the value of the assignment is defined as
         $$\omega(\sigma)=\prod_{v\in V} f_v(\sigma)$$
        where $f_v(\sigma)=f_v(\sigma({e_{v_1}}),...,\sigma({e_{v_k}}))$ and $v$ is incident to $e_{v_1},...,e_{v_k}$.
        \par The output of the instance, or the value of $G$, is the sum of the values of all possible assignments of $E$, denoted as:
        $$Z(G)=\sum_{\sigma\in \{0,1\}^{|E|}}\omega(\sigma)$$ 
            \label{defHol}
        \end{definition}

        Similarly, if each signature in $\mathcal{F}$ is restricted to be symmetric, we denote this kind of problems as symmetric Holant, or sym-Holant for short. If we restrict the maximum degree of the vertices in $V$ to be no more than a constant $k$, we denote this kind of problems as \textit{bounded degree }Holant or \textit{maximum degree }$k$ Holant. 

        Furthermore, we use $\text{Holant}(\mathcal{F}_1|\mathcal{F}_2)$ represents $\text{Holant}(\mathcal{F}_1\cup \mathcal{F}_2)$ with the restriction that the underlying graph $G=(U,V,E)$ is bipartite, and each vertex $u\in U$ is assigned a signature from $\mathcal{F}_1$ while each vertex $v\in V$ is assigned a signature from $\mathcal{F}_2$.
         We denote by $\mathcal{EQ}$ the set of all equality functions. In other words, $\mathcal{EQ}=\{=_k|k\ge1\}$ where $=_k$ is the signature $[1,0,...,0,1]_k$. We also denote $\{=_k|1\le k\le D\}$ by $\mathcal{EQ}_{\le D}$ for each integer $D\ge 1$.  
         By definition, we have the following lemma. 
         \begin{lemma}
         Let $\mathcal{C}$ be an arbitrary graph class, $\mathcal{F}$ be an arbitrary signature set and $D\ge 1$ be an integer. Then,

             $$\text{\#CSP}(\mathcal{F})\langle \mathcal{C}\rangle\equiv_T\text{Holant}(\mathcal{F}|\mathcal{EQ})\langle \mathcal{C}\rangle$$ 
              $$\#R_D\text{-CSP}(\mathcal{F})\langle \mathcal{C}\rangle\equiv_T\text{Holant}(\mathcal{F}|\mathcal{EQ}_{\le D})\langle \mathcal{C}\rangle$$ 
             \label{lemcsp=hol}
         \end{lemma}


         Besides, standard \#PM is exactly $\text{Holant}(\{[0,1,0,...,0]_k|k\in \mathbb{N}^+\})$. Suppose that $G=(V,E)$ is a graph with each vertex of degree $k$ assigned $[0,1,0,...,0]_k$. For each  assignment $\sigma$ of $E$, $\omega(\sigma)$ can only be either 0 or 1 since the value of each signature can only provide a multiplier with value 0 or 1. Furthermore, $\omega(\sigma)=1$ if and only if all edges assigned the value 1 form a perfect matching of $G$. Consequently, we have \#PM$(G)=Z(G)$. In addition, by exchanging 0 and 1, standard \#PM can also be expressed as $\text{Holant}(\{[0,...,0,1,0]_k|k\in \mathbb{N}^+\})$. Similarly, \#PM is exactly $\text{Holant}(\{[0,...,0,1,0]_k|k\in \mathbb{N}^+\}|\{[1,0,c]|c\in \mathbb{C}\})$ since $\{[1,0,c]|c\in \mathbb{C}\}$ is capable of expressing the weight of each edge.


      Suppose that $E'\subseteq E$, $\tau$ is an assignment of $E'$ and $\sigma$ is an assignment of $E$. If for any $e\in E'$, $\sigma(e)=\tau(e)$, then we say $\sigma$ is an extension of $\tau$, denoted by $\sigma\rhd \tau$. This notation can also be extended to strings, as an assignment can be seen as an input string for the instance. The value of $\tau$ is defined as:

        $$\omega(\tau)=\sum_{\sigma\rhd \tau}\omega(\sigma)$$
        We also define an instance of $\text{Holant}(\mathcal{F})$ with underlying graph $G^\tau=(V,E-E')$. For each vertex $v\in G^\tau$, if $f_v$ is assigned to $v$ in $G$, then the signature $f_v^{\tau_v}$ is assigned to $v$ in $G^\tau$, where $\tau_v$ is the assignment of all edges incident to $v$ and belong to $E'$, satisfying $\tau\rhd \tau_v$ . By definition, we have:

        $$Z(G^\tau)=\omega(\tau)$$
       The value of $G$ can also be written as follows:

        $$Z(G)=\sum_{\sigma\in \{0,1\}^{|E|}}\omega(\sigma)=\sum_{\tau\in \{0,1\}^{|E'|}}\sum_{\sigma\rhd \tau}\omega(\sigma)=\sum_{\tau\in \{0,1\}^{|E'|}}Z(G^{\tau})$$

        This form implies the following lemma:
        \begin{lemma}
            Suppose that $G=(V,E)$ is an instance of $\text{Holant}(\mathcal{F})$ and each vertex $v\in V$ is assigned a signature from $\mathcal{F}$. Let $E'\subseteq E$ with $|E'|\le c$, where $c$ is a constant. If for arbitrary $\tau\in \{0,1\}^{|E'|}$, $Z(G^{\tau})$ can be computed in polynomial time, then $Z(G)$ can be computed in polynomial time.
            \label{exhaustsum}
        \end{lemma}





\subsection{Reduction methods}
This section presents three kinds of common methods used in reductions in counting complexity.

\subsubsection{Constructing gadgets}

  A \textit{gadget} of $\text{Holant}(\mathcal{F})$ has an underlying graph $GG=(V,E,D)$, where $E$ is the set of normal edges and $D$ is the set of edges with only one endpoint, called \textit{dangling edges} \footnote{In order to differentiate from the notation of a graph, we use two capital letters to represent a gadget.}. Each vertex in $GG$ is still assigned a signature from $\mathcal{F}$. A signature $f$ of arity $|D|$ is said to be \textit{realized} by $GG=(V,E,D)$, if for each assignment $\alpha : D \to \{0,1\}$, $f(\alpha)=Z(GG^{\alpha})$. In this case, we also say $f$ can be realized by $\mathcal{F}$. Similarly to Lemma \ref{exhaustsum} we have:

        \begin{lemma}
            Suppose $c$ is a constant and $GG=(V,E,D)$ is a gadget of $\text{Holant}(\mathcal{F})$ with $|D|\le c$. If for arbitrary  $\tau : D \to \{0,1\}$, $Z(GG^{\tau})$ can be computed in polynomial time, then the signature realized by $GG$ can be computed in polynomial time.
            \label{exhaustgad}
        \end{lemma}
        By constructing gadgets with existing signatures, we are able to realize desired signatures.

        \begin{lemma}
            If $f$ can be realized by $\mathcal{F}$, then $$\text{Holant}(\mathcal{F})\equiv_T\text{Holant}(\mathcal{F}\cup\{f\})$$  
        \end{lemma}

        Also, we present some derivative concepts related to the concept of a gadget. A \textit{left-side gadget} of $\text{Holant}(\mathcal{F}_1|\mathcal{F}_2)$ has a bipartite underlying graph $GG=(U,V,E,D)$, where each vertex $u\in U$ is assigned a signature from $\mathcal{F}_1$, each vertex $v\in V$ is assigned a signature from $\mathcal{F}_2$, $E$ is the set of normal edges and $D$ is the set of dangling edges. Furthermore, the endpoint of each dangling edge must belong to $U$. It is easy to verify that, if $f$ can be realized by $GG$, then $\text{Holant}(\mathcal{F}_1|\mathcal{F}_2)\equiv_T\text{Holant}(\mathcal{F}_1\cup\{f\}|\mathcal{F}_2)$. The \textit{right-side gadget} is defined similarly except that the endpoint of each dangling edge must belong to $V$.

        Besides, for a graph $G=(V,E)$ and $V'\subseteq V$, a \textit{gadget induced by} $V'$ is a gadget $GG=(V',E_{V'},D_{V'})$, where $E_{V'}=\{uv\in E|u,v\in {V'}\}$ and $D_{V'}$ contains a dangling edge connecting to $u\in {V'}$ for each edge in $\{uv\in E|u\in {V'},v\in V-{V'}\}$.  

        \subsubsection{Polynomial interpolation}

 Another crucial technique for proving $\text{\#P}$-hardness of a problem is polynomial interpolation. This method usually involves the construction of a series of gadgets, which are used to simulate a specific signature. For example, we can prove the following lemma through this method:
        \begin{lemma}
            Suppose that there is a sequence of signatures $f_1,f_2,...,f_k,...$, where $f_k=[1,0,f(k)]$ and $f:\mathbb{N}^+\to \mathbb{C}$ is a computable function satisfying $f(i)\neq f(j)$ whenever $i\neq j$. If for each $k\in \mathbb{N}^+$, $f_k$ can be realized by a gadget $GG_k$ of $\text{Holant}(\mathcal{F})$ of size $poly(k)$, then for any $c\in\mathbb{C}$, 

            $$\text{Holant}(\mathcal{F}\cup\{[1,0,c]\})\le_T\text{Holant}(\mathcal{F})$$
        \label{interp}
        \end{lemma}
        \begin{proof}
            For any instance $G$ of $\text{Holant}(\mathcal{F}\cup\{[1,0,c]\})$, suppose that the signature $[1,0,c]$ appears $n$ times in $G$. For an instance $G_x$ obtained by replacing every $[1,0,c]$ signature in $G$ with $[1,0,x]$, where $x$ can be seen as a variable, $p(x)=Z(G_x)$ forms a polynomial of $x$ of degree at most $n$. We now construct an instance $G_k$ of  $\text{Holant}(\mathcal{F})$ for each $1\le k\le n$ by replacing every $[1,0,c]$ signature in $G$ with a gadget $GG_k$. As $GG_k$ is of size $poly(k)$, the size of $G_k$ is of size $poly(n)$ for each $k$. $Z(G_k)$ can be computed for each $1\le k\le n$ by using the oracle that computes every instance in $\text{Holant}(\mathcal{F})$. By definition, $Z(G_k)=p(f(k))$ for each $1\le k\le n$, and since for each $1\le i< j\le n, f(i)\neq f(j)$, the coefficient matrix is Vandermonde and we can solve the coefficients of $p(x)$ using these equations. As $Z(G)=p(c)$, $Z(G)$ can also be computed.
        \end{proof}
