       \begin{corollary}\label{corointerp}
           Suppose that $a\in \mathbb{C}$ is not a root of unity. If $[1,0,a]$ can be realized by a gadget $GG_1$ of $\text{Holant}(\mathcal{F})$,  then for any $c\in\mathbb{C}$, 

            $$\text{Holant}(\mathcal{F}\cup\{[1,0,c]\})\le_T\text{Holant}(\mathcal{F})$$
       \end{corollary}
       \begin{proof}
           Suppose $LP_k$ is a path of length $k$ and has a dangling edge on each end. If each vertex in $LP_k$ is assigned a $[1,0,a]$ signature, $LP_k$ becomes a gadget of signature $[1,0,a^k]$. Since $a$ is not a root of unity, for each $i,j\in \mathbb{N}^+$ where $i\neq j$, we have $a^i\neq a^j$. Thus by replacing each vertex in $LP_k$ with the gadget $GG_1$, we obtain $GG_k$ satisfying the condition in Lemma \ref{interp}.
       \end{proof}
        \par In the rest part of this article, we sometimes omit the proof of polynomial interpolation if the proof is similar to Lemma \ref{interp}. Instead, we will provide a succinct overview of the proof and highlight the particulars that we should pay attention to.  

\subsubsection{Holographic Transformation}
     Let $T$ be a binary signature, and we denote the two dangling edges corresponding to the input variables of it as a left edge and a right edge. Its value then can be written as a matrix $T=\begin{pmatrix}
          t_{00}&t_{01}\\
          t_{10}&t_{11}
      \end{pmatrix}$, where $t_{ij}$ is the value of $T$ when the value of left edge is $i$ and that of the right edge is $j$.


    This notation is conducive to the efficient calculation of the gadget's value. Let us consider two binary signatures, $T$ and $P$, with the right edge of $T$ connected to the left edge of $P$. $T$ and $P$ now form a binary gadget. Subsequently, it can be demonstrated that the value of the resulting gadget is precisely $TP$, which represents the matrix multiplication of $T$ and $P$.

      For a signature $f$ of arity $n$ and a binary signature $T$, we use $Tf/fT$ to denote the signature ``$f$ transformed by $T$'', which is a signature of arity $n$ obtained by connecting the right/left edge of $T$ to every dangling edge of $f$. For a set $\mathcal{F}$ of signatures, we also define $T\mathcal{F}=\{Tf|f\in \mathcal{F}\}$. Similarly we define $\mathcal{F}T$. The following theorem demonstrates the relationship between the initial and transformed problems: 
      \begin{theorem}[{Holographic Transformation}{\cite{valiant2008holographic,cai2007valiant}}]
          $Holant(\mathcal{F}|\mathcal{G}) \equiv_T Holant(\mathcal{F}T^{-1}|T\mathcal{G})$
          \label{thmHT}
      \end{theorem}
      Let $H_2=\begin{pmatrix}
          1&1\\
          1&-1
      \end{pmatrix}$. For a set of signatures $\mathcal{F}$, we use $\widehat{\mathcal{F}}$ to denote $H_2\mathcal{F}$. As $H_2^{-1}=\frac{1}{2}H_2$, by Theorem \ref{thmHT} we have:

      $$Holant(\mathcal{F}|\mathcal{G}) \equiv_T Holant(\widehat{\mathcal{F}}|\widehat{\mathcal{G}})$$

     We additionally present the following fact as a lemma for future reference.
     \begin{lemma}
         For each $k\ge 1$, $\widehat{=_k}=[1,0,1,0,1,0,\dots]_k$. For example, $\widehat{=_1}=[1,0], \widehat{=_2}=[1,0,1], \widehat{=_3}=[1,0,1,0]$. Consequently, $\widehat{\mathcal{EQ}}= \{[1,0,1,0,1,0,\dots]_k| k\ge 1\}$ and for an integer $D\ge 1$, $\widehat{\mathcal{EQ}_{\le D}}= \{[1,0,1,0,1,0,\dots]_k| 1\le k\le D\}$.
         \label{transEQ}
     \end{lemma}
\subsection{The complexity of \#CSP}\label{sec:precspdicho}
        We begin with the introduction of some special signature sets.
        \subsubsection{Tractable signature sets}
        \begin{definition}
        A signature $f$ with arity $k$ is of \textit{affine type} if it has the form:

        $$\lambda\chi_{AX=b}\cdot \mathfrak{i}^{\sum_{1\le i\le n}a_i{x_i}^2+2\sum_{1\le i< j\le n} b_{ij}x_ix_j}$$
        where $\mathfrak{i}$ denotes the imaginary unit, $a_i,b_{ij}\in\{0,1\},\lambda\in \mathbb{C}$, $AX=b$ is a system of linear equations on $\mathbb{Z}_2$ and
        \begin{equation}
            \chi_{AX=b}=\begin{cases}
                1, & \text{if } AX=b; \\
                0, & \text{otherwise}.\notag
            \end{cases}
        \end{equation}
        \par $\mathscr{A}$ denotes the set of all the signatures of affine type.
        \label{defA}
    \end{definition}
       \begin{definition}
        A signature $f$ is an $\mathcal{E}$\textit{-signature} if it has value 0 except for 2 complementary supports. A signature $f$ with arity $k$ is of \textit{product type} if it can be expressed as a tensor product of $\mathcal{E}$-signatures.

        \par $\mathscr{P}$ denotes the set of all the signatures of product type.
         \label{defP}
    \end{definition}
\subsubsection{Permutable matchgate signatures}
Permutable matchgate signatures are highly related to the tractable cases in \#CSP$\langle \mathcal{PL}\rangle$. 
 \begin{definition}
          A matchgate is a planar graph $G=(V,E)$ with weighted edges $w:E\to \mathbb{C}$, and together with some external nodes $U\subseteq V$ on its outer face labeled by $\{1,2,...,|U|\}$ in a clockwise order. The signature $f$ of a matchgate $G$ is a Boolean signature of arity $|U|$ and for each $\alpha\in \{0,1\}^{|U|}$,

          $$f(\alpha)=\#PM(G-X),$$
          where $X\subseteq U$ and a vertex in $U$ with label $i$ belongs to $X$ if and only if the $i$th bit of $\alpha$ is 1.
          %In other words, if each vertex in $G$ of degree $k$ is assigned $[0,1,0,...,0]_k$, $f(\alpha)=Z(G^\alpha)=\#PM(G-X)$.
          \par A signature $f$ is a matchgate signature if it is the signature of some matchgate.
           $\mathscr{M}$ denotes all the matchgate signatures.
          \label{defMG}
      \end{definition}

\begin{definition}
    Suppose $f$ is a signature of arity $n$. For a permutation $\pi\in S_n$, we use $f_\pi$ to denote the signature

$$f_\pi(x_1,\dots,x_n)=f(\pi(x_1),\dots,\pi(x_n))$$
If for each $\pi\in S_n$, $f_\pi$ is a matchgate signature, we say $f$ is a permutable matchgate signature.

We use $\mathscr{M}_{P}$ to denote the set of all the permutable matchgate signatures.
\label{def:MP}
\end{definition}

The following properties can be easily verified.
  \begin{lemma}\label{lemPin}
        If $f$ is a permutable matchgate signature of arity $k$, then for arbitrary $1\le p\le k$ and $\alpha\in \{0,1\}^p$, $f^\alpha$ is also a permutable matchgate signature.
    \end{lemma}
\begin{lemma}
        A symmetric matchgate signature is also a permutable matchgate signature.
    \end{lemma}
    Matchgate signatures can be simulated in polynomial size.
      \begin{lemma}[\cite{cai2013matchgates}]
          A matchgate signature of arity $k$ can be realized by a matchgate with at most $O(k^4)$ vertices, which can be constructed in $O(k^4)$ time.
          \label{lemMG}
      \end{lemma}

    If a signature $f$ takes only non-zero values on supports with even/odd Hamming weight, we say $f$ is of \textit{even/odd parity}. Furthermore, a signature $f$ is said to satisfy the \textit{parity condition} if it is of either even or odd parity. It can be easily verified that the parity condition is closed under tensor production and taking self-loops, and thus closed under gadget construction. In other words, if $f$ is the signature of the gadget $GG$, and each vertex in $GG$ is assigned a signature satisfying the parity condition, then $f$ also satisfies the parity condition. 

    Since graphs with an odd number of vertices have no perfect matching, all matchgate signatures satisfy the parity condition. Furthermore, by the construction in \cite[Proposition 6.1 and 6.2]{valiant2008holographic}, we have the following lemma:

\begin{lemma}
    If a signature $f$ of arity $k\le 3$ satisfy the parity condition, then $f$ is a permutable matchgate signature.
    \label{MG<3}
\end{lemma}


    Permutable matchgate signatures are also characterized in detail in \cite{meng2025matchgate}. A \textit{star gadget} is a gadget $ST$ formed by a signature $h$ of arity $n$, and $n$ binary signatures $b_1,\dots,b_n$ where for each $1\le j\le n$, $b_j$ is connected to the $j$th variable of $h$. $h$ is denoted as the \textit{central signature} of $ST$ and $b_j$ is denoted as the \textit{$j$th edge signature}. Figure \ref{fig:stargad} presents the star gadget.
\begin{figure}
            \centering
            \includegraphics[height=0.2\textheight]{stargad.png}
            \caption{The star gadget. Each edge incident to the vertex of degree $k$, represented by a square, is also incident to a vertex of degree 2 represented by a circle.}
            \label{fig:stargad}
        \end{figure}
 \begin{lemma}\label{lem:SymGadRealize}
    Each permutable matchgate signature $f$ of arity $n$ can be realized by a star gadget, where the center signature is a symmetric matchgate signature and each edge signature is a binary matchgate signature. 
\end{lemma}

\begin{lemma}\label{lem:AsymtoSym}
    For each signature $F\in \mathscr{M}_P-\mathscr{A}$ of arity $n$, a symmetric signature $g\in \mathscr{M}_P-\mathscr{A}$ can be realized by $\{F\}\mid\{[1,0],[1,0,1],[1,0,1,0]\}$ as a planar left-side gadget.
\end{lemma}

\subsubsection{Previous dichotomies for \#CSP}


      The existing dichotomies for \#CSP can be stated as follows:  
\begin{theorem}[\cite{cai2014complexity}]
        If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$, $\text{\#CSP}(\mathcal{F})$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.
        \label{genCSP}
    \end{theorem}

\begin{theorem}[\cite{cai2014complexity}]
        Suppose $D\ge 3$ is an integer. If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$, $\#R_D\text{-CSP}(\mathcal{F})$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.
        \label{genRDCSP}
    \end{theorem}



    \begin{theorem}[\cite{cai2017holographicuni,meng2025matchgate}]\label{plCSP}
        If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$ or $\mathcal{F}\subseteq \widehat{\mathscr{M}_P}$, $\text{\#CSP}(\mathcal{F})\langle \mathcal{PL}\rangle$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.    
    \end{theorem}
\begin{theorem}[\cite{meng2025matchgate}]\label{plRDCSP}
    Suppose $D\ge3$ is an integer. If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$ or $\mathcal{F}\subseteq \widehat{\mathscr{M}_P}$, $\#R_D$-CSP$(\mathcal{F})\langle \mathcal{PL}\rangle$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.
\end{theorem}
 At last we present an algorithm result for \#CSP with bounded treewidth from \cite{ganian2018sum}. In the following theorem, \textsf{dom} denotes the size of the domain, \textsf{sup} denotes the maximum size of support in $\mathcal{F}$, $\textsf{tw}^*$ denotes the maximum incidence treewidth and $|I|$ denotes the size of the instance. Furthermore, \#CSPD is a generalized version of \#CSP.

    \begin{theorem}[\cite{ganian2018sum}]
     \#CSPD can be solved in time $(\textsf{dom} +\textsf{sup}+1)^{O(\textsf{tw}^*)}|I|$.
    \label{incidence}
\end{theorem}

In the setting of this article, $\textsf{dom}=2$ and $\textsf{sup}$ is bounded since $\mathcal{F}$ is finite. Consequently,  Theorem \ref{incidence} can induce the following corollary.
   % The function sets $\mathscr{A},\mathscr{P}$ and $\widehat{\mathscr{M}}$ are defined as follows:

   \begin{corollary}[\cite{ganian2018sum}]
      For each $k\in \mathbb{N}^+$, if $\mathcal{F}$ is finite, \#CSP$(\mathcal{F})\langle \mathcal{TW}_k \rangle$ is computable in $c^{O(k)}|I|$ time, where $c$ is only parameterized by $\mathcal{F}$.
    \label{CSPK4}
   \end{corollary}
    Furthermore, since $fb(\{K_4\})=\mathcal{TW}_2$, we have that $\text{\#CSP}(\mathcal{F})[K_4]$ can be computed in linear time for arbitrary finite $\mathcal{F}$. This proves the first statement in Theorem \ref{allthm}.

