\section{An algorithm for bounded degree \#CSP on minor-free graphs}\label{secK7}

In this section, we prove the fourth statement in Theorem \ref{allthm2}, which can be restated as follows.

\begin{theorem}     
   If $\mathcal{G}\cap\mathcal{H}\neq \emptyset$, $\mathcal{G}\cap\mathcal{PL}= \emptyset$, then for any constant $k\in \mathbb{N}^+$, maximum degree $k$ $\text{\#CSP}(\mathcal{F})[ \mathcal{G} ]$ is computable in polynomial time if $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$ or $\mathcal{F}\subseteq \widehat{\mathscr{M}_P}$; otherwise it is $\text{\#P}$-hard. 
    \label{CSPK7}
\end{theorem}

By Lemma \ref{RD=bounded}, the following corollary can be obtained from Theorem \ref{CSPK7}.

\begin{corollary}
    If $\mathcal{G}\cap\mathcal{H}\neq \emptyset$, $\mathcal{G}\cap\mathcal{PL}= \emptyset$, then for any constant $D\in \mathbb{N}^+$, $\#R_D\text{CSP}(\mathcal{F})[ \mathcal{G} ]$ is computable in polynomial time if $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$ or $\mathcal{F}\subseteq \widehat{\mathscr{M}_P}$; otherwise it is $\text{\#P}$-hard. 
\end{corollary}

The fourth statement in Theorem \ref{allthm} can be obtained from Theorem \ref{CSPK7} as $K_7$ is a minor of $H_{18}$ and can not be embedded on the plane \cite{thilikos2022killing}. As $\mathcal{G}\cap\mathcal{PL}= \emptyset$, all planar graphs are $\mathcal{G}$-minor-free. By Remark \ref{remarCSP}, to prove Theorem \ref{CSPK7}, it is sufficient to prove the following lemma.
%%

\begin{lemma}
     \par Suppose that $\mathcal{F}\subseteq \mathscr{M}_P$ and all the signatures in $\mathcal{F}$ are of arity at most $k$, where $k\in \mathbb{N}^+$ is a constant. Then for any graph class $\mathcal{G}$ satisfying $\mathcal{G}\cap\mathcal{H}\neq \emptyset$, there is an algorithm that computes $\text{Holant}(\mathcal{F})[ \mathcal{G} ]$ in polynomial time.
     \label{K7alg}
\end{lemma}
