\ar@{..>}@/^6ex/ [rrrr] ^-{yx}="aw"
&
\ar@{..>} [r] ^{x}="t"
\ar@{..>}@/_6ex/ [rr] _-{z}="ub"
& 
\ar@{..>}[r] ^-{y}="w"
& 
\ar@{..>}[r] _-{\mathsf{r}}="r"
