\subsection{$\learbalance$}
Algorithm~\ref{alg:learbalance_concentration} presents the $\learbalance$ policy, which combines a fixed-duration Explore-Then-Commit (ETC) strategy with the $\balance$ rule for class selection. The algorithm proceeds in two phases. During the exploration phase, which lasts for a fixed number of rounds \( T_{\text{explore}} \), arriving nodes are matched by selecting classes uniformly at random. This allows the algorithm to collect data on the outcomes of triplets \((c, d, m)\), where \(c \in \mathcal{C}\), \(d \in \mathcal{D}\), and \(m\) is the current matching size of the class \(c\). We let \(T_{c,d,m}\) denote the number of times the triplet \((c, d, m)\) has been observed. After this phase, the algorithm enters the commitment phase and uses the collected data to estimate the match failure probabilities. Specifically, it estimates \(D_{c,d}(m) = \left(1 - \frac{a_{c,d}}{N} \right)^{N b_c - m}\) using an estimator \(\hat{D}_{c,d}(m)\), whose form and concentration properties are given in \Cref{theorem:concentrationpowers}. These estimates are then incorporated into the $\balance$ rule to select the class \(c\) that maximizes the expected success probability, weighted by the type distribution \(\nu(d)\).

\begin{algorithm}[ht]
\caption{$\learbalance$ }
\label{alg:learbalance_concentration}
\DontPrintSemicolon
\KwIn{$T$, $\nu(d)$, $N$, $T_{\text{explore}}$, confidence level $\delta$}
\KwOut{Matching $M(t)$}

\textbf{Init:} $\mathcal{M}(0) = \emptyset$, $M_c(0) = 0$, $T_{c,d,m}(0) = 0$, $\hat{D}_{c,d}(m) = 1$\;

\For{$t = 1$ \KwTo $T$}{
    Node $t$ of type $d(t)$ arrives\;

    \uIf{$t \leq T_{\text{explore}}$}{
        Select $c_t$ uniformly at random\;
    }
    \Else{
        \ForEach{$c \in [C]$}{
            Let $m = M_c(t-1)$, $s(m) = \frac{b_c}{b_c - m/N}$\;
            Compute $\hat{D}_{c,d}(m)$ %via weighted avg over $\mathcal{V}_m = \{m' \mid 2m' - m \leq Nb_c\}$. (\Cref{theorem:concentrationpowers})
        }
        Choose $c_t = \arg\max_c \sum_d 1 - \hat{D}_{c,d}(M_c(t{-}1)) \nu(d)$\;
    }

    \uIf{ $ \mathcal{F}_{c_t}(t) \neq \emptyset$ }{
        Match $(n_t,t)$ for $n_t \sim \text{unif}(\mathcal{F}_{c_t}(t))$, update $\mathcal{M}(t)$, $M_{c_t}(t)$, and $Y_{c_t,d(t)}(t) = 1$\;
    }
    \Else{
        No match, $Y_{c_t,d(t)}(t) = 0$\;
    }

    Update $T_{c_t,d(t),M_{c_t}(t)} \gets T_{c_t,d(t),M_{c_t}(t)} + 1$\;
}
\end{algorithm}
\subsection{Regret}
For each class $ i \in \mathcal{C} $, let $ M_i(t) $ and $ \hat{M}_i(t) $ denote the number of matches made by the $\balance$ and $\learbalance$ algorithms, respectively, up to time $ t $. We define the regret of $\learbalance$ as the total difference in matching performance across all classes when compared to $\balance$, which has full knowledge of the match probabilities. In other words, the regret quantifies the cumulative loss incurred by $\learbalance$ due to not knowing the match probabilities in advance. The following result shows that this regret grows at most on the order of $ \mathcal{O}(N^{(q+3)/4}) $ for some $0<q<1$.
%Note that this is not the standard notion of regret from online learning, but rather a benchmark-based comparison against an informed baseline
\begin{restatable}{theorem}{regretetcbalance}\label{theorem:regretetcbalance}
Let $ R(T) = \sum_{i \in \mathcal{C}} M_i(T) - \hat{M}_i(T) $ denote the regret of $\learbalance$. Suppose the exploration phase lasts for $ T_{\text{explore}} = T^{\frac{q+3}{4}} $, for some $ 0 < q < 1 $. Then the regret satisfies
\[
R(T) = \mathcal{O}(T^{\frac{q+3}{4}}).
\]
\end{restatable}

